window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_012"]={"n":"卢龙云","dyn":"明","poems":[{"t":"长歌行","f":"五言古诗","c":["春风动百草，林卉各芳妍。","秋霜入原野，零落难久鲜。","人生百年内，倏若东逝川。","红颜等朝露，旦夕成弃捐。","少壮不相待，老大空自怜。","先民有遗叹，竹帛无所宣。","烱戒事明淑，惜阴慕古贤。"]},{"t":"美女篇","f":"五言古诗","c":["燕赵有佳人，羞作凡家妇。","少心在深闺，步履不轻举。","十三学画眉，十五工织组。","绿鬓整新妆，膏沐时为理。","荆玉镂华簪，大秦珠作珥。","木难间珊瑚，黄金饰翠羽。","佩以青琅玕，罗袂翩翩举。","吐气若兰馨，未为金屋贮。","常恐群芳歇，缅然怀独处。","玉帛将充庭，闻者慕俦侣。","秉尚实自殊，媒氏亦何苦。","愿以金石心，及时配君子。"]},{"t":"古八变歌","f":"五言古诗","c":["凉风起夕吹，白露浥寒霏。","朔雁来天北，越燕辞南归。","蟋蟀鸣四壁，熠耀照我帷。","桐叶满空井，百卉亦具腓。","关河千里外，游子暮何之。"]},{"t":"门有车马客为郭学宪作","f":"五言古诗","c":["凉飙集庭树，炎晖撤广陌。","抚景叹合并，暮类翻离索。","念无心所知，可与陈肝膈。","搔首步前除，忽来车马客。","年齿丈人行，儒雅文章伯。","缱绻叙乡园，酌酒相娱乐。","俯仰聆高谈，意气感今昔。","天子重才贤，求之偏草泽。","出庭固有时，幸兹贤路辟。","繄我万里游，谬忝金闺籍。","萍水尽他乡，缅焉怀所戚。","促膝讵云疲，晤言可终夕。"]},{"t":"怨歌行二首 其一","f":"五言绝句","c":["膏沐徒为理，长宵恨有馀。","罗衣新染泪，明月怨离居。"]},{"t":"怨歌行二首 其二","f":"五言绝句","c":["买赋嗟何及，春风惹恨偏。","楼头看柳色，偷唱想夫怜。"]},{"t":"前有尊酒行为颜使君作","f":"五言古诗","c":["日永晷渐移，午睡梦方觉。","抱膝百虑婴，羁怀渺难托。","感君自高谊，一见等夙昔。","握手共殷勤，吐论本肝膈。","儒雅亦吾师，笑谈皆莫逆。","晤言安可常，相酬屡促席。","尊酒但复盈，客心胡不乐。","人生贵适志，风尘徒役役。"]},{"t":"从军行二首 其一","f":"五言绝句","c":["共赋从军乐，西征未厌劳。","长驱应卷席，杀气薄云高。"]},{"t":"从军行二首 其二","f":"五言绝句","c":["士马来何劲，鸣笳杂鼓声。","远山千队肃，铁骑出龙城。"]},{"t":"王明君二首 其一","f":"七言绝句","c":["掩泪含情出汉宫，胡王见妾喜相逢。","天留薄命教和虏，敢悔当时计未工。"]},{"t":"王明君二首 其二","f":"七言绝句","c":["马上啼痕染别衣，琵琶有恨寸心违。","妾身未怨丹青误，只怪和戎事已非。"]},{"t":"相逢行","f":"五言古诗","c":["长安狭斜路，轩盖日追随。","突如流星转，叱咤成风雷。","拂剑平明去，垂鞭日暮回。","市人皆辟易，言从天上来。","敝裘款段马，平生寡所谐。","虚薄乖时用，中道且徘徊。","顾问何为者，栖栖逐尘埃。","挥手谢时贵，王孙只自哀。","燕诏不可作，孰扫黄金台？"]},{"t":"邯郸才人嫁为厮养卒妇","f":"五言古诗","c":["舍悲辞密亲，零泪忽如雨。","惭愧诸姊妹，各各有处所。","贱妾独何为，吞声谢俦侣。","昔居繁盛时，今作卑微伍。","俛首拜姑嫜，脉脉情难语。","罗绮无复施，铅华不用诩。","引分各所宜，贞心徒自许。","君王若问妾，妾心应自苦。","掖庭佳丽多，故人安足数。"]},{"t":"自君之出矣二首 其一","f":"五言绝句","c":["自君之出矣，何地不堪愁。","明月两乡照，霜寒更入楼。"]},{"t":"自君之出矣二首 其二","f":"五言绝句","c":["自君之出矣，时序速如梭。","雪里春将动，流光一岁过。"]},{"t":"长安道","f":"五言古诗","c":["长安佳丽地，自昔帝王州。","六衢通绣户，九陌夹朱楼。","名花娇上苑，垂杨荫御沟。","宝马如龙度，香车似水流。","往来朝七贵，经过暮五侯。","结束郊畿满，歌舞狭斜留。","赤日应难措，红尘可自由。","试看外州客，频来易白头。"]},{"t":"出塞曲二首 其一","f":"五言古诗","c":["天兵夜度辽，去家几千里。","霜落塞草腓，朔风动地起。","驰突羽林郎，召募良家子。","弓刀各在腰，人人乐殊死。","奋勇争先登，所向应披靡。","长歌早入关，誓将雪国耻。"]},{"t":"出塞曲二首 其二","f":"五言古诗","c":["边城雪初下，都护远从戎。","长驱十万众，直赴青海东。","并抚如霜剑，齐弯似月弓。","兵威连杀气，耿耿贯长虹。","本为怀恩苦，宁知岁月终。","生平暮勋伐，麟阁待书功。"]},{"t":"燕歌行","f":"七言古诗","c":["春风入户燕初飞，柳色方舒花欲辉。","紫陌游人催晓骑，翠楼小妇裁春衣。","夫婿此时轻远别，挥手魂销心百结。","吴刀出匣佩秋霜，宛马连钱嘶汗血。","行行却道赴金河，杖策相看意气多。","三军羽骑欢传箭，六郡良家喜荷戈。","去时娇鸟鸣春早，此日凄风凋塞草。","拟清瀚海博侯封，不怨玉关羁人老。","陇头孤月照连营，想见征夫夜勒兵。","入梦似闻出塞曲，断肠偏送捣衣声。","沙边鸣雁翩翩起，日日思君几千里。","归来应及纪凌烟，丈夫有志报天子。"]},{"t":"艳歌行","f":"五言古诗","c":["荆杨路迢遥，南金久寂寥。","隐者混沙砾，用之等琼瑶。","洛阳发中使，黄金色自骄。","披沙金始见，采择不盈朝。","韫之以桂椟，驰上洛阳宫。","见者莫不叹，问金来何从。","谁能铸镕此，同归大冶中。","珠玉缭绕之，翠羽问陆离。","本是荆杨金，今作后庭辉。"]},{"t":"蜀道难","f":"古风","c":["蜀道难，五丁开。","峻坂千盘度，冲波百丈回。","巫山剑阁高入云，瞿塘滟滪奔如雷。","石栈天梯鸟道出，飞湍挂瀑猿声哀。","蜀道难，不可攀，堪怪世人如走丸。","每闻叱驭往，几见回驭还。","王褒持节山间走，相如拥传里中看。","亦有君平百钱知自足，子云寂寞一枝安。","蜀道难，欲往从之阻且艰。","令人壮志多催残，侧身西望涕汍澜。","世路崄巇皆若此，不似鸿飞冥冥厉羽翰。"]},{"t":"长门怨二首 其一","f":"五言律诗","c":["寂寞掩长门，幽思孰与论。","亦知非妾妒，空自阻君恩。","夜色流萤度，秋声落木翻。","啼痕沾舞袖，偏向箧中存。"]},{"t":"长门怨二首 其二","f":"五言律诗","c":["抱镜朱颜换，承恩忆往时。","委荣伤旧叶，连理出新枝。","明月心堪寄，秋风鬓易丝。","游梁多赋客，或有长卿词。"]},{"t":"妾薄命","f":"五言古诗","c":["结发事君子，所愿永不移。","君王况一顾，承恩上玉墀。","得奉万年觞，奚止共餔糜。","人事有迁改，君心那可知。","蛾眉忽见妒，尘镜隐光仪。","昔为金屋贮，今作玉阶悲。","秋风掩团扇，明月鉴重帷。","促织鸣四壁，珠帘骨网丝。","深宫多乐事，妾自断肠时。","去矣勿复道，时哉待来兹。","安得黄金百，重买长卿词。","君恩谅可续，慰妾长相思。"]},{"t":"苦寒行","f":"五言古诗","c":["黯黯寒云黑，云寒不见月。","天际多悲风，吹落云中雪。","雪花入户来，寒威夜转烈。","牢落客襟单，展转愁怀结。","愁多苦夜长，耿耿待明发。","旭日出东隅，开门扫积雪。","素影流清辉，差可自怡悦。"]},{"t":"君子行","f":"五言古诗","c":["君子防未然，世道险且艰。","谈笑有戈矛，平地生波澜。","众言成市虎，三至惑大贤。","燕石能混璧，野鸟易为鸾。","谁云古达者，不畏嫌疑间。","御寒以重裘，君其善自全。"]},{"t":"乌生曲","f":"古风","c":["乌生八九子，乃在大海旁。","毛羽参差长，俱愿凌穹苍。","相哺桂树里，岂虞缯缴伤。","苦遭秦氏恶少年，弯弓挟弹睨其间。","一发乱乌群，九子相惊看。","各各恋其巢，安得离哉翻。","唶尔少年轻薄子，乌自群飞何负汝！","少年不暇思，反用相矜诩。","昔我臂苍鹰，共逐平原野。","鸟飞不及瞬，尚得攫而食之。","有时牵黄犬，驰骛山间薮。","兔奔不及穴，尚得获而醢之。","机用匪一朝，于乌竟何有。","但明飞伏各自天，无须复欢前与后。"]},{"t":"龙笛曲","f":"古风","c":["嶰谷萧萧绿玉林，佳人截作夜龙吟，珠帘绣户流清音。","流清音，澈洞府。","降列仙，宴王母。"]},{"t":"凤笙曲","f":"古风","c":["高台夹侍董双成，玉管忝差学凤鸣，丛霄吹下几般声。","几般声，悦仙侣。","奉天孙，邀月姊。"]},{"t":"猛虎行","f":"古风","c":["南山深林多虎穴，猛虎噬人时出没。","嗟尔虎胡不仁，驺虞之厚麟振振。","尔独胡为甘食人，咆哮百兽尽辟易。","山家闭门晏未出，往来射猎观行迹。","男儿欲作健，誓寝汝之皮。","昔年白额今安在，除害终看饮羽时。"]},{"t":"有所思","f":"古风","c":["有所思，乃在大海旁。","将何问遗君，明月更夜光。","锦带缭五丝，薰以瑞麟香。","君心闻已变，焚之扬其灰。","思君亦徒尔，覆水难重回。","恩情中道绝，日月有盈亏。","长夜耿耿风凄凄，欲渡无梁当诉谁。"]},{"t":"君黄马","f":"古风","c":["君马黄，臣马赤。","二马并逐臣马力，骥不称力称其德。","游子在天南驾车，驰马力尽伤我心。","居人在天北顿辔，摧轮遥望安终极。"]},{"t":"懊侬歌四首 其一","f":"五言绝句","c":["流苏结合欢，绣被双鸳鸯。","郎去还何日，深闺夜自长。"]},{"t":"懊侬歌四首 其二","f":"五言绝句","c":["出门送郎去，郎心不可住。","南北易销魂，独倚相思树。"]},{"t":"懊侬歌四首 其三","f":"五言绝句","c":["大艑百幅帆，日暮宿江浔。","二日已千里，安不懊侬心。"]},{"t":"懊侬歌四首 其四","f":"五言绝句","c":["估客不知愁，但醉酒家楼。","侬心陇下水，悲咽何时休。"]},{"t":"将进酒郊居作","f":"古风","c":["将进酒，发浩歌。","人生各有欲，随分得天和。","驷马带倾覆，忧患恒苦多。","光阴总付忙里过，花月笑人当奈何。","劝君但醉金叵罗。"]},{"t":"鞠歌行","f":"古风","c":["心扰扰，愿难从，鹿蕉有梦到隍中。","地清切，文似雄，吹嘘无力送河东。","知交少，杂客佣，杵臼之间枉赁舂。","鹰犬疾，豢养丰，举廷惊视彪仪同。","相推毂，早为容，至今惟羡郑司农。"]},{"t":"东光","f":"古风","c":["山寨平，海舶何不平？","大海烟波阔，巨舰鸿毛轻。","乘潮任来往，漂泊转纵横。"]},{"t":"鸡鸣曲","f":"五言古诗","c":["鸡鸣巷陌间，狗吠墟里侧。","刑章戢乱民，里巷方安席。","天下当太平，往事空沾臆。","谁家轻薄儿，昔居豪盛时。","咤叱风云变，意气山岳移。","宝剑千金装，鞍马光陆离。","五侯同盼睐，七贵或低眉。","驱骋洛阳道，调笑酒家胡。","出入常千骑，观者塞道隅。","入门张华灯，琼浆白玉壶。","小姝工赵瑟，大姝美秦竽。","捧觞各上寿，愿保千金躯。","欢乐犹未已，回飙一夕起。","枯蓬离本根，零落从兹始。","枝叶曾蔽亏，各逐东流水。","何况四海人，兄弟能复迩。"]},{"t":"东门行为采珠者作","f":"古风","c":["出东门，欲何之？","丈夫志四海，安效辕下驹。","而况室中无储粟，体上无完衣。","仗剑出门去，不顾儿女悲。","结客场中多侠少，何事牵衣苦别离。","苦别离，寥落荆布妇，呱呱黄口儿。","君慎自爱戒，勿为非国法。","明明谁敢欺。","君慎自爱戒，勿为非国法，明明谁敢欺。","何时当来归，生还但愿同餔麋。"]},{"t":"五杂组","f":"古风","c":["五杂组，道边树。","往复还，无定处。","不获已，老将至。"]},{"t":"白马篇","f":"五言古诗","c":["白马铁连钱，长安侠少年。","仗剑去乡邑，结客多才贤。","名家推六郡，勇略冠三边。","从军出陇右，应募赴河源。","长驱时自负，直捣每争先。","胜算孙吴后，英声卫霍前。","横行绝沙漠，飞渡过祁连。","旌旗摇汉月，笳鼓彻胡天。","久期清瀚海，时欲勒燕然。","旋师歌入塞，奏捷颂甘泉。","岂慕山河赏，惟思竹帛传。","国恩诚欲报，出门谢所牵。","丈夫志四海，岂私儿女怜。"]},{"t":"短歌行","f":"古风","c":["日月其逝，岁不我留。","有酒盈觞，难以解忧。","忧心如焚，迭用悲惧。","春花既陨，夏叶空存。","秋飙入林，木叶萧森。","寒蝉鸣树，感物悲深。","容华易衰，盛时难再。","今我不乐，忽焉改岁。","为乐如何，有酒当歌。","人之云远，别日苦多。"]},{"t":"两头纤纤","f":"七言绝句","c":["两头纤纤波上纹，半黑半白雨中云。","腷腷膊膊柝初闻，磊磊落落酒微醺。"]},{"t":"青青河畔草","f":"五言古诗","c":["青青河畔草，迢迢京洛道。","良人行未归，道远音信稀。","长城万馀里，日暮风沙起。","遥望隔山川，沉忧曷能已。","男儿志四方，贱妾久空房。","功名及盛年，离合讵有常。","客从北道旋，椷书喜为传。","开椷细玩绎，慰我长相忆。","功成当早还，安得久离别。"]},{"t":"子夜四时歌八首 其一","f":"五言绝句","c":["梅柳相将发，桃花色渐殷。","园门终日闭，春意总相关。"]},{"t":"子夜四时歌八首 其二","f":"五言绝句","c":["霏霏陌上烟，漠漠林中雨。","桐叶初满枝，何时见梧子。"]},{"t":"子夜四时歌八首 其三","f":"五言绝句","c":["昼长偏苦熟，凉生过雨时。","屋角添蛛网，日暮更悬丝。"]},{"t":"子夜四时歌八首 其四","f":"五言绝句","c":["逃暑傍曲池，风送荷香入。","倚槛两三花，见莲还未实。"]},{"t":"子夜四时歌八首 其五","f":"五言绝句","c":["凭栏看木落，四壁鸣促织。","天上几七襄，犹恐未成匹。"]},{"t":"子夜四时歌八首 其六","f":"五言绝句","c":["日晚采莲归，轻舟入南浦。","花里觅莲房，可奈心中苦。"]},{"t":"子夜四时歌八首 其七","f":"五言绝句","c":["别多会苦少，有怀当诉谁。","似看灯下局，落落不堪棋。"]},{"t":"子夜四时歌八首 其八","f":"五言绝句","c":["凛凛北风寒，乌鹊树间绕。","展转觉夜长，思君全不晓。"]},{"t":"从军行","f":"五言古诗","c":["男儿重游侠，率苦远从戎。","生平论战略，意气慕边功。","结发随征骑，赌命博侯封。","黑山云作阵，青海月如弓。","大小逾百战，烟沙长被面。","草陨际严霜，蓬断追飞霰。","往来几践更，正奇多合变。","空返鲁阳戈，未定天山箭。","李广自数奇，不及幽并儿。","今年出上谷，明年别月氏。","烽火三边乱，轮辕九折危。","画角中宵起，清笳永夜悲。","边尘犹未灭，坐惜芳菲节。","右地更屯兵，左贤方授钺。","平明候马归，薄暮轻车发。","偏师时合围，骁骑纷驰突。","直捣赴金微，关山度若飞。","玉关如未老，麟阁有光辉。"]},{"t":"鼓吹入朝曲二首 其一","f":"五言古诗","c":["朝廷尊北极，地位切中台。","久虚调焚任，妙选赞襄才。","使者纷相望，徵书蚤下来。","箫鼓川原动，旌麾道路开。","嘉会投鱼水，欢声彻草莱。","严程思侧席，翘首咏康哉。"]},{"t":"鼓吹入朝曲二首 其二","f":"五言古诗","c":["海邦多豪彦，清时共奋庸。","明良欣遇合，宏硕喜登崇。","茅茹逢千载，葵心达九重。","改服戒徒旅，铭勋待鼎钟。","精诚孚帝眷，渥泽起人穷。","缅想曲江侣，双飞羡最雄。"]},{"t":"枯鱼过河泣","f":"五言绝句","c":["枯鱼过河泣，早不慎出入。","寄书谢鲂鲤，悔来那可及。"]},{"t":"东飞伯劳歌","f":"七言古诗","c":["东飞伯劳西飞燕，秦楼楚榭纷相恋。","谁家妖丽可倾城，朱唇皓齿发新声。","美酒十千罗绮食，骏马香车恒络绎。","花貌年年三六馀，宝珥金钿剌绣裾。","一朝离别分南北，意态可怜怀抱恶。"]},{"t":"励俗诗","f":"古风","c":["缅想哲人，弗移于俗。","履洁含贞，卓矣芳躅。","慎修永思，不远而复。","视履考祥，前车戒覆。","主善为师，终始不渝。","时怀靡及，敢玩细娱。","毋荒毋怠，以步以趋。","朝夕匪懈，动与道俱。","如彼农亩，期于必获。","如彼梓材，岂徒朴斲。","是蓘是藨，涂其丹艧。","曾谓伊人，余反不若。","不若惟何，玩愒孔多。","光阴荏苒，岁月虚过。","克念则圣，力岂殊科。","中流一柱，实障颓波。"]},{"t":"悯谗诗","f":"古风","c":["彼苍者天，照临下土。","人之讹言，莫克先睹。","断干单縻，沉舟积羽。","野鸟为鸾，众言成虎。","朝比埙篪，暮若仇虏。","风运铅刀，雷鸣瓦釜。","嗟彼谮人，德輶鲜举。","惟谗罔极，百行胥愆。","卒混苍素，莫辨媸妍。","谓夷匪圣，谓蹠为贤。","措躬无地，防口若川。","于余何罪，视履则旋。","中心自悼，顾影私怜。","悲因抱玉，愁将绝弦。","惟天之命，不爽其应。","始以迹暌，终于实胜。","金石难渝，姜桂有性。","彼昏不知，具曰予圣。","此道其常，厥惟天定。","祸福由人，堪以自镜。","君子闻言，靡惑于听。"]},{"t":"閒居二首 其一","f":"古风","c":["茫茫道路，何时可息。","载驰载驱，不遑自逸。","鸟倦知还，言返我室。","左右图书，长吟抱膝。"]},{"t":"閒居二首 其二","f":"古风","c":["爰居爰处，葆我天和。","衔杯授简，其乐如何。","驷马高盖，忧患孔多。","人亦有言，对酒当歌。"]},{"t":"述祖德八首有引 其一","f":"古风","c":["于穆令祖，贻翼远猷。","启我邦族，溯源分流。","昭穆渐渺，敦叙难周。","于以萃涣，庙貌惟修。"]},{"t":"述祖德八首有引 其二","f":"古风","c":["宋室方乱，各念尔家。","卜宅来宇，在海之涯。","施于孙子，代有国华。","云谁荒度，其功孔嘉。"]},{"t":"述祖德八首有引 其三","f":"古风","c":["胡闰乱华，抗迹遗世。","秉尚伊何，累仁积义。","启佑斯勤，引而勿替。","浚发其祥，承休滋大。"]},{"t":"述祖德八首有引 其四","f":"古风","c":["明德方茂，南粤甫宁。","实兹戎卫，尺籍是兢。","乃疆乃亩，定之宗盟。","黾勉王事，保我后生。"]},{"t":"述祖德八首有引 其五","f":"古风","c":["伍世其昌，逮我王父。","克俭克勤，诗书烈祖。","表正乡闾，回澜砥柱。","责报于天，如携如取。"]},{"t":"述祖德八首有引 其六","f":"古风","c":["仁考绍之，守而勿失。","忠厚传家，数世如一。","岂误儒冠，龙章有秩。","手泽恒存，敢忘嗣述。"]},{"t":"述祖德八首有引 其七","f":"古风","c":["嗟余小子，祗命亲庭。","绎思我祖，先志是承。","爰有堂构，以妥先灵。","以享以祀，明德斯馨。"]},{"t":"述祖德八首有引 其八","f":"古风","c":["戚戚兄弟，念祖攸行。","令仪令德，孰敢不经。","夙兴夜寐，无忝所生。","自求多福，罔坠家声。"]},{"t":"咏史六首 其一","f":"古风","c":["炎德方盛，恭修玄默。","抚下以仁，民无不获。","感春之和，蠲租赐帛。","诽谤既除，土木必惜。","四海阜安，罔罹兵革。"]},{"t":"咏史六首 其二","f":"古风","c":["继体英谊，洞悉闾阎。","赏罚必信，综覈惟严。","横经论决，称制时临。","循良增秩，慰我苍黔。","远夷效顺，海宇熙恬。"]},{"t":"咏史六首 其三","f":"古风","c":["四七之际，烨矣中兴。","首釐冤狱，出系省刑。","日赅朝罢，复引谈经。","却献抑瑞，驰役缓征。","宽仁及下，柔道致平。"]},{"t":"咏史六首 其四","f":"古风","c":["日表龙姿，高出千古。","妙选瀛洲，学舍千庑。","减膳赈饥，恤民疾苦。","谏比韦弦，虚怀罕伍。","睿藻昭宣，经文纬武。"]},{"t":"咏史六首 其五","f":"古风","c":["太平天子，日临讲幄。","赐酺赋诗，与众共乐。","召对群材，激扬清浊。","亲录系囚，惧刑之虐。","罢献五坊，汰侈还朴。"]},{"t":"咏史六首 其六","f":"古风","c":["恭俭之君，四纪如一。","延义迩英，大书无逸。","好生缓刑，惧灾修德。","罢榷蠲逋，库珠助籴。","贪黩必防，罔私山泽。"]},{"t":"赠友人","f":"五言古诗","c":["丈夫志四海，安能自结束。","顾盻生雄风，意气恒相逐。","短褐不完肤，薄糜不充腹。","贫穷遇所安，吾性乃自足。","闭户理典坟，古哲常在目。","天地本为徒，六合纵遐瞩。","乡誉非所荣，独行甘累俗。","寂寞守杨玄，穷途异阮哭。","鲲鹏时负风，瞬息杳云陆。","九万脱榆枋，鴳雀讵同欲。"]},{"t":"将适西粤早发芦沟","f":"五言古诗","c":["自我辞霄汉，行行雪满途。","驱车出广野，迟回恋上都。","初承天子命，新领郎官符。","王事无宁处，严程敢后趋。","五更霜气肃，号寒悯仆夫。","北风利如剑，坚冰正在须。","凄凉向前语，京华贵侠徒。","千金裘自美，日醉酒家胡。","讵念窭人困，敝褐不完肤。","方今宰百里，絮寒饥待哺。","谁知穷檐下，一夫或向隅。","闻者皆叹息，迩言等训谟。","生平慕莘野，不获信予辜。","愿无离苦状，免绘郑公图。"]},{"t":"除夕至淮上","f":"五言古诗","c":["去岁逢除夕，维舟冰满湖。","今岁逢除夕，驱车雨满途。","历涉恒苦辛，寒暑代相徂。","两经淮水渡，怅念旧酒垆。","昔我胡为往，蹑屩三上书。","伏阙遭明主，承恩出帝都。","道路纷相逐，敢比弃繻徒。","自惭千万里，衔命起憔枯。","陈力亮不易，何以慰来苏。"]},{"t":"野泊二首 其一","f":"五言古诗","c":["日暮且维舟，川原浩无极。","宿鸟投深林，疏云过绝壁。","伫立暂彷徨，搔首空叹息。","昨朝辞簿领，今晨远行役。","王事敢云劳，俛仰怀今昔。"]},{"t":"野泊二首 其二","f":"五言古诗","c":["四野何苍茫，客怀方未已。","欲寝不成寐，徘徊揽衣起。","推篷视众星，灿灿临江沚。","萧瑟西风来，吹入群芳里。","秋夜殊未央，所思在万里。"]},{"t":"寿梁丈人","f":"五言古诗","c":["达人负奇尚，幽居任所便。","逍遥恣览历，偃仰息繁喧。","眄彼神仙宅，遗名自葛仙。","羡君居此土，要术得其传。","行年过六十，朱颜发尚玄。","凉风扇吟席，华月临广筵。","称觞迭起寿，从兹逮百年。","山林所以贵，恬澹得自全。"]},{"t":"出邯郸西郭悯荒","f":"五言古诗","c":["驱车出城西，井里太萧索。","寥寥几家村，俛仰但四壁。","鸡犬声不闻，日晏未炊食。","釜甑几生尘，相视无颜色。","烈日更流金，大风走沙石。","岂无百亩宽，其奈千里赤。","壮者行四方，老者守廛陌。","孤妇抱儿号，将为沟中瘠。","我行一见之，涕下忽沾臆。","何以待徵求，无用苦相迫。"]},{"t":"秋怀二首 其一","f":"五言古诗","c":["流景若川逝，秋飙忽复来。","新凉袭户牖，细雨洗烦埃。","残萤照阒寂，落叶舞庭阶。","羁人感物候，四顾郁中怀。","卑栖独抱影，俛仰难自谐。","何当乘风翼，汗漫游八垓。"]},{"t":"秋怀二首 其二","f":"五言古诗","c":["草木渐黄落，春华乃变衰。","旅雁先霜至，寒蛩傍砌悲。","栖栖怜在远，税驾渺难期。","纡怀何所托，飞蓬愁鬓丝。","恨无凌风羽，徘徊将安之。","沉吟以朝夕，百感良在兹。"]},{"t":"赴谪益津留别诸亲友","f":"五言古诗","c":["南陆循修景，朱明丽初节。","恭承兹嘉惠，稽首辞帝阙。","行役本近疆，酌酒重为别。","感往情内劳，抚今念悠结。","昔来冬始寒，风吹马前雪。","及往春既徂，柳长堪攀折。","浓阴覆路蹊，芳草藉蹄辙。","岁序如电奔，缅想愧时哲。","中心难具陈，薄宦良自拙。","愿保崇兰姿，毋俾芳香灭。"]},{"t":"读杨忠悯公集","f":"五言古诗","c":["在昔乘嘉运，深宫事玄默。","天子但垂衣，虚心委贤硕。","谁其负端揆，转为狐鼠窟。","所以节直者，怒发眦为裂。","是时杨职方，尤称铁石肠。","立谈辄太息，颇类戆与狂。","大廷初抗议，流落谪边疆。","赐环未几日，吐论眉转扬。","请剑务诛佞，激烈由天性。","何知逆耳言，叩阍不可听。","屈首就簿责，幽系伤形影。","微臣亦何辜，天王自明圣。","伤哉遘憸壬，甘为虎蟒嗔。","爱憎移生死，烈士乃陨身。","直气元不改，方幸已成仁。","馀作忠魂补，兼以待后昆。","人心自不昧，天心亦可回。","一朝朝论定，殊恩及夜台。","嗣子悯先志，勋业起尘埃。","视彼谮人者，而今安在哉。"]},{"t":"韩烈妇","f":"五言古诗","c":["天地有正气，浩然不可折。","人生天地间，赖此完其节。","彼美兰房质，秉心何壮烈。","结发事夫君，百岁愿同穴。","中道忽乖离，黄鹄伤孤飞。","未明偕老志，何以守空帷。","作嫔儒家日，操行有前规。","真金试烈火，就义死如归。","解化类仙举，气节凌区宇。","生死安足云，身后名千古。","世岂乏男儿，草木同衰腐。","徒自愧须眉，贞魄宁为伍。"]},{"t":"将发益津答王存初勋部时岛夷犯朝鲜","f":"五言古诗","c":["驱车遵海旁，行役出东方。","东风吹海氛，鲸鲵且陆梁。","海邦严斥堠，衣裙袽方长。","念我谪居日，兼隐事篇章。","王事今益我，启处不暂遑。","多谢子相期，弯弓挂扶桑。","儒冠久自误，白面谈岂臧。","王师谅神武，暂往必复康。","济济承明侣，事主毋怠荒。","干羽能服远，海波能久扬。"]},{"t":"守钱五卿使君二首 其一","f":"五言古诗","c":["昔我方守玄，闭门事探讨。","盻睐承辉光，屡许酬嘉藻。","杯酒慰寂寥，为君时倾倒。","一别成参商，长途渺浩浩。","回望霸水头，戚戚伤怀抱。"]},{"t":"守钱五卿使君二首 其二","f":"五言古诗","c":["忆与君别处，春风入新柳。","今日思君时，花落满林薮。","岁月焉可留，千里空回首。","兴至拂瑶琴，公馀呼浊酒。","惜乏赏心人，对景亦何有。"]},{"t":"题莫廷韩所制兰竹图歌后","f":"五言律诗","c":["幽兰与修竹，展图并堪悦。","对竹俗虑消，握兰芳香发。","常与善人居，独持君子节。","更忆长吟者，千岁字不灭。"]},{"t":"度庾岭谒张文献公祠三首 其一","f":"五言律诗","c":["之子挺南服，作相始乡邦。","称诗大历前，于今号盛唐。","诗名与相业，千载并流芳。","眷焉慕先达，风度安可常。"]},{"t":"度庾岭谒张文献公祠三首 其二","f":"五言律诗","c":["白羽明吾志，金鉴为君敷。","道本侔伊吕，言堪等训谟。","唐室方求理，曷自混贤愚。","及尔播迁日，追思亦已徒。"]},{"t":"度庾岭谒张文献公祠三首 其三","f":"五言律诗","c":["遵彼庾关道，开凿念前劳。","长松荫修陆，车马自滔滔。","行者日百里，仗之辟莱蒿。","万古周行在，功方粤岭高。"]},{"t":"侍御王公生祠","f":"五言古诗","c":["皇天祚海濒，法星照南土。","使者天上来，豸冠持绣斧。","雅志在澄清，登车窃自许。","何以惠斯民，极力驱豺虎。","狐鼠亦潜奔，良善赖安堵。","海舶东南来，扬帆称大估。","亡命窜其间，蚁聚江之浒。","但利岛人金，不念居人苦。","索米尽民间，甘心日饷虏。","使君痌切身，未然辄先睹。","内安且外攘，全活真无数。","旱魃间为灾，小民忧百亩。","使君舍鹭车，步行躬祷雨。","甘澍满田园，盈畴复禾黍。","使君按部来，倏历三年所。","三尺自兢兢，惟民曰父母。","廛市无横征，囊箧谁多取。","井里轻薄儿，宁复旧豪举。","沧海有蛟龙，鳅鳝无夜舞。","千仞若鸾凰，鹰隼亦非伍。","使君纳节行，鸣珂入朝庑。","上有稷契邻，下有皋夔侣。","南顾念吾民，何由获爰处。","皇恩谅不次，万方胥镇抚。","简在有辉光，勋业照千古。","野老岁时心，伏谒瞻祠宇。"]},{"t":"经保昌珠玑巷为吾族故里","f":"五言古诗","c":["念载事行役，九度经兹里。","春风桃李开，缅然思故址。","宋室当盛时，居此亦洵美。","田庐广且饶，烽烟净不起。","牛羊日夕来，霞光照山紫。","岁岁看梅花，春事复伊始。","酾酒洽比邻，室迩幸相倚。","世事有变更，大难起宫珥。","玉石恐俱焚，相携并南徙。","我祖见实优，登樵思爰止。","卜宅樵之阳，艰难自疆理。","由宋及盛明，倏逾三十纪。","耕凿慕诗书，贻谋永孙子。","伊余自弱龄，微尚耽图史。","通籍忝朝簪，优游藉先祉。","蹇拙仍滞留，岁月奔如驶。","起家复北游，仗策重经此。","坐恐春华歇，出若山灵耻。","夙昔慕亢宗，抚心良未已。"]},{"t":"都门送袁敬德之任英州二首 其一","f":"五言古诗","c":["去岁珠江湄，别君来帝城。","今岁长安陌，送尔复南行。","丈夫志四海，安惮劳此生。","浈阳风土美，千叠暮山青。","如何能久系，早发入承明。"]},{"t":"都门送袁敬德之任英州二首 其二","f":"五言古诗","c":["新知初握手，相送出城隅。","王程不敢缓，立马能须臾。","念兹非久隔，离颜强自舒。","何时当来还，与子极欢娱。","春风回帝里，游历任所如。"]},{"t":"钱塘观潮","f":"五言古诗","c":["维舟日已暮，坐听浙江潮。","长风吹海岸，落照衔山腰。","潮声一以厉，波光亦复遥。","浩荡豁心目，因之破泬寥。","缅矣怀今昔，盈虚岂一朝。","吴越相雄长，倏忽如迅飙。","髑髅千古恨，一旅耻夫椒。","高台竟游鹿，贞魂讵可招。","怒涛空自托，往事一长谣。","瞬息潮还汐，推篷月可邀。","渔灯互明灭，船头响洞箫。","独客惟杯酒，堪以永今宵。","胡为多苦心，历历认前朝。"]},{"t":"东平行","f":"五言古诗","c":["言慕古东平，卓识异王族。","绮丽非其珍，择善谐所欲。","常恐失丘民，推心广仁育。","归朝承睿问，真乐云自足。","汉室大封建，谁堪缵王服。","之子实维藩，配命求多福。"]},{"t":"西平行","f":"五言古诗","c":["若有西平侯，不冤善为理。","阴德类乃公，仁声相继美。","当其活狱时，私心窃自拟。","我后必有昌，发源从兹始。","再世秉国钧，侯封耀闾里。","驷马驾高车，奕叶流青史。"]},{"t":"周文学膺奖二首 其一","f":"五言古诗","c":["生平秉孤尚，结发游艺林。","玄览极千古，抗志扬徽音。","遘时苦不早，迟暮出云岑。","松柏自有性，芝兰自有心。","黾勉事一职，宁复伤滞淫。","稽古念弥笃，讲诵罗青衿。","片玉世所重，相知日已深。","名藉曹丘起，何言但陆沉。"]},{"t":"周文学膺奖二首 其二","f":"五言古诗","c":["吴楚东南际，贤豪本代兴。","之子挺灵异，匹练应初生。","童龄擅芳誉，弱冠扬徽称。","操瑟竟难合，明经待晚成。","遇我闽海曲，示我郢中声。","训士力崇古，何嫌世俗轻。","游扬渐以广，乘时起令名。","终当策高足，万里扬前旌。"]},{"t":"郑烈妇","f":"五言古诗","c":["结发事君子，止愿同餔糜。","丈夫志万里，一别几经时。","山川修以阻，会面安可知。","妇姑相对守，菽水甘如饴。","多谢邻家妇，测我心所私。","堪恨里中少，谓我心可移。","妾心谅匪石，一死安足辞。","舍生以明志，千载令人悲。"]},{"t":"送梁公益归五羊","f":"五言古诗","c":["自我违乡国，栖栖逐旅尘。","腰肢曾未改，面目强看人。","公事日纷纠，幽绪无由申。","客从远方至，云是故乡亲。","倒衣且迎客，悲喜难具陈。","问客来何所，薄游遵海滨。","江山恣历览，意气念沉沦。","而我滞行役，感君相顾频。","探囊多赋草，翰墨总鲜新。","羡君耽著作，家学相因循。","骚盟递雄长，嗣业踰簪绅。","赠我皆珠玉，炫目豁心神。","于我聊信宿，谈论辟荆榛。","念当从此别，独行良苦辛。","还家逼岁暮，梅花及早春。","沧洲生事足，会有访垂纶。"]},{"t":"喜西征报捷","f":"五言古诗","c":["几日西风急，风前送好音。","西陲今已晏，大慑远人心。","蠢伊匪族类，豺虎而冠衿。","豢养胡为者，反以助骄淫。","重关抱深箐，高垒倚层岑。","兴言抗上国，宁知效献琛。","天子赫斯怒，流毒恐渐深。","授钺开专阃，飞刍集羽林。","去年兴薄伐，行役至于今。","摧坚纷冒石，执锐赴悬金。","哀猿听凄断，毒雾触阴森。","暑雨无咨怨，从军但壮吟。","嗟彼辙中鳞，终焉归釜鬵。","王师幸无敌，馀凶总馘擒。","一方久涂炭，若旱忽沾霖。","还家悲喜集，月下再闻砧。","辕门将振旅，恩赉普颁临。","献俘行赴阙，欢颂侈缨簪。","从兹遍柔远，无为用伐侵。","垂衣受重译，薰风乐舜琴。"]},{"t":"秋晚泊舟洪塘","f":"五言古诗","c":["维舟日将入，微风动晚凉。","坐久江月白，斜辉照我床。","解衣眠伴月，鸣雁天一方。","是时秋已半，沙边苇渐黄。","夜深寒气至，零露当为霜。","感时悲物换，而我在他乡。","三年居此土，毛发日欲苍。","乘潮递来往，谁念客衣裳。","逢迎本自拙，于世亦何妨。","狂飙起天末，愿言保孤芳。"]},{"t":"答黄全之","f":"五言古诗","c":["结发事篇翰，游心竹素园。","一赴公车召，乃自涉烦喧。","中复罹世网，邅回守故樊。","雌伏十馀载，安能凌风翻。","艰危保末路，祗用拙自存。","多君谢尘壒，丘壑道弥尊。","荣名非所宝，诗书日讨论。","八十神逾王，操觚累万言。","眷念同声者，忘年等弟昆。","殷勤几百里，椷寄道寒暄。","而我滞行役，难逢笑语温。","岂不慕高义，何日访衡门。"]},{"t":"夜宿三山禅房漫赋刀剑二首 其一 刀","f":"五言古诗","c":["我有一宝刀，解之欲赠谁。","伊人不可见，佩以善自随。","明时遵海曲，漂泊滞天涯。","刀头似明月，忆我心所私。","操而可使割，应用自有时。","堪叹世间人，笑中亦有之。"]},{"t":"夜宿三山禅房漫赋刀剑二首 其二 剑","f":"五言古诗","c":["匣中有双剑，谁与辨雄雌。","当年解其一，遗我心所知。","双龙久未合，斗光望渐移。","终难授楚柄，聊用强自持。","水陆有二用，何当任所施。","堪笑世间人，腹中亦有之。"]},{"t":"答清源林生","f":"五言古诗","c":["凤凰鸣昆丘，太液奋鸿鹄。","鸒斯蒿下飞，羽翼何局促。","人生各有志，小大随所欲。","古来贤达流，振响遗空谷。","昔余在弱龄，抗志薄时俗。","旅游二十春，蹉跎守雌伏。","南北万里遥，风尘徒仆仆。","燕赵齐鲁墟，周行至海曲。","政简讼还稀，幸不迷按牍。","公暇寡所营，游神辄汗竹。","探讨多会心，俯仰意恒触。","微吟但自舒，何知炫群玉。","羡子志不凡，千古慕芳躅。","匪我平生亲，声气特相属。","持论迥时流，摛文复纷郁。","倾盖义已投，稽疑念弥笃。","寡陋愧前闻，于尔何能淑。","淡交惟若斯，相期善自勖。"]},{"t":"咏怀二首 其一","f":"五言古诗","c":["吏道苦烦促，田野多欢娱。","平生少年日，汎览遍群书。","言论慕古哲，寤寐忆黄虞。","念载事尘役，道路空踟蹰。","意气寡所谐，亲朋日以疏。","风波殊未已，安得骋良图。","不如谢羁勒，息驾返吾庐。"]},{"t":"咏怀二首 其二","f":"五言古诗","c":["端坐怀百忧，愁思当告谁。","荆棘满中道，行者亦云疲。","富贵非所营，贫贱非所移。","越鸟恋故林，游子暮何之。","河清不可俟，得失恒相随。","回车返初服，无为泣路岐。","东皋既息耜，倚杖临清池。"]},{"t":"大中丞戴公考绩","f":"五言古诗","c":["天子念寰㝢，分道出绛绉。","四方值多故，里巷繁诛求。","衮衣觏之子，问俗殚怀柔。","今古两叔伦，威名动遐陬。","三载馀懋绩，飞书上冕旒。","宛如躬召对，喜气溢皇州。","承恩谅不次，臣劳兹可酬。"]},{"t":"杂诗","f":"五言古诗","c":["北风何凛烈，落叶离本根。","山川改气候，黯淡无朝昏。","室人戒裳衣，中庖具盘飧。","闻君将远行，哽咽未能言。","道路多修阻，何日当回辕。","他乡各异俗，谁与共寒暄。","知音不可遇，世态难具论。","山中有藜藿，可以乐衡门。"]},{"t":"李封君兄弟承恩图","f":"五言古诗","c":["余视世间人，岂无兄及弟。","荣瘁间同根，具迩殊廉陛。","式好任埙篪，名实不堪礼。","宦达即齐名，参商逐旅邸。","闽海多贤豪，二老表林皋。","诗书敦夙尚，水石美游遨。","友爱念弥笃，乡闾慕转高。","辞荣乐丘贲，家声起誉髦。","令德宜寿岂，锦衣炫庭綵。","同时荷紫纶，皇恩深若海。","锡服相辉鲜，素澹元无改。","雏驹总凤龙，移忠未休怠。","粤徼已澄清，屏翰出江城。","观风过海岱，齐鲁遍诸生。","风雨对床夜，池塘梦草情。","教仕迭跻膴，黄发逮三旌。"]},{"t":"自乡返城喜春雨沾足兼闻欲罢矿税释建言得罪诸臣","f":"五言古诗","c":["我初返旧疆，原野尚枯赤。","油云忽四兴，甘澍满田泽。","农人相慰欢，举趾盈阡陌。","今年复有秋，卒岁仍有获。","返棹珠江濆，恒情倍自适。","共道圣明朝，燔然悯疾阨。","有诏及闾阎，苛条尽蠲革。","欣跃遍群黎，若旱逢膏液。","造物本无私，皇仁亦自辟。","胥颂圣同天，里巷今安席。","早晚下徵书，岩穴搜贤硕。","伫见东山人，弹冠趋禁掖。"]},{"t":"悯俗","f":"五言古诗","c":["吾慕汉阴人，抱瓮日灌园。","吾嘉河上叟，求珠虑没渊。","时运迭相代，得失难并论。","春花遍桃李，桂树冬转繁。","芳桂自有性，桃李亦何言。","荣枯物所变，大造司其根。","人生何役役，用拙聊自存。"]},{"t":"答友人劝驾","f":"五言古诗","c":["平生丘壑姿，弃置宁复惜。","斥鴳总逍遥，蓬蒿任所适。","鹍鹏不负风，安见垂天翼。","自我返衡茅，方欣脱尘役。","乡里慕少游，烟霞渐成癖。","君复远相期，愿言各努力。","力田当逢年，何但守萝薜。","九万失扶摇，终焉愧善息。","感君慰劳辞，沉思终永夕。","出处亦何常，先民以为则。"]},{"t":"答梁宪父兼约玩月","f":"五言古诗","c":["端居澹物虑，守拙薄浮名。","托交俱翰墨，多擅五言城。","独寡中所谐，谁与竭生平。","体骨难自媚，非关无宦情。","因之谢束缚，言恋我同声。","闭影甘穷巷，扫迹违上京。","蓬如张仲蔚，壁类马长卿。","与君乍相识，彩笔太纵横。","雄篇富磊落，珠玉自分明。","千秋谅已足，安用劳此生。","为君呼斗酒，长宵坐猎缨。"]},{"t":"题宪父山居","f":"五言古诗","c":["天地一蘧庐，无用小吾室。","卜筑远尘嚣，四顾何寥寂。","捲帘面西山，山气佳日夕。","清啸凌烟霞，草木皆生色。","容膝易为安，图书共四壁。","游心六合间，暂兹守泉石。","陈平不久贫，负郭门犹席。","诸葛自草庐，而怀开济策。","诣阙终上书，万里行观国。","且为语山灵，移文未须勒。"]},{"t":"招隐诗二首 其一","f":"五言古诗","c":["达人知止足，功名及盛年。","昔日红颜子，倏忽成华颠。","拙宦不偶世，投绂谢所牵。","碧山宁负我，洞壑生虚烟。","渔钓狎鸥鸟，嘉树荫通川。","于此涤喧浊，因之性所便。"]},{"t":"招隐诗二首 其二","f":"五言古诗","c":["世路常崄巇，驷马带倾覆。","所以慕幽人，偃息在浚谷。","日暮生松风，音响如丝竹。","葵藿分所甘，何必厌粱肉。","布褐足禦冬，狐貉未为燠。","逍遥任所之，无荣亦不辱。"]},{"t":"春雨","f":"五言古诗","c":["好风送时雨，沾润浃荒蓁。","布谷初鸣日，田家事事频。","稚子驱犊出，僯翁唤赛神。","农时不可缓，岁计在于春。","幸免桔槔苦，敢辞东作勤。"]},{"t":"感时二首 其一","f":"五言古诗","c":["四野阴云蔽，狂飙暮凌乱。","清露忽凝霜，卉木皆彫换。","扰扰锥刀子，营营等血汗。","中夜起彷徨，持筹有遗算。","道路多苦辛，豺虎复为患。","念此羁旅人，如何不长叹。"]},{"t":"感时二首 其二","f":"五言古诗","c":["世变类江河，滔滔逝不返。","黔首亦何辜，共恨生逢晚。","伊昔全盛时，宁迩不遗远。","里巷寡诛求，朝作暮息偃。","岁月相推斥，生理日乖蹇。","寄言怀所钦，何以惠元本。"]},{"t":"客有讥余不出者赋此代答","f":"五言古诗","c":["一从解缨绂，自觉无烦恼。","结交多静者，谈谐半野老。","颇识渊明琴，亦爱子云草。","开尊乘夕凉，问月展沉抱。","管乐非所歆，鱼鸟狎幽讨。","吾道本沧洲，投簪未为早。"]},{"t":"乙巳入京睹饥民载道怅焉成感","f":"五言古诗","c":["畿南百里馀，托家在日边。","胡为多菜色，老稚强相牵。","困苦弥道周，流离满目前。","展转沟中瘠，感之涕泫然。","昊天何不吊，灾疹屡婴缠。","里巷寡完壁，日午厨未烟。","岂无郡邑吏，蒿目恤颠连。","岂不奉明诏，频烦事赈蠲。","谋朝不保夕，微生只暂延。","裘马千金子，银鞍白玉鞭。","意气倾燕市，斗酒美十千。","立马闻痛哭，时或投一钱。","所活宁有几，明惠不足宣。","仁人切痌瘝，造物苦无权。","谁当司燮理，密勿赞重玄。","旸雨尽时若，蒸黎获所天。"]},{"t":"补谪候旨未下","f":"五言古诗","c":["不到京华久，宫阙望逾高。","九阍严戟卫，陛楯戒呼号。","我来自炎徼，仗剑出蓬蒿。","驱骋长楸道，再返五陵豪。","微官将白首，青草但如袍。","姓名在除目，依稀似马曹。","浪迹聊玩世，陈力愧时髦。","一命亦不易，敢希鱼水遭。","赤日方炎赫，步马忆兰皋。","何当踏层冰，林洞恣游遨。","俛首俟嘉惠，闭户绎离骚。"]},{"t":"赠李嗣业太学有引","f":"五言古诗","c":["圣主当阳日，临轩雅好文。","四郊承累洽，间亦起尘氛。","安危时注念，将相总难分。","有美南州彦，修洁袭清芬。","千秋绳作者，万里志奇勋。","家学源流远，趋庭嗣述勤。","绮谭绎霞馆，保泰虑弥殷。","应心思哲匠，屑玉见缤纷。","洞彻天人理，宁惟躐典坟。","请缨追往烈，草檄震前闻。","燕台方市骏，冀北未空群。","扶摇将直上，阊阖待排云。","吉甫称为宪，他时或属君。"]},{"t":"西河郝氏馀庆堂","f":"五言古诗","c":["十年看树木，百年仰树德。","树木长乔林，树德延世泽。","干木隐西河，美誉亘今昔。","卜夏与田方，亦复如双璧。","寥寥千载馀，谁与践芳迹。","丈人溪上居，秉心嗜玄寂。","于世薄所营，齐物忘得失。","捐粟惠贫荒，施剂起残疫。","道路悯遗金，囹圄念艰阨。","餔馁复赈穷，轻财殚心力。","哀死建义茔，累累表幽宅。","存殁总衔恩，自我无德色。","哲嗣乃肯堂，作求念弥惕。","永言绍家声，禔躬慎朝夕。","当官重清勤，吏事岂缘饰。","仁惠浃穷檐，勉勉树声绩。","孙枝日衍繁，云霄看比翼。","不见内史家，里中称万石。"]},{"t":"初春感怀","f":"五言古诗","c":["通籍将二纪，阅世良已多。","拙宦乃若兹，造物当如何。","消息谅有时，无用辄自嗟。","渔樵任所适，谁遣谢薜萝。","既出勿复道，岁月匪虚过。","圣德方日新，有道如春和。","四方共拭目，跂足沾恩波。","众觉忧茅拔，大业岂蹉跎。","小臣堪就列，欣际涤烦苛。","太平占有象，休续五噫歌。","桑榆应未晚，宁烦逐日戈。","子奇须白首，方共表东阿。"]},{"t":"过宁远值王直夫公出不得晤语赋怀二首 其一","f":"五言古诗","c":["合并良未易，君去何时还。","相暌日以远，形影渺难攀。","衡阳无雁度，音信亦孔艰。","念我同声者，寥寥天地间。","仗剑从西来，驱车历万山。","凭君一尊酒，慰我游子颜。","地近等秦越，何由写肺肝。","岂无杯中绿，独酌不成欢。"]},{"t":"过宁远值王直夫公出不得晤语赋怀二首 其二","f":"五言古诗","c":["闻君事结束，驾言入上都。","述职趋王会，宁辞涉远途。","羡君居此邑，发轫骋良图。","政甫逾期月，惠泽已全敷。","书生宰百里，黄白徯来苏。","宁静希单父，恬淡等菜芜。","朝天类化叶，入境方治蒲。","归来增秩后，夹道拥欢呼。"]},{"t":"送同年蔡子正以院幕考绩二首 其一","f":"五言古诗","c":["行矣登长路，乘秋入上都。","与君暂离别，握手复踟蹰。","在昔投嘉会，振策事齐驱。","悠悠越念载，逐逐府中趋。","相怜语留滞，奋翼及桑榆。","归朝承睿奖，振拔不须臾。"]},{"t":"送同年蔡子正以院幕考绩二首 其二","f":"五言古诗","c":["宦达良不偶，遇合固有时。","昔年同籍者，显膴递相随。","南北渐离散，倚伏理难窥。","前薪勿复道，疏滞得所宜。","明庭慎课典，主眷讵云私。","伫见雄飞近，宁庸更伏雌。"]},{"t":"正学发潜卷为韶州李封君作二首 其一","f":"五言古诗","c":["湛湛浈江水，英英庾岭云。","昔有幽潜士，于此扬清芬。","努力追千古，潜心事典坟。","豪华俗所悦，而乃厌尘氛。","圣功始克复，章句岂徒云。","名教自足乐，嘉尚志不群。","式闾慕高义，交者意独勤。","令子承先德，通籍迩明君。","应时树嘉绩，奕奕振前闻。","义方馀世泽，取赢属后昆。"]},{"t":"正学发潜卷为韶州李封君作二首 其二","f":"五言古诗","c":["南荒始作相，大业美开元。","千载曲江后，谁与并腾骞。","丈人初养晦，家学浚其源。","地灵若有待，岳降可同论。","传经念手泽，贻翼永不谖。","郡国徵高等，天路缀鹓鸾。","人伦推藻镜，结纫总芳荪。","披忠饶启事，时时上帝阍。","之子在万里，寤寐怀乡园。","显亲重行道，勋烈照乾坤。"]},{"t":"送黄达卿归延平","f":"五言古诗","c":["黄生负奇尚，耻与流俗亲。","好游恣览历，仆仆走风尘。","弱冠弄柔翰，仿古逼其真。","腰下芙蓉剑，烨烨出延津。","佩此仗谁知，亲仁托善邻。","一见如平生，莫逆超常伦。","遗我双明珠，几席诚足珍。","邂逅只须臾，言归及早春。","握手何所道，衷曲难具陈。","后会当何时，矫首道无因。"]},{"t":"送刘左史游吴越","f":"五言古诗","c":["楚中有高士，意气实霞举。","薄宦不徇时，三仕未跻膴。","分符及盛年，地近庾山紫。","赫赫何所知，闷闷只循理。","王门再曳裾，去思尚孔迩。","行路转多艰，拂衣还故里。","十五男女儿，婚嫁俱毕矣。","行年八十馀，矫矫类仙侣。","鼓棹出汉江，五岳从兹始。","邯郸大道旁，别君逾二纪。","念我本同声，访我金陵市。","促膝靡所谈，雅尚仍图史。","筋力不自劳，驱车又复起。","吴越美遨游，选胜犹未已。"]},{"t":"答刘九逵二首 其一","f":"五言古诗","c":["卉木零高秋，窗轩困积雨。","怀人葭露长，新知乐披睹。","邂逅不须臾，慇勤托肺腑。","遗我几瑶篇，珠玉满环堵。","展玩照颜色，时如对握麈。","探讨及盛年，积学罗千古。","得句每惊人，价重鸡林贾。"]},{"t":"答刘九逵二首 其二","f":"五言古诗","c":["自昔论意气，义侠美刘生。","而我遘之子，谈辨倍峥嵘。","雅尚耽图史，彩笔复纵横。","胸藏包万象，词源轶二京。","蒐罗日以富，著作日以闳。","岂伊独务博，聊此导冥行。","杀青业兼辆，宁徒藉墨卿。"]},{"t":"送黄季文游皖潜兼寄刘明府","f":"五言古诗","c":["海曲多名流，艺苑各驰骛。","仆仆一黄生，汪汪亦叔度。","五岳慕奇观，三都等作赋。","华发渐盈颠，名山恒杖屦。","驾言复西游，皖潜有佳趣。","巍巍天柱间，山谷旧游处。","胜迹属吾家，千古如旦暮。","此地得神君，口碑方载路。","挟刺何所投，依刘实倾注。","岩穴普声施，青云藉攀附。"]},{"t":"寿肥乡李封君七十","f":"五言古诗","c":["昔游赵魏间，颇识其风土。","丈夫多慷慨，士俗恒遵古。","葛城带邯沟，浮丘接广武。","圣相肇名家，旧族罕为伍。","世代几变更，作求应念祖。","独行一鸿生，□□推藻斧。","家学有渊源，三凤继腾骞。","仲子业方就，平章奋裔孙。","两都劳抚字，恩光及里门。","行年且杖国，先蒙天语温。","锦衣映鹤发，山林道转尊。","云司倚钟阜，遥睇卧龙村。","冬风吹朔雪，春酒复当设。","家会美连枝，游子重为别。","定省隔晨昏，千里共明月。","燕喜递称觞，自我心如结。","显亲在扬名，褒纶绎不绝。","遐齿叠承恩，移忠念逾切。"]},{"t":"霍廷评以县绩既赠其所后父母复疏请移赠其本生者得旨俞允","f":"五言古诗","c":["世人有二亲，君独有其四。","问之何为然，犹子道无异。","昔在襁褓时，曷知身所自。","稍长解趋庭，膝下两承志。","先子守章缝，怀才绌远施。","世父里中豪，慷慨多植义。","所后暨所生，罔极看无二。","先德并能培，作求兹不坠。","宦迹始东方，苍黎戴抚字。","当宁重循良，恩赉侈衡泌。","义方差可酬，明发恒不寐。","溯念厥初生，有怀当倍至。","一疏动明光，天朝本孝治。","生我育我者，龙章幸同贲。","佳妇视佳儿，尊亲各自致。","主锡讵云私，孝心元不匮。","廷尉自无冤，亲恩仍显被。","移孝勉为忠，天书谅可冀。","宰木有辉光，里人称善事。","厚积庆偏流，举颂昌而炽。"]},{"t":"读归德孝女传有序","f":"五言古诗","c":["世道日以衰，伦纪渐攸斁。","睢阳淑气盘，砀山连雁泽。","元老既生申，钟灵逮女德。","彼美香闺人，志行何辉赫。","结发事夫君，内相殚厥力。","黄鹄忽孤飞，誓节明如日。","高堂养舅姑，令仪固靡忒。","罔极报所生，亦复娱亲侧。","造物啬其年，同穴愿斯毕。","骨肉感分离，泉台乃终寂。","谁与述平生，家庭旧史笔。","累累数千言，孝思实维则。","扶纲仗老臣，安车且前席。","再相即归朝，道路咸加额。","燕语及笄帏，圣心谅同恻。","伫见下龙章，潜光表幽宅。"]},{"t":"诸同社期集梅花坞余以公阻弗克赴","f":"五言古诗","c":["春色满近郊，徘徊堪寓目。","松柏夹道周，禅宇敞虚谷。","结伴探梅花，览历遍林麓。","草木皆向荣，香雪独芬郁。","冷蕊点疏枝，清赏递相逐。","姑射有仙姿，皎洁如冰玉。","瑶台本淡妆，铅华不染俗。","而我尘俗婴，遥望隔山曲。","家傍罗浮村，万树带晴燠。","庾岭先南枝，冲寒媚朝旭。","看去乱乡愁，未必娱心目。","东阁似扬州，诗兴但潜触。"]},{"t":"中春宴集汪氏西园","f":"五言古诗","c":["中和启令节，旷望极春明。","谷风舒以穆，百卉竞芬荣。","良辰既如许，胜赏复群英。","会心安在远，方驾薄西城。","苑开凤台侧，嘉木荫芳亭。","高丘环异石，池塘草并生。","万绿间红紫，禽鸟亦春声。","暂此息尘累，先教俗虑清。","绮谭佐名理，雄辨恣峥嵘。","已协沧洲趣，兼欣求友情。","坐久林霏合，轻飙逗野庭。","馀寒恋衣袂，对酒谁独醒。","献酬屡促席，觞至必尽倾。","晚归各留咏，刻烛韵斯成。","分携订后会，心知重合并。"]},{"t":"社中延李本宁先生同集承见赠四章答和如数 其一","f":"五言古诗","c":["江左富才华，佳丽称自昔。","文人几代兴，词章稍赫奕。","沈谢既相雄，颜鲍俱挺出。","终焉匪国桢，绮靡亦何益。","道丧千载馀，谁与振芳迹。","大明甫中天，应运多贤硕。","斯文乃在兹，起衰济其溺。","后进有师承，努力追前辙。"]},{"t":"社中延李本宁先生同集承见赠四章答和如数 其二","f":"五言古诗","c":["留都实旧邦，万年等丰镐。","钟山接石城，长江复环抱。","太平多欢娱，曹务亦稀少。","眷焉心所知，相与事幽讨。","慕类情每殷，结盟以为好。","休浣迭命觞，意气恒倾倒。","篇翰各自雄，聊此谢尘扰。","服义畏友朋，群疑互质考。"]},{"t":"社中延李本宁先生同集承见赠四章答和如数 其三","f":"五言古诗","c":["圣治日休明，奇文播芬郁。","伊我二三子，于何绍芳躅。","大雅既堪师，稽古念逾笃。","末学安足云，中行贵独复。","探讨多会心，俦侣情俱属。","梦寐昔贤豪，千秋矢与续。","日月惜居诸，飞光一何速。","艺苑有宗工，相期善自勖。"]},{"t":"社中延李本宁先生同集承见赠四章答和如数 其四","f":"五言古诗","c":["金石本希声，瓦缶一何众。","江汉楚望分，争先睹麟凤。","赤帜竖艺林，千载无屈宋。","海内几神交，雄篇或传诵。","紫气忽东来，盈门多宾从。","吾党勉步趋，翩翩逐飞鞚。","君子遗德音，穆如过雅颂。","鸾翮非久羁，大厦需梁栋。"]},{"t":"天界寺宴集","f":"五言古诗","c":["近郊多宝地，兹地景偏饶。","诸天开净域，上界出僧寮。","阴森翳草树，乔木且干霄。","万松间修竹，绿荫垂丰条。","值我同心友，折简相招邀。","夙驾西南隅，弭盖陟山椒。","历览穷幽胜，徙倚任逍遥。","置酒长檐下，远俗隔尘嚣。","鸟哢声声巧，林响复翛翛。","举杯能勿醉，耳热一长谣。","日晚促归骑，始觉路迢迢。","秉烛兴未尽，入户已深宵。"]},{"t":"西行答赵仁甫","f":"七言古诗","c":["何人解作阳春曲，世上巴词第相逐。","闽海赵生才实奇，艺苑于今步称独。","与余莫逆始论心，促席开樽时一吟。","师门雅重学不愧，客舍相看情最深。","大雪漫漫惊岁易，去住从今隔消息。","伊余远役粤西陲，而君尚走长安陌。","长安聚会不可常，他时绾绶向何方。","风尘荏苒俱为客，欲寄音书路总长。"]},{"t":"蟠桃行","f":"七言古诗","c":["春风桃花千万树，几日飘零逐春去。","四月枝头实正圆，频经采摘知何处。","别有兹桃种最佳，灵根久托在仙家。","栽培不染尘寰土，枝干时披阆苑霞。","开花结实三千岁，应候经期长不改。","筠笼相赠罕致之，时向瑶池宴里在。","东方小儿岂不良，惯饮金盘玉屑浆。","三过桃林采其实，寘之怀袖托天香。","慇勤为谢西王母，彼是人间大隐侣。","天上何年失岁星，流作金门陆沉者。","后来桃熟好相招，免向林园更复取。"]},{"t":"宝剑篇答谢潘明府","f":"七言古诗","c":["潘郎作吏花满县，匣贮雌雄双实剑。","看花琴鹤思俱清，抚剑豺狼迹尽歛。","羡君佩此已多年，何须巨阙与龙泉。","雪花星文纷照耀，陆剸水断俱赫然。","政成久已报天子，穷谷深山遍霖雨。","卑棘那堪凤久栖，层霄合拟凫将起。","伊余宦迹偶从君，杯酒慇勤几论文。","解剑赠余心莫逆，恍然风雨双龙分。","剑乎剑乎堪重汝，潘郎意气长相许。","旧时魑魅敢窥人，入夜斗牛光射土。","神物由来用有时，铅刀何用徒区区。","借处会须先斩佞，弹来休用叹无鱼。"]},{"t":"五月五日过新安冯明府招集柳将军庙时诸葛邓二君俱以董河役适至","f":"古风","c":["江南江北路初分，万里乡书未易闻。","岁序孤舟逢五日，弟兄同社忆离群。","东道更谁为地主，西河却有大冯君。","命驾频烦江之浒，折简慇勤日将暮。","置驿真能似郑庄，下榻何当比徐孺。","将军祠宇自昔年，此地壶觞亦嘉晤。","况兼二客千里逢，促席开尊并许同。","诸葛雅称丞相裔，邓君亦有长成风。","倾盖乍交情若故，把酒剧谈词俱雄。","乡园蒲艾岂须设，故人鸡黍自堪悦。","君不见清时无事辟兵符，翕河已仗群公力。","淮海应高卧治名，簿书岂废逢迎客。","休向三闾羡独醒，且须一醉同今夕。"]},{"t":"与黄中翰登丛台","f":"七言古诗","c":["邯郸大道连上国，道旁主人殊不乐。","南去北来寡所欢，总是悠悠异乡域。","君本罗浮洞里仙，今作凤凰池上客。","使节辉煌返玉京，邮亭邂逅风尘陌。","喜君新自故乡来，于我信宿暂徘徊。","握手共道乡园事，慰劳相看酒一杯。","探奇吊古重多兴，携壶更上古丛台。","倚阑四顾河山渺，歌舞当时安在哉。","王侯第宅感今昔，井里年来渐萧索。","岁岁但修祷雨文，未见丰年贺苍赤。","君归丹阙觐天颜，四方水旱应沾臆。","民力东南何足陈，三辅之间且菜色。"]},{"t":"义犬行有序","f":"古风","c":["犬马之私世所有，衔恩总缘豢养久。","死生之际义所难，胡然得之丧家狗。","吁嗟乎，白杨古冢空累累，不见声称及后来。","丰碑长傍一抔土，题以义犬何奇哉。","行如狗彘人羞比，留却芳名翻若此。","贫贱相随未足嘉，临难守死节堪与。","宿草荒阡掩秽骸，往来观者嗟未已。","君不见鹄苍昔日美徐宫，礼锡君王称狗垄。","又不见洛下传书慰陆机，亦留孤冢呼黄耳。","古之葬者若论功，今之葬者彰其义。","乾坤正气属斯人，平生恩爱与谁亲。","一朝反眼不相识，羞对前丘义犬坟。"]},{"t":"闻宁夏警报","f":"七言古诗","c":["圣世承平日已久，韬甲休戈但坐守。","未闻天子猎长杨，不见将军屯细柳。","一朝羽檄西北驰，惨淡秦州战角悲。","白骨如山被原野，赤燧中宵动鼓鼙。","此时大将方推毂，万里何辞挽刍粟。","决策应过汉子房，壮猷岂但周方叔。","骄虏旋闻悔祸殃，小丑何堪距大邦。","威仪复见汉官旧，转战无须六郡良。","豺狼族类心难测，周秦以来无上策。","浪说佳兵事不祥，敢谓和戎利已得。","乘胜还须缚左贤，铭功有待勒燕然。","北伐似闻歌六月，东征何必待三年。","直使王庭空绝漠，尽致降夷称属国。","长驱凯奏入鹤关，永见胡尘清虎落。"]},{"t":"苦热","f":"七言古诗","c":["六月南方暑渐稠，祝融司令按炎陬。","火旗当午常不散，烈驭中天故为留。","销金烁石如飞炬，群生若在洪炉里。","已应道路少行游，却以簿书妨燕处。","安得大壑与层冰，令人但有河朔情。","何当一夜金飙发，崇台峻宇同秋清。"]},{"t":"元夕徐侍御招同王光禄李孝廉观灯","f":"七言古诗","c":["帝里春还未几日，万户千门总春色。","昨夜云间月欲圆，更道今宵祀太一。","华灯闪烁映朱阑，纵横游骑满长安。","笙歌响度香尘起，触忤羁人惨未欢。","徐卿为我开斗酒，李白谈诗方在口。","倒屣王生能复来，浮云万态俱何有。","请记当年旧酒垆，几人得意在皇都。","且拚乐事随青帝，莫逐乡心卜紫姑。"]},{"t":"宝纶楼为萧比部赋","f":"古风","c":["谁家高楼倚碧空，层檐飞宇势穹窿。","佳丽河山指顾中，地灵久与人谋通。","乔木森森本故丰，谷口犹馀百尺松。","主人卜筑方成功，登楼一览思无穷。","朝看旭日扶桑东，夕挹明霞返照红。","奎壁入夜透绮栊，四时林薄环青葱。","忽睹鸾书下九重，天意人事宛相从。","君不见东海父老忆于公，高闾驷马意何雄。","又不见通德门成自孔融，世人咸仰郑君风。","宝纶之楼事并同，主人以此称亢宗。","岭海遗爱溢花封，白云司里名转隆。","奏绩又逮明光宫，天书之下迭相逢。","千年堂搆业增崇，更看贻燕光前踪。"]},{"t":"枯桐行有序","f":"古风","c":["君不见定清寺里双高桐，疏枝直干拂苍空。","迩时荣枯忽顿改，一株摧落淩霜风。","孤根未绝含生意，鬼神呵护知无穷。","夜半高歌人不识，冥冥诧有嘘枯功。","生气从兹回地底，柔条嫩绿盘根起。","翩翻翠叶大于盘，浥露含风姿更美。","看看渐与碧檐齐，高枝复有摩空势。","物理由来不可知，一任玄苍而已矣。","世人得丧理亦然，安见浮生事事完。","有时披雾青天出，有时急雨春风颠。","栽培但使灵根在，雪干霜标年复年。","不因零落归山涧，会须千尺能参天。"]},{"t":"咏芍药","f":"七言古诗","c":["春风浩荡百花庄，千红万紫斗妍芳。","雨前雨后难相似，点点风飘正断肠。","莫向此花悲晚暮，此花不受春光妒。","幽香独自殿芳尘，浩态还能称独步。","醉露当阶不自持，含风绕砌却多姿。","广陵浪说誇金带，东武何劳侈玉盂。","近侍牡丹元似锦，绿水绛荷芳尚歛。","送去迎来如有情，艳妆总道来仙禁。","薰风阵阵拂瑶台，红药分明锦绣开。","折向尊前怜国色，更有天香入酒杯。"]},{"t":"寿大司马王公七十","f":"古风","c":["枌社星辰聚，槐庭日月长。","苍生安石望，绿野晋公堂。","紫气朱明天一色，夜夜祥光表南极。","三朝姓字可淩烟，再起勋猷看指日。","谁令宰相号山中，咫尺天都事不同。","仲淹雅有先忧志，充国能图方略雄。","似闻侧席思耆旧，共拟安车下岩薮。","敷锡先由歛五福，作朋自合称三寿。","松筠晚节坚，龟鹤更长年。","金茎天上诏，铁杖地行仙。","馀庆犹能光燕翼，令子葵心初捧日。","谢庭兰玉未须多，王家龙凤元非一。","君不见明经韦氏学，相业悠悠增世泽。","又不见清德杨氏家，四世三公事可誇。","持觞今且颂南山，剑履旋应近圣颜。","欲令仁寿遍天下，直教中国相司马。"]},{"t":"汉宫春晓图","f":"七言古诗","c":["禁苑钟声催报晓，枝间处处闻啼鸟。","开帘岂复雪霜寒，掩镜齐欢风日好。","无边乐事趁春明，韶华满目最关情。","娇颜任使名花妒，缓步偏多细草承。","共美纤腰回万舞，亦有长门伤独处。","新□□□□□歌，密意难传红叶语。","堪笑高台止避风，岂能对槛却当熊。","丹青图画春风里，哀怨琵琶夜月中。","春去春来人渐老，花落花开春竞巧。","年年岁岁奉宸游，何论承恩先与后。","夭桃如锦柳如丝，流莺千啭上林枝。","欲知无限芳春思，总在凭阑不语时。"]},{"t":"岁暮答深泽赵明府","f":"七言古诗","c":["与君万里同为客，千里分符复相隔。","南北天寒雁不征，缄书欲寄无由得。","剖冰跃出双鲤鱼，尺素由来自深泽。","开函一字一相思，愁怀望断黄尘陌。","我今寄傲海东头，宦思羁情总萧索。","大东杼轴渐成空，鸿雁何时慰安集。","海内交知转寂寥，邮筒几月无消息。","岁晚谁能罢越吟，劝君且自加餐食。"]},{"t":"穆陵行答吕惟仪","f":"古风","c":["全齐十二称天府，山川错列雄东土。","当年赐履尽穆陵，历世兴文接邹鲁。","沂山之下沂水清，远流曲折来骈城。","郁芊盘结多灵淑，岳降常为圣代英。","君不见马卿文章魁天下，已高学士南金价。","又不见冯君大小相因循，奕世勋名可动人。","自馀禀粹相继作，跃龙翥凤非寥廓。","君家先达有许公，后贤亦合比申国。","我本东南海上来，薄游北海接仙才。","双鬓萧骚惭渐短，孤怀愁绝傍谁开。","明珠久矣甘寥寂，片玉依然光始发。","早晚徵书下晋城，更看并对黄金阙。"]},{"t":"万松引为蔡孝廉作","f":"古风","c":["君不见桃李花，浅白轻红相间遮。","伤春一夜林头雨，飘泊溪边片片霞。","又不见杨柳枝，娜婀千丝拂地垂。","一朝霜气摧梧叶，总逐秋风陌上吹。","朔雪漫漫地冻裂，山间百卉俱欲折。","岁寒何物可徵奇，苍翠长松端自别。","谁人家玩此珍图，传来的是蔡君谟。","节概看君应类此，萎薾于今何有乎。","披图细睹万松树，傲雪淩霜自朝暮。","龙干参差护岭云，虬枝葱茜含山雨。","陶径何言菊并存，丁年十八事堪论。","托迹聊为处士隐，分荣不羡大夫尊。","闽中夹道君家物，彷佛今犹相咫尺。","磥砢终须梁栋材，气色居然嵩岱植。","有时隔水奏笙簧，千年裂石摩穹苍。","青牛或出樛枝里，白犬多居偃盖傍。","真人最爱风初入，服食还须俟五粒。","更喜兴祥枯复生，共羡禀和高且直。","堪嗟杨柳望秋零，桃李当春只暂荣。","岂似贞姿劲节长，不改万山摇落万松青。"]},{"t":"屡丰亭有序","f":"七言古诗","c":["半亩荒园一径通，四面山气相冥濛。","蓬蒿密拥一朝辟，独立虚亭草树中。","见说亭成甘雨溢，是时忧旱意初释。","主人默祷年屡丰，以此名亭义偏得。","吁嗟洵美非其乡，斯人一去迷何方。","四顾虚明堪徙倚，亭亭宛若鲁灵光。","伊余继至及秋好，公暇看山豁尘抱。","冬雪官梅树树花，春风桃李媚百草。","去岁民间赖有秋，今年雨泽亦还周。","有鸟枝头催布谷，家家南亩事锄耰。","但令穑事年年足，圃暇农閒皆鼓腹。","鸣琴不怍屡丰亭，处处同歌春酒熟。"]},{"t":"武夷九曲歌寿少司马陈公七十有序 其一","f":"楚辞体","c":["一歌曰：我所瞻兮万年宫，溪流一曲开蒙茸。","彭祖之居号云龙，群仙更聚幔亭中。","谁其主之溪上翁，惟张与徐差可同。","骖龙驭鹤意融融，坐见尘扬沧海东。"]},{"t":"武夷九曲歌寿少司马陈公七十有序 其二","f":"楚辞体","c":["二歌曰：我所瞻兮玉女峰，溪流二曲山气浓。","镜台不受埃尘封，印石时留翰墨踪。","何以居之桂树丛，猿吟虎啸生雄风。","勒马淩霄四望通，千龄龟鹤伴长松。"]},{"t":"武夷九曲歌寿少司马陈公七十有序 其三","f":"楚辞体","c":["三歌曰：我所瞻兮会仙岩，溪流三曲溪转深。","海日初升开晓岚，游仙鸾鹤此中骖。","何以侑之杯行三，缘厓架壑穷幽探。","山光水色媚清酣，千秋万岁乐且耽。"]},{"t":"武夷九曲歌寿少司马陈公七十有序 其四","f":"楚辞体","c":["四歌曰：我所瞻兮在玉华，溪流四曲景逾赊。","钓鱼溪畔放浮槎，题诗合到李仙家。","谁与幽栖傍赤霞，仙床倦起看山花。","解愠园中试御茶，主人之乐讵有涯。"]},{"t":"武夷九曲歌寿少司马陈公七十有序 其五","f":"楚辞体","c":["五歌曰：我所瞻兮号天柱，溪流五曲杂烟雾。","栖真更在留云处，丹灶茶炉共朝暮。","谁与相从洽情愫，晚对群峰誇乐聚。","紫阳之业应难去，君子万年当永誉。"]},{"t":"武夷九曲歌寿少司马陈公七十有序 其六","f":"楚辞体","c":["六歌曰：我所瞻兮一览台，溪流六曲苍屏开。","振衣千仞出崔嵬，上与天游意豁哉。","谁其镌石扫莓苔，千年声响超群材。","露零仙掌溢玉杯，葆真怡性貌若孩。"]},{"t":"武夷九曲歌寿少司马陈公七十有序 其七","f":"楚辞体","c":["七歌曰：我所瞻兮云石堂，溪流七曲树生香。","石门虚彻把金光，翘首三峰列上方。","谁其行乐意未央，天壶日月景偏长。","逍遥倚仗回北廊，乐只君子寿无疆。"]},{"t":"武夷九曲歌寿少司马陈公七十有序 其八","f":"楚辞体","c":["八歌曰：我所瞻兮到并莲，溪流八曲水潺湲。","钟鼓楼台步列仙，月明环佩声珊然。","谁可与同学慕禅，笠子临流枕石眠。","游方之外思翩翩，赢得神全迓永年。"]},{"t":"武夷九曲歌寿少司马陈公七十有序 其九","f":"楚辞体","c":["九歌曰：我所瞻兮尽仙亭，溪流九曲山鸟鸣。","灵峰之上云英英，轻盈杖屦等鸿冥。","谁可与同猿鹤情，荷锸相将日斲苓。","止恐安车下帝庭，山中之乐如苍生。"]},{"t":"清江行送孙邑簿归清江","f":"古风","c":["江流旋绕临江城，江中之水何清清。","江比颍川堪洗耳，清似沧浪可濯缨。","结庐江上孙文宝，闭门诵读明经早。","官因论秀无中人，政署催科宁下考。","朅来海上两期年，廨宇名更高士轩。","栖凤原非考城后，淩云况在华阴先。","堪叹时无曾待制，叶子才高且同滞。","宦辙久知行路难，王门岂合长裾曳。","任他设醴左迎虚，已向天台赋遂初。","世情自古疑蕉鹿，秋风此日正莼鱼。","君家有法名安乐，四休居士言犹昨。","携壶当复陟金牛，开门更喜罗黄雀。","江水洋洋总乐饥，餐英又到菊花时。","昆山璞玉仍韬耀，郤林新桂待华滋。","君不见孔家兄弟振清响，当时且坐元祐党。","道脉浚于江有源，赢得儒林并瞻仰。","又不见刘氏子姓美星郎，科名继武振馀芳。","世泽江流同不息，千载令人颂墨庄。","君归酿秫柴桑里，看山日坐乌皮几。","身外浮名了不关，羽翼云霄将继起。"]},{"t":"读郑氏世德传有序","f":"楚辞体","c":["万事悠悠听彼苍，古来壮志多摧藏。","几处功成归绿野，几人世及有青箱。","人岂尤兮天岂怨，天与英雄半利钝。","馀庆常从身后知，荣名未可眼前论。","尔家世泽总诗书，逢衣无术胜华裾。","丹山一奋犹衰凤，绿泮三生待化鱼。","光阴容易催人老，自叹功名苦不早。","流水知音未绝弦，清庙抡材须合抱。","君不见东海源长泽亦长，汪波浩渺浸扶桑。","海上风云时会合，鹏程九万终飞扬。"]},{"t":"陈以哲孝廉自武夷山中有作寄怀侑以仙洞茶建溪酒赋此答谢","f":"七言古诗","c":["敲门报有山中使，新从武夷下九曲。","高人犹在幔亭间，缥缈烟霞三十六。","秋阴猿鹤解相留，日宴群仙酣未足。","慇勤寄我洞天香，逡巡复有杯中绿。","安得乘风辄御虚，伴尔名山脱尘俗。","司马云端旧结庐，至今借与何人宿。","君来且赴曲江春，莫畏移文绊岩谷。"]},{"t":"海上谣","f":"古风","c":["东来渤澥浸扶桑，下见南溟接渺茫。","潮平半拍中华岸，流远时通异域航。","十洲三岛知何在，兴雨腾云多变态。","曾闻鞭石总成虚，复拟扬尘焉可待。","登高望远苦难超，百川并注归沃焦。","忘机鸥鸟狎烟艇，遭睡骊龙弃纬萧。","有客三年居海上，大观饱目心神爽。","倘可浮槎伴列仙，不然乘桴穷沆漭。","昔逢若士吾家子，蒙谷行游苍雾里。","今应何处访安期，我欲从之隔弱水。","安得乘风生羽翰，飞越蓬壶周历金台玉阁三千里。"]},{"t":"百仙图为陈司马题","f":"七言古诗","c":["何处山幽开洞府，苍松白石烟霞古。","南极星腾涧壑辉，百仙并集呼且舞。","天门宛似辟三宫，天池又与二室同。","莲比华山千叶秀，云气昆丘及阆风。","铁桥应是罗山曲，扶醉桥头鞭白鹿。","斲得终南地肺芝，采药天台犹未足。","大会依稀赴幔亭，结庐主人亦谪星。","海上蟠桃经岁熟，倚门云是董双成。","何必飞升同白日，棋局优游晋石室。","羽扇堪挥障世尘，遍览名山愿已毕。","慇勤为谢吕纯阳，卢生犹解说黄粱。","归与亦欲随仙侣，万态浮云酒一觞。"]},{"t":"商山图为林国相题","f":"七言古诗","c":["商山旧接终南胜，深谷层峦倍幽静。","高士何年共结庐，云满衣裳蒿满径。","閒来便唱紫芝歌，驷马高车较若何。","棋局每凭幽涧石，诗篇长咏狎烟萝。","自嗟生世唐虞远，祗应木石同萧散。","反覆时情任变更，过目浮云了不管。","汉庭当日重元良，忽从秘画张子房。","羽翼终归岩下叟，千年涧壑尚辉光。","后人颇笑卢藏用，佳趣此山曾与共。","唐家无事翊皇储，何须别却烟霞洞。"]},{"t":"龙江行送黄士明归龙江","f":"七言古诗","c":["樵山巀嶪罗群峰，中天削出青芙蓉。","樵湖尽注飞流水，一湾东下江犹龙。","中产高人萃清淑，古今上下蟠心胸。","往往应时多遇合，文章行业淩苍穹。","君年逾壮学日积，飞扬意气追前踪。","霜蹄得路轻千里，养成六翮将摩空。","天子求贤初爰立，前星瑞协映储宫。","异日明良知济美，青云早附毕天工。"]},{"t":"忆昔行","f":"七言古诗","c":["忆昔长安事薄游，相逢意气淩千秋。","鸣珂队逐双龙阙，就日辉腾五凤楼。","紫陌繁花邀并马，玉河新柳系停驺。","是时方喜离家食，海内朋游近相得。","翻手宁知云雨情，论心未怯风尘色。","衔杯结伴有高阳，挥麈谈天俱碣石。","一从分袂出都门，世事悠悠不可论。","落魄天涯时自惜，狂歌燕市几人存。","驱车每共嗟危辙，逆旅能无念故园。","暂假拂衣归栗里，林泉幽暇释尘滓。","几年松菊讵云荒，何处江山誇洵美。","却爱吾庐未可忘，畏路无心强复起。"]},{"t":"对酒歌夏日郊居作","f":"古风","c":["五月林亭花气浓，披襟四面生凉风。","主人避暑池边坐，客至樽开乐事同。","尊前爱客重沽酒，世上浮云宁复有。","河朔风流昔所闻，兰亭觞咏今能否。","对酒歌，日欲曛，劝君有酒莫辞频。","一醉浑忘愁里事，千愁尽向醉中分。","浮生不定如漂梗，白日西飞谁解挥戈留短景。","渊明入社便攒眉，李白举杯惟对影。","相见应知聚会难，酌酒与君君尽欢。","但使金樽长对月，莫教奔走道路空漫漫。"]},{"t":"寿母行为倪明府作","f":"七言古诗","c":["宝婺江边婺影悬，仙华白鹿女中仙。","燕喜堂前歌寿母，忘忧阶下乐长年。","忆昔公车初召对，十月征衣寒朔吹。","不嫌游子道路遥，自许高堂钟釜在。","曲江宴罢试分符，百里花光溢海隅。","熊丸已幸成慈训，乌哺偏能念母劬。","爱日春晖多受祉，瞻云岭峤嘉能子。","瑶池青鸟信常通，金阙紫鸾恩具迩。","行看锦绶贲鱼轩，佩玉鸣珈自兹始。"]},{"t":"刘明府迁倅吉安","f":"古风","c":["君不见召翁卿，当年抚字著贤声。","躬劝耕桑循陇亩，留得人传召父名。","又不见杜公君，从来绩誉比前闻。","底事令人歌杜母，祇缘节爱念弥殷。","以此方知古为政，不在苛条与虐令。","赫赫虽无在处称，既去人心思莫竟。","刘君治行有谁先，两汉家声旧所传。","仁比南阳蒲示辱，义似山阴惟一钱。","人道君才非百里，展骥功应别驾起。","岭北烽烟接岭南，父母之思犹孔迩。"]},{"t":"九如图","f":"七言古诗","c":["名山万丈插天碧，曲阜层冈环翠壁。","苍陵面面削芙蓉，下见长川流大泽。","日月重明不夜城，托根千龄松与柏。","结庐高士得所如，何用移文拒逋客。","森森兰玉更芳姿，自可优游任泉石。"]},{"t":"岁暮","f":"七言律诗","c":["当时走马共朝天，屈指长安二十年。","岁暮流光思往日，世间万事皆徒然。","东风吹绿变新柳，又见池塘对春酒。","且将吾道付沧洲，自古红颜终老丑。"]},{"t":"机易行有序","f":"七言古诗","c":["东南海上几仙山，巨浸洪涛漭瀁间。","金银宫阙三千里，止许游仙日往还。","幻出群峰有机易，岩石巑岏瞰蛟室。","扶桑堤岸对吞天，灵草汀洲连浴日。","混沌凿处德难居，精卫填来事总虚。","岂见徐生药可市，浪誇秦帝石能驱。","么么何物商人子，眼轻大壑如沼沚。","妄言海若在海山，拟藉天吴报天子。","扬帆破浪喜长风，虎节龙旂入海中。","黄金他日使如土，朱提异地愧无功。","举朝相顾尽失色，却恐天心未易格。","谁能周隐及穷荒，孰引批鳞为已责。","王生素业慕萧曹，自矜曾佩吕虔刀。","誓歼狐鼠清城社，忍使鲸鲵截海涛。","草茅书就千言牍，条陈利弊剖衷曲。","宛如长孺思拾遗，大类贾生能痛哭。","曾闻杞客但忧天，争比恤周嫠妇贤。","立仗每愁鸣辄斥，朝阳未见声俱传。","吁嗟王生解张胆，绘图封事彻皇览。","海波依旧今不扬，奸谀魄夺齐民感。"]},{"t":"冰桃行寿刘隐君","f":"七言古诗","c":["寒威凛冽冰塞川，止见梅花犯雪妍。","天上碧桃元异种，冬来结实实逾鲜。","刘郎自识天台路，亦解瑶池接王母。","黄竹歌馀宴白云，擎出冰桃非下土。","丹丘紫洞美仙居，蓬蒿亦自爱吾庐。","萧然一径成真隐，含毫因暇著潜夫。","谢家兄弟多兰玉，登筵并奏南山曲。","未须笙鹤侈霓裳，汉露金茎仍所欲。"]},{"t":"答林无华时自莆中来访因之阳春","f":"古风","c":["世上少知音，与君初握手。","文章宦达我难兼，满耳蛙鸣亦何有。","九漈壶山类毓奇，见君颇恨识君迟。","囊中白雪堪谁和，听尔复赋阳春时。"]},{"t":"题寿鹿图为人侄寿其叔母","f":"七言古诗","c":["海气蒸霞日始旭，照见碧桃初度熟。","翩翩青鸟自瑶池，伴得女仙骑白鹿。","鹿衔芝草声呦呦，桃实累累枝上头。","并入丹青图寿禄，因知萱草号忘忧。","谁共家园周览远，最是竹林推小阮。","丝管骈罗日导舆，好鸟和鸣千百啭。","兰玉阶庭雨露长，阿宜岂特称文章。","绕膝含饴多集顺，岁岁同开燕喜堂。"]},{"t":"北上答黄卓卿","f":"七言古诗","c":["游人理棹珠江前，记得还舟及四年。","握手河梁复送远，片帆北去淩风烟。","见说声名忌太早，谁解红颜长美好。","功业难俱少壮时，悠悠岁月长安道。","至后阳生春又新，马蹄再踏帝京尘。","请看紫陌看花者，亦是玄亭载酒人。"]},{"t":"帝京篇","f":"七言古诗","c":["皇家首善枕居庸，山河孕毓环青葱。","绣户朱门通十道，龙楼凤阁严九重。","簪缨漏待鹓鸾簉，戟卫营连虎豹雄。","贵倖轩车流似水，豪游衣马气如虹。","玉帛群方俱萃止，赆琛无远不同风。","昔时天子日临御，将相安危深眷注。","宵衣咫尺近重瞳，便殿从容亲谠语。","自从回禄稍为灾，将作频烦忧爰处。","两宫虽幸觏重新，三殿才闻工乍举。","大内深居静有常，天上人间渺莫睹。","迩来况复多妖氛，去年暑雨溢城闉。","至今食玉兼炊桂，在处釜鱼与甑尘。","闾阎生理日消索，今昔人心异笑嚬。","主计帷中难借箸，司马门前惧脱巾。","庙算由来因圣主，国是兼之藉大臣。","坐看调燮先宁迩，四海同归万历春。"]},{"t":"题张从事思亲卷","f":"七言古诗","c":["永嘉山水钟才贤，盛美由来多可传。","近年更见张从事，翩翩文行雅能全。","菽水生平欢未足，岁月悠悠感风木。","劬劳几废蓼莪篇，白云飞绕他山屋。","自从鼓箧出成均，南北都怀寸草春。","捧檄绵绵思道路，三釜何由更逮亲。","张仲于前称孝友，君今嗣述芳传久。","须知移孝易为忠，不独风尘驱下走。","显亲何术在扬名，骎骎宦业起家声。","已见封章贲泉户，还看兰玉竞敷荣。"]},{"t":"章江送别图为黄季子作有序","f":"七言古诗","c":["江干六月暑初赫，谁解停桡访迁客。","楚粤间关路几千，于君意气感今昔。","君家兄弟雅爱余，休戚由来义所须。","肝胆时时堪并照，势利翩翩总不如。","吁嗟薄俗增兹口，罔极谗言亦何有。","金石宁渝肺腑交，云雨徒翻轻薄手。","叔度汪汪千顷波，淆之不浊将奈何。","剡溪未惮乘舟远，滕阁难同载酒过。","豫章却有陈蕃榻，高士南州已非昨。","良夜真虚北海尊，孤山独渺西湖鹤。","写出生绡送别图，君归名尚纪洪都。","昔日销魂南浦处，碧草绿波半有无。","水鸟自飞还自没，扁舟想像当时发。","篷底一声独酌谣，浩歌天地流云遏。"]},{"t":"送少宰叶公拜相北上","f":"古风","c":["圣王御宇垂三纪，海内贤豪相继起。","宰衡之任厥惟艰，爰立于今几易矣。","闽海福唐首地灵，挺生人杰重明庭。","沙合河通占郭璞，魁名兆后相初兴。","遘会方知全不爽，名世登庸若应响。","天将良弼赉皇家，廿载蓬池钦邃养。","当宁年来梦卜频，一夕台阶气色新。","使者徵书分道出，念旧招留共五人。","君不见虞廷五臣昔辅理，化洽垂裳称善美。","又不见夏后当时得五丞，坐令天地庆成平。","江干几日新凉至，发船叠鼓催津吏。","伫看道合更和衷，奕奕勋猷起三事。"]},{"t":"寄题钱侍御小辋川","f":"七言古诗","c":["天留胜地虞山麓，城市林泉乐亦足。","宛转清渠有画桥，周回广径多奇木。","翩翩鸥鹭百千群，两两鹓鸯三十六。","溪渚宁言仆射陂，岩峦未数王官谷。","主人只慕右丞庄，每道蓝田胜辟疆。","笔落已同诗有画，樽开便逐醉为乡。","烟霞在处生华薄，箫鼓乘流命野航。","地阔尽容江月色，亭高时逗涧花香。","看看水木清华里，幻出潇湘一别墅。","聚远楼前绕砌兰，空明阁下临汀芷。","桂丛杏馆间椒园，槐陌梅廊带竹里。","倒影朱阑池畔回，栖霞青雀林间起。","早岁能悬御史车，萧然濠濮羡鯈鱼。","酒阑但坐看山几，歌罢还抄种树书。","流水柴门非俗境，青松白石爱吾庐。","千年摩诘风流在，莫说清斋尚不如。"]},{"t":"寿冯母太孺人八十","f":"七言古诗","c":["江南十月天气新，橘柚垂荣号小春。","爱日北堂情更倍，翩翩彩袖正娱亲。","碧桃海上冬还实，雪藕冰梨伴锦瑟。","西母瑶池信始通，麻姑且道蓬莱出。","家园周览乐潘舆，彷佛云扶白鹿车。","南极星光联宝婺，管弦应奏凤将雏。","子舍承颜孙绕膝，女偊长年犹孺色。","庭阶兰玉喜森森，拜阙衣冠恒络绎。","八十遐龄未足多，阳都得道已形和。","称觞定迓期颐永，黄发重赓燕喜歌。"]},{"t":"送韩孟郁南还","f":"七言古诗","c":["去年挟策上皇州，握手为君赋远游。","今年舣棹江之涯，杯酒逢君还白下。","三献楚玉犹未明，令人感慨倍关情。","由来遇合苦不早，幸君始壮匪晚成。","驽骀未敢轻骐骥，霜蹄得路终千里。","斑衣且暂傍庭闱，贾勇还期复大举。","中朝事业俱名贤，结客何须但少年。","丈夫许与恒不小，飞扬意气凌苍天。"]},{"t":"答梅子庾","f":"七言古诗","c":["有客丰神照秋水，胸中磊落谈名理。","仙隐如传仙尉家，吴趋大类吴门市。","自言负俗寡所谐，难遣风云入壮怀。","世上龌龊何足数，客中情绪苦无佳。","床头却有书连屋，展向风檐时玩读。","雅意难忘对圣贤，此身未肯混流俗。","蹑屩行游到秣陵，彩笔还能赋二京。","名刺怀来字半灭，尘剑拂时铗自鸣。","神交海内谁知己，雄文欲学黄初语。","赠我空惭寡和篇，争比龙门得御李。"]},{"t":"赋得宦情随日薄","f":"古风","c":["当年畏路苦驱驰，往事于今有所思。","千山历转听猿道，三径犹临浴鹤池。","老作蠹鱼空玩日，杜门却客从真率。","时邀社酒问农桑，或向古人寻著述。","泉石逍遥赋遂初，蓬蒿密拥一郊居。","杖屦忽回方外辙，冠裳再逐府中趋。","自甘阅历风尘久，岂谓憣然辞?亩。","意气纵横类若无，身世浮沉亦何有。","小草谁令复出山，强将名姓在人间。","考槃尚忆林园乐，结辔难忘道路艰。","看看世事徒劳耳，屈指科名越二纪。","薄宦宁能但俛眉，优游却道衡门美。"]},{"t":"赋得诗思入秋多","f":"七言古诗","c":["三伏炎蒸喜渐收，新凉河汉属清秋。","数声树底蝉方变，几点窗间萤自流。","怀人极目蒹葭水，四方云集纷才子。","衣马同游思转多，鞭弭相从业未弛。","栖迟旅食总他乡，公馀登览白门旁。","六朝旧事吟禾黍，千里邦郊咏凤凰。","远近亲知半离索，缄书谁与道寥廓。","璀璨珠玑海畔来，绰约风云天上落。","胸如云梦八九吞，忽睹连篇满赠言。","为向泥涂嗟潦倒，将从霄汉望腾骞。","伊余短鬓霜初染，薄禄衰迟徒窃忝。","岁寒但共保松筠，莫遣年华空荏苒。"]},{"t":"双节咏为王孟箕虞部母暨大母作","f":"七言古诗","c":["棱棱双节称王母，此日陈情先念祖。","陟屺仍怀圣善人，燕喜俱难方颂鲁。","匡岳彭湖间气钟，妇姑先后禀将同。","节操承家自不改，贻翼于今未有穷。","黄鹄歌残天渺渺，鸾书欲下恩多少。","三釜犹怀风木思，六珈已恨堂萱老。","手植庭槐喜独存，欲报春晖未敢言。","骅骝志尚堪千里，乌鸟情终逮九原。","财赋东南随物力，早夜持筹裕经国。","岂同榷利计征求，祇为明庭佐规画。","能诗水部本通才，宦业中朝更远哉。","叠有纶恩荣里闬，依然宝婺映中台。"]},{"t":"南圃长春卷","f":"七言古诗","c":["东南海上神仙窟，长薄逶迤荫丛樾。","扶桑万里映朝暾，波光倒射金银阙。","幽秘中开小有天，参差蕙畹接芝田。","主人自辟三三径，风月壶觞伴列仙。","不羡桃红与李白，珠林烨烨金光碧。","宁同仲蔚守蓬蒿，芳香种种沾天泽。","就中松柏有贞姿，上栖鸾鸟下伏龟。","千寻劲节淩霄起，风标雪干自离奇。","洞里乾坤开丽日，丛桂灵椿相挺出。","竹梧次第长孙枝，年年此地皆春色。"]},{"t":"瑶池喜燕歌长至日为友人寿母","f":"古风","c":["天上欣迎至，人间庆履长。","书云礼罢初增线，爱日情深复举觞。","慇勤开绮席，并奏云和瑟。","擎来玉乳九霞浆，侑以金桃千岁实。","斑衣庭下舞蹁跹，间有蓬莱阆苑之群仙。","灵妃环侍，玉女在前。","枣如瓜，藕如船，脯麟炙凤多芳鲜。","白鹿车随孔雀扇，霓旌羽盖云中现。","大会何须侈幔亭，珠树瑶林介福殿。","酒阑便拟白云谣，听彻缑山学凤箫。","侍女笙歌相间作，骖鸾驾鹤递招邀。","昔时八骏空驰骛，此日庭帏乐自足。","承欢侍宴似东方，大隐金门仍所欲。"]},{"t":"送陈仲子赴春官兼呈王明府","f":"古风","c":["城南有名族，韦杜不专美。","厥族本太丘，犹称聚德里。","昔时兄弟止两方，世推二难声俱扬。","今日诸孙纷嗣业，人言旧里胜高阳。","家学渊源相师友，博古探奇穷二酉。","文章独步应魁元，科名接武辉前后。","仲子才雄海内知，韬光韫璞已多时。","一朝薛卞与长价，四海珍琛共斗奇。","王家仙令飞双舄，增秩行看嘉乃绩。","计偕挟策对临轩，踵接鸣珂趋左掖。","凤毛苞彩映天颜，翕赫簪裾玉笋班。","次第生平摅积抱，大业同看伯仲间。"]},{"t":"题黄给谏南山精舍","f":"七言古诗","c":["东南海上凤凰山，山下灵岩杳霭间。","仙都自昔美泉石，福地由来远市阛。","爰溯梁陈始栋宇，百庵十院相连附。","中开石室名普门，旧是黄公栖隐处。","一从英茂已蜚腾，故社难忘竹院僧。","割田岁入充香积，报祀堂留伴佛灯。","荒烟野草将沦没，香火延绵尚不绝。","巍巍古殿似灵光，郁郁丛祠等千越。","善庆应符百世昌，云仍奕叶有辉光。","科名异代绳相继，宦业于时久益芳。","有美当朝名谏议，亢宗自解承先志。","陵谷千年稍变更，箕裘自我宁遗坠。","心因念祖切光前，长悬旧隐寄云烟。","买山辟地可十亩，作室临厓复几椽。","苍松翠竹参差起，怪石飞流接溪渚。","堂称乐志怡心神，馆号撷华满图史。","长桥木末疑汉津，泉听飞轩迥绝尘。","傍舍兼营水月阁，清斋不减辋川人。","羹墙祖德自难舍，选胜溪山亦复寡。","谁云此地不丹丘，更待他时为绿野。"]},{"t":"题金陵寺遂有亭董吏部在计曹时所建也","f":"七言古诗","c":["金陵城里金陵寺，当是金陵最佳处。","一区僻地人罕过，几仞高丘亭可据。","海畔忽来吏是仙，造士横经业已传。","国计频烦方借箸，公暇犹能觅胜缘。","寻幽挈伴山之麓，振衣直上纵遐瞩。","诛茅辟石亭乃成，临高望远意偏足。","郁葱佳气满钟山，翱翔宫阙五云间。","二水分流江浩渺，鸥鸟帆樯日去还。","城郭居人十万户，甲第连营纷指顾。","缔造初开万载基，歌咏堪裁两都赋。","主人登览未多时，内召程材荷眷私。","记忆吾曹杯酒侣，中心何日遂忘之。"]},{"t":"舞蛟石行有序","f":"七言古诗","c":["清宛堂前三丈石，出自他山始何日。","洞庭波底一潜蛟，舞馀幽壑离窟宅。","已化贞坚状独奇，舞态犹存未异昔。","不与青州怪并来，岂藉神人驱始得。","鉴赏曾经巨笔铭，先朝真迹自堪凭。","雷雨乍闻恐变化，风云如待欲飞腾。","何缘异代相传久，呵护应知属地灵。","倚槛不堪残秀萼，垂阴犹复绕朱藤。","丈人夙昔曾见梦，何如友谊今逾重。","笏袍亦类米家虔，表异真过灵璧贡。","长许高人入咏觞，更与词林侈歌颂。","平泉不羡赞皇居，叱羊浪说金华洞。","兴废由来自有时，灵光独在此为宜。","主人自昔多奇尚，神物于今却遇知。","屡经险阨终难易，岂因权力可潜移。","将军台榭逢新主，学士祯祥再见之。"]},{"t":"金陵元夕篇","f":"七言古诗","c":["令节招携聚会频，移尊更傍帝城闉。","金吾不禁閒游骑，玉漏休催结赏人。","淑气千门方霁雪，阳和满目堪怡悦。","九微灿若紫垣星，百影辉连朱户月。","太乙通宵祀汉宫，此时卜夜将无同。","银花树合光逾远，竹叶杯深乐正融。","佳丽金陵美自昔，留连想见豪华日。","临春阁上管弦多，结绮楼头歌吹溢。","吾党如今但乐群，却缘高会得论文。","共看结綵娱清夜，最好传柑遗细君。","见说天官初定籍，造物悠悠未易测。","世事何心卜紫姑，但须剧饮同今夕。"]},{"t":"元日","f":"五言律诗","c":["万国趋王会，山中自一家。","庭馀经岁草，林起隔年花。","入户风初暖，开帘日始华。","流年增感慨，飞思绕天涯。"]},{"t":"谒祖垄","f":"五言律诗","c":["三年樵径别，此日更跻攀。","祖德思逾厚，山灵笑复还。","心悬碧落外，身在翠微间。","来岁逢寒食，他乡忆故山。"]},{"t":"下第回舟次平圃","f":"五言律诗","c":["客久多吟越，人谁谏逐秦。","思家愁远道，去国忆王春。","岁月惭双鬓，江湖笑此身。","渐闻乡语近，归梦不须频。"]},{"t":"陈氏水楼","f":"五言律诗","c":["问尔餐霞者，何年此卜居。","白沙丛翠竹，秋水濯红蕖。","机静驯鸥侣，心閒谢鹤书。","萧然尘世外，无用忆莼鱼。"]},{"t":"元夕","f":"五言律诗","c":["序入初元夕，灯分太乙光。","钥鱼閒警柝，火树照流觞。","月皎春增色，歌残夜未央。","去年忆此日，驱马正他乡。"]},{"t":"郊行值雨","f":"五言律诗","c":["避暑寻幽壑，乘閒到野亭。","风声动林薄，雨气入郊坰。","尘外欣沾洒，吟边豁性灵。","行行归路晚，酒态已全醒。"]},{"t":"闻司谏刘先生佥宪闽中赋怀三首 其一","f":"五言律诗","c":["羊郡三年别，鸿音万里疏。","狂歌燕市酒，涕泪汉庭书。","吾道艰危里，时名想望初。","烽烟闽海净，揽辔意何如。"]},{"t":"闻司谏刘先生佥宪闽中赋怀三首 其二","f":"五言律诗","c":["青琐班朝日，黄门刻漏时。","有怀心独切，封事夜何其。","兴礼辞刘向，抡才补望之。","圣恩原不浅，出处未堪疑。"]},{"t":"闻司谏刘先生佥宪闽中赋怀三首 其三","f":"五言律诗","c":["宪府开闽越，雄才自汉京。","莺声辞碣石，龙气望延平。","奏疏君门远，刑章列郡清。","褰帷过海岳，似亦厌承明。"]},{"t":"途中人日","f":"五言律诗","c":["此日人同得，和风喜袭裳。","无心誇綵胜，转眼逼年芳。","池草知新绿，蹊花忆旧香。","上林春更好，及早赋春阳。"]},{"t":"京邸七夕过林希平小酌","f":"五言律诗","c":["夜色同杯酒，其如旅思遥。","音稀鸿度岭，秋入鹊为桥。","巧向吟边乞，愁因醉里消。","明年当此夕，何处复相招。"]},{"t":"赠黎运幕","f":"五言律诗","c":["全齐称外帑，少府待缗钱。","煮海功还在，操赢策孰先。","货权由昔重，吏隐识君贤。","幕里冰壶澈，芳声历下传。"]},{"t":"送程太学南归","f":"五言律诗","c":["摇落秋逾半，霜前叶乱飞。","酒随燕市散，人望故园归。","佩有吴钩在，吟馀郢调稀。","识君怜暂合，又向旅中违。"]},{"t":"送黄侍御之留都","f":"五言律诗","c":["乍逢燕市酒，其奈别离同。","道出青门远，声于白下雄。","喜看车是鹭，争避马为骢。","好结澄清侣，交章达汉宫。"]},{"t":"范晦叔程右文将归见过值余外出代柬再约","f":"五言律诗","c":["偶逐尘踪去，空闻二妙过。","风流兼阮谢，吟和喜羊何。","坐客应常满，逢君岂易多。","归心如未急，清夜倘来歌。"]},{"t":"送黄礼甫令归安","f":"五言律诗","c":["共是河阳吏，君先捧檄行。","几人随粉署，数月得黄生。","念此别离远，其如鄙吝萌。","重逢在何日，奏最入燕城。"]},{"t":"答谭金吾兄弟 其一","f":"五言律诗","c":["自昔同桑梓，而今隔异方。","非随鹓鹭侣，那识蕙兰香。","金是燕台重，珠元合浦光。","翩翩鸿渐羽，喜近五云翔。"]},{"t":"答谭金吾兄弟 其二","f":"五言律诗","c":["旅酒皆无赖，逢君即故乡。","遏云歌屡发，邀月兴偏狂。","文武声俱茂，衣冠泽自芳。","风尘驱俗吏，别思转堪伤。"]},{"t":"留别袁太学","f":"五言律诗","c":["与尔同桑梓，相将上国游。","诗篇谁竞美，杯酒每淹留。","雪里牵行色，天涯起别愁。","未知重会处，应早觅书邮。"]},{"t":"留别丁国云","f":"五言律诗","c":["帝里同为客，交情尔更真。","开尊来雪夜，握手慰风尘。","并马游俱壮，歌骊思转频。","不堪言别后，途次独迎春。"]},{"t":"新城道中","f":"五言律诗","c":["日暮西风急，黄尘扑马头。","村藏平野树，酒记旧家楼。","候馆听鸡发，征鞍对月收。","已忘从役苦，行路不曾愁。"]},{"t":"送车一中归罗浮二首 其一","f":"五言律诗","c":["客自罗浮出，探奇事远游。","云山几千里，雪夜一孤舟。","宦迹怜余渺，词林羡尔优。","诵来诗句好，真涤旅心愁。"]},{"t":"送车一中归罗浮二首 其二","f":"五言律诗","c":["僻地经过少，相寻却有君。","一行先作吏，几度忆离群。","握袂方冬雪，临岐复暮云。","汉庭有知己，应荐子虚文。"]},{"t":"题马平邑署","f":"五言律诗","c":["作吏元兼隐，萧然一草堂。","短墙过月色，虚牖接霞光。","阁最閒堪卧，琴还静可张。","生平甘澹泊，此味不妨长。"]},{"t":"邑中槐树","f":"五言律诗","c":["元非王相宅，庭下亦三槐。","嫩绿盈春榭，繁阴覆夏台。","政閒喧自息，吏散鸟堪来。","阴德差无忝，他时莫浪猜。"]},{"t":"咏邑前榕树因忆子厚有榕叶满庭之句","f":"五言律诗","c":["双榕何岁植，苍黛已盈围。","雨过百花尽，莺啼乱叶飞。","高人去云远，往事是耶非。","欲拟甘棠咏，其如和者稀。"]},{"t":"土酋四首有引 其一","f":"五言律诗","c":["族类元非我，徒云附大邦。","摧锋看有几，授钺诧无双。","止可追骄虏，谁令戮已降。","哀哀闻巷哭，泪血染西江。"]},{"t":"土酋四首有引 其二","f":"五言律诗","c":["俯仰追前事，令人恨里隆。","青衿还丧气，赤燧有何功。","单骑颜偏壮，群谋见略同。","至今安土著，鸟尽合藏弓。"]},{"t":"土酋四首有引 其三","f":"五言律诗","c":["比屋还耕凿，田园半已荒。","云何邀上赏，遽尔启侵疆。","浪说方归马，真成复进狼。","苍生元不造，谋者自为臧。"]},{"t":"土酋四首有引 其四","f":"五言律诗","c":["白面诚非拙，丹衷却未投。","恩遗曲突客，皮尽负刍裘。","狡虏心难测，蒸黎恨未休。","无辜将受戮，多难总堪忧。"]},{"t":"自城中还至乡园二首 其一","f":"五言律诗","c":["阒寂樵山下，先人一敝庐。","好游经岁别，避乱更城居。","阴德于门旧，遗经邺架馀。","暂归环眺伫，何日遂吾初。"]},{"t":"自城中还至乡园二首 其二","f":"五言律诗","c":["祖泽贻遗远，亲庭嗣述来。","山林欢未足，风木思堪哀。","魂魄思丰沛，班斓忆老莱。","满庭今对客，笑口未曾开。"]},{"t":"读郭郡公新筑东洲记","f":"五言律诗","c":["岭海千年胜，重逢郭细侯。","狂澜回砥柱，王气结中流。","海浴双珠出，波涵半璧浮。","甘棠他日咏，文彩遍南州。"]},{"t":"北上辞先墓二首 其一","f":"五言律诗","c":["四序春还转，重泉夜永藏。","有怀空陟岵，无地不沾裳。","列鼎嗟何及，趋庭恨倍长。","九原难复作，风木古来伤。"]},{"t":"北上辞先墓二首 其二","f":"五言律诗","c":["浮生俱幻梦，异代想音容。","痛拭牛山泪，悲看马鬣封。","义方馀手泽，往事感遗踪。","禄养真无补，瞻云涕复从。"]},{"t":"十八滩","f":"五言律诗","c":["二水流初合，群滩石并攒。","总成熟道往，不作畏途看。","捩柁过回岸，轻桡下急湍。","但谙三老法，利涉岂称难。"]},{"t":"杮源雨中","f":"五言律诗","c":["岭外雷初起，江边雨乍鸣。","旅眠听不尽，孤枕梦难成。","大野生寒色，长堤响瀑声。","应时偏润物，岂唤客愁生。"]},{"t":"次清源值龚侍御行部过谈舟中","f":"五言律诗","c":["维舟当日暮，有客过河干。","六载思同舍，重逢感旧欢。","月曾薇省隔，霜已鹭车寒。","揽辔君行早，弹来愧豸冠。"]},{"t":"将之邯郸答高正甫博士二首 其一","f":"五言律诗","c":["疋马向丛台，风烟万里开。","骊歌徵别曲，郢调杂新裁。","随牒官非远，临岐首屡回。","绝怜天尺五，先简邺中才。"]},{"t":"将之邯郸答高正甫博士二首 其二","f":"五言律诗","c":["再上燕台日，还思粤岭时。","千山辞瘴疠，五斗复腰肢。","下走风尘吏，中兴国学师。","未称劳逸远，诗句许相思。"]},{"t":"回车巷世传蔺相如避廉颇处","f":"五言律诗","c":["国事艰危里，君心属望初。","抗秦堪拔剑，全赵且回车。","虎斗谁争长，鹰扬计未疏。","列侯多策士，谁更似相如。"]},{"t":"赠陈新之二首 其一","f":"五言律诗","c":["期月平干政，风流邺下才。","神君邑里颂，循吏传中来。","世业青箱授，先声白简催。","五云天咫尺，飞舄自堪回。"]},{"t":"赠陈新之二首 其二","f":"五言律诗","c":["保障元相并，飞腾可易同。","里中难和雪，斤外已成风。","名自斗南远，群应冀北空。","愧余初学步，蹇拙向谁工。"]},{"t":"读朱巽甫嘉禾卷二首 其一","f":"五言律诗","c":["旧美渔阳政，嘉禾合并观。","总缘秋色好，双拂露华乾。","瑞协千箱积，忧从百亩宽。","河阳花发后，孰与此中看。"]},{"t":"读朱巽甫嘉禾卷二首 其二","f":"五言律诗","c":["几载求荒策，祥开喜颂君。","政和天亦格，绩异帝先闻。","畴绿新沾雨，畦黄并卧云。","愿因同颖秀，遍向陇头分。"]},{"t":"得仲弟家书二首 其一","f":"五言律诗","c":["万里天南信，经年未易闻。","清宵频梦草，白日几看云。","朔雪迷凫影，春山掩雁群。","忽来逢粤使，欣读八行文。"]},{"t":"得仲弟家书二首 其二","f":"五言律诗","c":["三年来冀北，星聚愧元方。","松菊应还在，田园岂尽荒。","旅愁春又半，乡思日偏长。","秋好看鹏翼，凌风或并翔。"]},{"t":"照眉池世传赵宫人照眉于此","f":"五言律诗","c":["荒池千载后，尚忆照眉时。","云鬓临妆罢，花容傍槛移。","柳馀深染黛，桃学淡凝脂。","此日空樵牧，兴亡事可悲。"]},{"t":"感遇三首 其一","f":"五言律诗","c":["行路难如此，孤踪合滞留。","客怀空对月，蓬鬓又惊秋。","愁逐商飙起，心俱大火流。","长安车马地，回首记同游。"]},{"t":"感遇三首 其二","f":"五言律诗","c":["阅遍红尘骑，凭谁慰盍簪。","人多工射影，吾独怅论心。","往事如川逝，生涯总陆沉。","但令钟子在，犹可托知音。"]},{"t":"感遇三首 其三","f":"五言律诗","c":["圣朝多雨露，无地不衔恩。","总识乾坤大，其如岁月奔。","殊方甘落魄，旅梦易惊魂。","自信心元赤，何时达帝阍。"]},{"t":"与张计部夜语并寄家书","f":"五言律诗","c":["冉冉风尘客，悠悠桑梓情。","十年俱潦倒，片语尽平生。","候馆悲秋色，乡园羡昼行。","平安惟两字，凭为报柴荆。"]},{"t":"旅梦二首 其一","f":"五言律诗","c":["客舍连宵梦，居然是故乡。","风波怜逆旅，羽翮倦殊方。","漏永参横户，窗虚月在梁。","静闻天籁起，萧飒动新凉。"]},{"t":"旅梦二首 其二","f":"五言律诗","c":["漂泊非吾土，迢遥忆敝庐。","到家元是梦，经岁渺无书。","骨肉两乡隔，宾朋万里疏。","行藏天所付，安用渺愁予。"]},{"t":"将发邯郸暂寓西署四首 其一","f":"五言律诗","c":["信宿丛台下，栖栖一旅人。","閒方谢簿领，愁转怯风尘。","砧杵秋声急，关山客梦频。","但谙倚伏理，何处不容身。"]},{"t":"将发邯郸暂寓西署四首 其二","f":"五言律诗","c":["蓬转应难定，羁栖复若何。","困来悲失马，妒在敢扬蛾。","旅思丹枫剧，乡心白雁多。","长风吹晓漏，不寐彻行窝。"]},{"t":"将发邯郸暂寓西署四首 其三","f":"五言律诗","c":["细雨侵阶湿，微风入暮寒。","徘徊征思懒，牢落客衣单。","卷帙堪为伴，琴尊并所欢。","未须怜去住，何路不行难。"]},{"t":"将发邯郸暂寓西署四首 其四","f":"五言律诗","c":["闭户时深念，凭谁作解嘲。","不妨杯独把，聊复句重敲。","傲骨成金注，穷愁是石交。","故园秋色满，天末有衡茅。"]},{"t":"九日旅怀","f":"五言律诗","c":["万里同为客，三年别故乡。","生涯俱逆旅，岁事又重阳。","盟负篱花酒，寒侵木叶霜。","龙山今日帽，谁并孟嘉狂。"]},{"t":"对月","f":"五言律诗","c":["望尽三秋月，空添万里愁。","风云多变态，羽翼尚淹留。","未上贾生涕，难消杞国忧。","可堪三五夕，俱倚仲宣楼。"]},{"t":"送乡友之扬州","f":"五言律诗","c":["木叶催寒序，他乡动客愁。","君方随旅雁，我独怅鸣驺。","斗下分雄剑，霜前怯敝裘。","暮云将鹤去，何日到扬州。"]},{"t":"晓行","f":"五言律诗","c":["淡月听鸡去，狂风傍马吹。","有谁怜傲骨，徒自强低眉。","白屋閒中笑，青楼暗里窥。","故人霄汉上，几度及瓜期。"]},{"t":"答黄汝纶","f":"五言律诗","c":["记忆邯郸道，真从梦里看。","弹冠先达笑，行路古来难。","满目纷时态，贞心独岁寒。","风尘俱异域，握手慰加餐。"]},{"t":"偶成","f":"五言律诗","c":["万态纷如昨，乾坤总莫容。","是非元自见，忧喜递相从。","未解知黄雀，何须笑白龙。","酒杯时对月，漂泊任萍踪。"]},{"t":"答高正甫赠别二首 其一","f":"五言律诗","c":["拙已无三异，狂初学四明。","暮云连树渺，孤鹤伴琴清。","走马为迁客，听莺恋友生。","骊歌新柳外，无奈别离声。"]},{"t":"答高正甫赠别二首 其二","f":"五言律诗","c":["上林春事好，谁与问花神。","我愧愁为敌，人知懒是真。","漂零随世态，奔轶望京尘。","纵有渑池翼，那堪白发新。"]},{"t":"答袁彦可","f":"五言律诗","c":["回首金台下，如君意独长。","开尊同雪色，并骑挹春光。","袂忍看花别，鞭因折柳扬。","新诗时把玩，慰我九回肠。"]},{"t":"留别黄汝纶","f":"五言律诗","c":["风尘耽薄禄，岁月混微名。","衣敝鹑将结，琴孤鹤共清。","诗多留滞意，酒慰别离情。","试问金台客，谁当赋二京。"]},{"t":"宫文学转王官致政","f":"五言律诗","c":["王门堪吏隐，虚左待君来。","醴酒恩非薄，长裾念已灰。","未临都讲席，先上望乡台。","桃李阴初合，含情更一杯。"]},{"t":"五日钱使君招同蒋文学署中小酌时方忧旱","f":"五言律诗","c":["郡阁逢多暇，庭槐逗远风。","天涯三夏半，客里一尊同。","艾叶迎杯绿，榴花入座红。","因思云汉语，废酒意忡忡。"]},{"t":"夏日公出便过江氏园亭","f":"五言律诗","c":["本是逢迎出，翻为汗漫游。","葵榴丹艳满，槐柳绿阴稠。","染翰馀清暇，开尊恋胜幽。","坐来移昼永，忽自散穷愁。"]},{"t":"城北送客不及小集神祠得同字","f":"五言律诗","c":["共有阳关意，归人望已穷。","避喧因别酒，听法借禅宫。","聚散元无定，壶觞但不空。","官閒期会少，竟日总堪同。"]},{"t":"喜雨","f":"五言律诗","c":["雨意连朝足，人心尽日欢。","火云初捲焰，赤地已扬澜。","耕课移勤补，农书带笑看。","几旬陪露祷，今得谢玄坛。"]},{"t":"大司马王公招饮城东别墅","f":"五言律诗","c":["背郭新开径，邀宾屡徙筵。","香山游再羙，绿野景同鲜。","鸟亦知人乐，花能为客妍。","微风生雨后，真可对炎天。"]},{"t":"慰蒋文学思归","f":"五言律诗","c":["异地同为客，如君最系思。","眼穿垂暮日，愁剧未归时。","燧色连青海，乡心满绛帷。","春风将改岁，桃李又花期。"]},{"t":"宿兴善寺二首 其一","f":"五言律诗","c":["一径双林下，新晴对夕晖。","参禅同入定，趺坐久忘归。","蛙吹皆成部，莲灯半照帷。","疏钟才数点，冥悟息尘机。"]},{"t":"宿兴善寺二首 其二","f":"五言律诗","c":["借榻依禅室，坛前见雨花。","停骖初贳酒，避鹤几烹茶。","棋局缘幽兴，诗篇恋物华。","尘途方扰扰，安得似僧家。"]},{"t":"淫雨颓垣甚多走笔戏作","f":"五言律诗","c":["蜗居徒四壁，四壁复难存。","夜宿玄冥驾，朝翻白帝盆。","龙吟当户牖，蛙鼓近堂门。","无力驱山鬼，凭谁为筑垣。"]},{"t":"自文安舟行至武清二首 其一","f":"五言律诗","c":["作客元无定，公馀亦胜游。","泥涂方驻马，野水共乘舟。","帆挂中川月，舷鸣雨岸秋。","江湖思不尽，渔火满汀洲。"]},{"t":"自文安舟行至武清二首 其二","f":"五言律诗","c":["蓟北三年客，常愁马足尘。","平川理舟楫，清夜下江津。","秋夜穿蒲苇，波光共羽鳞。","莼鲈思未得，亦自慰征人。"]},{"t":"大悲寺与文安诸生小集","f":"五言律诗","c":["野寺当幽处，登临思亦佳。","暮云方绕室，秋水欲浮阶。","扫榻呼僧语，凭轩动客怀。","青衿劳问讯，玄论满萧斋。"]},{"t":"武清隆兴寺僻静可居而门外纡径深泥不便来往","f":"五言律诗","c":["一榻双林里，焚香展道书。","闭门聊玩世，行路辄愁余。","僻地尘缘渺，新晴露下初。","不须惭物役，独坐见真如。"]},{"t":"和钱使君与大司马王公月下汎舟酌别薛明府","f":"五言律诗","c":["名园开洛社，月下记同游。","五马鸥相狎，双凫鹢并流。","池平波影动，星聚夜光浮。","□有安车诏，追欢复帝州。"]},{"t":"十四夜与诸文学对月酌别","f":"五言律诗","c":["砧杵秋将半，新情夜色良。","举杯同问月，今夕各他乡。","客里萍踪合，尊中桂子香。","当歌还进酒，明发思偏长。"]},{"t":"夜渡苑家口时月出东方水天一色酷类江南之景","f":"五言律诗","c":["月出波光涌，秋深露气寒。","观涛心欲壮，击楫道偏难。","灯火渔家集，帆樯估客欢。","江南多泽国，此地却同看。"]},{"t":"王孝廉席上送蒋郡博给假南还","f":"五言律诗","c":["几夜秋声急，催君解缆行。","莼鲈思正渺，衣马念全轻。","杯酒还今夕，邮签柰去程。","相违休道远，南望不胜情。"]},{"t":"海虞十二景 其一 龙山带郭","f":"五言律诗","c":["缭绕城边地，移来海上山。","峰峦朝暮接，苍翠有无间。","紫气时环抱，白云长自閒。","仙踪何处觅，蜡屐好同攀。"]},{"t":"海虞十二景 其二 雁塔摩空","f":"五言律诗","c":["阿育留遗胜，千年迹未芜。","凭虚观始壮，望远势难模。","霄汉闻钟磬，乾坤入画图。","锡游飞不尽，登览遍三吴。"]},{"t":"海虞十二景 其三 七水横琴","f":"五言律诗","c":["流水知音少，扬澜此地回。","盈堤多细柳，遇腊有官梅。","七派潮声入，千厓淑气开。","雍门今去远，何用使人哀。"]},{"t":"海虞十二景 其四 两湖浮镜","f":"五言律诗","c":["玉匣谁开镜，寒光对郭分。","双涵沧海月，半度具区云。","钓艇烟笼棹，莲舟绿映裙。","歌声随处起，偏动旅中闻。"]},{"t":"海虞十二景 其五 桧坛流月","f":"五言律诗","c":["仙坛嘉树合，世远自齐梁。","翠盖参天色，清阴碎月光。","干留孤鹤下，叶抱片云凉。","直性终无改，灵根谅有常。"]},{"t":"海虞十二景 其六 桃涧飞泉","f":"五言律诗","c":["涧水飞流出，桃花夹岸开。","穿林疑作雨，喷壑自成雷。","选胜堪移杖，探幽屡举杯。","武陵休再入，聊此涤尘埃。"]},{"t":"海虞十二景 其七 破山钟磬","f":"五言律诗","c":["断壁云常补，崩厓路欲迷。","仙游邀杖屦，客至访伽梨。","闻磬知莲社，听钟认虎溪。","禅心如入定，真作絮沾泥。"]},{"t":"海虞十二景 其八 瑞石亭台","f":"五言律诗","c":["磐石依山曲，孤根岁月遒。","台成堪坐啸，亭在可销愁。","截雨疑犀浦，听箫作凤楼。","飞仙宁道远，此地足夷犹。"]},{"t":"海虞十二景 其九 绝壁悬门","f":"五言律诗","c":["百丈丹梯迥，乾坤拓此山。","高疑通帝座，幽可列仙班。","日月平临照，风云递往还。","祗应人世外，别自有天关。"]},{"t":"海虞十二景 其十 拂岩回瀑","f":"五言律诗","c":["悬泉千尺下，飞作雪花轻。","岩挂联珠影，溪鸣碎玉声。","霏微沾月驭，凌乱洒霓旌。","并坐翻愁湿，新来谷口莺。"]},{"t":"海虞十二景 其十一 玄林鸽井","f":"五言律诗","c":["卓锡何年至，泉流雪乳寒。","群飞天外羽，几就洞中丹。","花雨兴龙窟，慈云覆绮阑。","酌来应觉爽，沆瀣不须餐。"]},{"t":"海虞十二景 其十二 晴海狼崖","f":"五言律诗","c":["大壑容流远，晴天入望多。","雨馀看玉蝀，浪里出青螺。","观海元无极，题厓尚可磨。","鲸波长愿息，击壤听讴歌。"]},{"t":"喜宁夏报捷二首 其一","f":"五言律诗","c":["六月王师出，三秦虏祸深。","尚方烦赐剑，死士赴悬金。","秘法通黄石，先声陨绿林。","辕门看饮至，庶以答天心。"]},{"t":"喜宁夏报捷二首 其二","f":"五言律诗","c":["骑士皆超距，儒臣亦据鞍。","城登弓月满，水决阵云寒。","百二还秦险，威仪复汉官。","几回看露布，更为里中欢。"]},{"t":"寄李长庚","f":"五言律诗","c":["问讯丛台月，凭谁作报章。","交情看剑远，别恨引杯长。","命驾难千里，怀人祗一方。","太行休道险，天路识飞黄。"]},{"t":"立春日得徐二孺书兼承寄长歌一阕赋答二首 其一","f":"五言律诗","c":["喜际春还候，双鱼达素书。","名因汉高士，诗似魏黄初。","青眼宁违俗，玄言重起予。","公车能召对，且莫赋閒居。"]},{"t":"立春日得徐二孺书兼承寄长歌一阕赋答二首 其二","f":"五言律诗","c":["屈指词坛客，徐卿已白眉。","三都推作赋，五岳待题诗。","海上依丛桂，山中问紫芝。","吴门他日过，载酒若为期。"]},{"t":"将发益津留别江应雷二首 其一","f":"五言律诗","c":["试笔当春早，江淹梦若何。","风云应有合，岁月岂虚过。","孤愤当年甚，离怀此日多。","不须传别赋，脉脉对沧波。"]},{"t":"将发益津留别江应雷二首 其二","f":"五言律诗","c":["旧业馀三径，幽居傍五渠。","孤山时养鹤，濠濮久观鱼。","上国多鸳侣，承家有鹭车。","箕裘看汝在，莫自托樵渔。"]},{"t":"王观察八柏亭二首 其一","f":"五言律诗","c":["宅以三槐胜，亭因列柏留。","岁寒偏不改，春翠日添稠。","门亦曾罗雀，材非但蔽牛。","悠悠伤往事，气节自千秋。"]},{"t":"王观察八柏亭二首 其二","f":"五言律诗","c":["乔木家声远，芳亭胜事繁。","雪霜看愈劲，雨露感偏存。","几就閒居赋，休誇独乐园。","东山何日起，难自老衡门。"]},{"t":"答妺丈崔体韶二首 其一","f":"五言律诗","c":["弟妺天南远，开缄独惘然。","栖迟因鸟道，沦落愧龙渊。","旅梦乡园隔，生涯岁月迁。","薄游苏季子，安问洛阳田。"]},{"t":"答妺丈崔体韶二首 其二","f":"五言律诗","c":["羡尔方云卧，衡茅且避喧。","蓬犹张氏径，帷自董生园。","共惜飞腾晚，长怀笑语温。","不言桃与李，应自见环门。"]},{"t":"贺郡丞过谈有思归之作赋此慰留","f":"五言律诗","c":["宿雨妆残暑，新晴见晚晖。","官閒期会少，地僻到来稀。","持论多坚白，当歌但式微。","君才非六百，岂可遂怀归。"]},{"t":"王德称从外舅韩公?兵槜李以所著客越集见惠代柬留酌","f":"五言律诗","c":["仗剑南游客，迎秋望故乡。","山川来越绝，风雨度维扬。","抱玉齐冰镜，怀珠溢锦囊。","久无诗伴至，那可废传觞。"]},{"t":"守岁","f":"五言律诗","c":["烛烬将残夜，钟鸣欲曙天。","漂零思故国，惟悴入新年。","春色还应近，东方候更先。","呼童催柏酒，往事不须怜。"]},{"t":"元夕同张计部常比部张大行宴集","f":"五言律诗","c":["频年多道路，良会总他乡。","百里星还聚，千金夜可长。","灯花迎客笑，火树接邻光。","愁病消强半，清歌复几觞。"]},{"t":"穆陵关二首 其一","f":"五言律诗","c":["驻马频思古，西风度穆陵。","崖悬山径狭，地迥野云层。","险阻真天设，山川几代兴。","时平关禁少，来往自相仍。"]},{"t":"穆陵关二首 其二","f":"五言律诗","c":["海岱称雄镇，提封自昔时。","当关元重地，赐履尽南陲。","往事惟衰草，颓垣有断碑。","游人多感慨，指点日西移。"]},{"t":"刘博士以诗文见寄赋答二首 其一","f":"五言律诗","c":["采风来大国，冠盖忆同游。","悬榻空相待，驱车可自由。","高谈虚稷下，司命有荆州。","词藻非公干，谁堪第一流。"]},{"t":"刘博士以诗文见寄赋答二首 其二","f":"五言律诗","c":["乡里衣冠后，如君岂乏贤。","文雄推赤帜，官冷尚青毡。","飘泊同羁旅，赓酬少接联。","上林将赋猎，紫陌听莺迁。"]},{"t":"五日过城西草堂","f":"五言律诗","c":["不到西园久，蒲觞此日来。","池环碧树合，门对紫薇开。","雨气清书幌，风香入酒杯。","欲寻逃□会，端不限城隈。"]},{"t":"再过草堂同罗李区诸君及二仲小酌","f":"五言律诗","c":["探幽谢尘役，乘暇款林扉。","好鸟声初集，连枝萼并辉。","暑从新雨涤，兴逐野云飞。","每忆西园会，清尊傍夕晖。"]},{"t":"寄题飞泉洞二首 其一","f":"五言律诗","c":["洞倚诸天胜，泉飞万壑寒。","枕流山瀑细，开径野云宽。","入会方莲社，招游并鹖冠。","鹤书如可待，难恋一枝安。"]},{"t":"寄题飞泉洞二首 其二","f":"五言律诗","c":["峡寺飞来久，泉应与寺同。","洞迷芳草径，林递落花风。","谷静闻莺响，山幽望桂丛。","探奇争载酒，倚杖见晴虹。"]},{"t":"答梁公益","f":"五言律诗","c":["上客争虚左，王孙岂自哀。","止因怀璞久，翻讶弃繻来。","骥足追风远，龙光傍斗开。","子虚如有问，谁复马卿才。"]},{"t":"答黄季重二首 其一","f":"五言律诗","c":["不浅春晖恋，仍淹九万程。","风尘过逆旅，逢掖守诸生。","旧学潜心富，新诗彻骨清。","远来君自见，多是为同声。"]},{"t":"答黄季重二首 其二","f":"五言律诗","c":["天涯羁薄宦，留滞惜年光。","琴静馀单父，车驱自太行。","气佳秋日夕，风洒客衣裳。","白雪依然在，承家业擅长。"]},{"t":"喜晴","f":"五言律诗","c":["积雨愁难破，新晴喜不禁。","绕檐飞燕剧，穿径落花深。","得暇频开卷，息交寡盍簪。","风来庭院午，独坐正披襟。"]},{"t":"和黎文学村庄即事","f":"五言律诗","c":["暂出红尘市，田家可避喧。","蓬蒿俱满径，芋栗各为园。","安定非鸿泽，相携类鹿门。","客来新酿熟，夜月醉荒村。"]},{"t":"元夕舟中二首 其一","f":"五言律诗","c":["今夕是何夕，扁舟伴鹤汀。","推篷一月白，弭棹数峰青。","深夜惟渔火，孤尊自客星。","不愁更漏永，此地隔尘扃。"]},{"t":"元夕舟中二首 其二","f":"五言律诗","c":["旅泊逢佳节，长宵作卧游。","江间仍禁夜，月下且维舟。","火树违同赏，灯花逭独愁。","明年知此夕，何客共登楼。"]},{"t":"寒食","f":"五言律诗","c":["旅次经寒食，游人念故园。","松楸违渐远，雨露感偏存。","昔幸同三釜，今谁作九原。","环樵峰七十，有梦到云门。"]},{"t":"过汨罗江","f":"五言律诗","c":["拟吊三闾赋，经行久未投。","谗人应共愤，宗国仗谁忧。","鱼腹千年恨，江声万古愁。","向令天可问，端不负灵脩。"]},{"t":"大风过采石泊舟时自慰","f":"五言律诗","c":["放舶春流驶，烟波却自愁。","半帆过采石，孤屿望仙楼。","水阔鱼龙宅，天空雁鹜洲。","长风吹不尽，薄暮喜维舟。"]},{"t":"三月抵京二首 其一","f":"五言律诗","c":["帝城三月暮，天气亦初春。","红紫花相待，青黄柳未匀。","条风开宿雾，细雨浥轻尘。","物色元非恶，深尊绿且亲。"]},{"t":"三月抵京二首 其二","f":"五言律诗","c":["尚及三春候，重来万里人。","辞家方在远，观国屡为宾。","宦业难书竹，时情任积薪。","长安真似奕，往事不须颦。"]},{"t":"出京阻雨","f":"五言律诗","c":["久客长安陌，缁尘日上衣。","计程方跋涉，听雨转霏微。","恋阙身难系，忧时愿不违。","冲泥非傍险，前路有晴晖。"]},{"t":"答区用孺太史雨中赠别","f":"五言律诗","c":["漂泊风尘里，曲江度几春。","莺仍乔木友，燕傍旧家人。","识路蹄空急，更弦调强新。","皇天多雨泽，何地不堪均。"]},{"t":"宝带桥在吴江","f":"五言律诗","c":["何年驱石至，十里接湖干。","雁鹜烟波渺，鱼龙夜水宽。","采菱歌进艇，对月坐持竿。","无限潇湘意，秋初露已寒。"]},{"t":"宿江山客舍","f":"五言律诗","c":["信宿江山道，清泠涧水滨。","川原多胜概，漂泊自风尘。","暂豁登楼目，因惭报主身。","灯前对儿女，何日是归人。"]},{"t":"江郎石","f":"五言律诗","c":["江郎三片石，鼎立出丹霄。","地植孤根远，天擎列柱遥。","露为金掌润，霞是赤城标。","劲质原无改，浮云暮复朝。"]},{"t":"建溪夜泊时值中秋","f":"五言律诗","c":["住楫滩头宿，滩声彻夜喧。","水舂随断岸，渔火照孤村。","月满秋光半，更深露气寒。","推篷怜对影，凉籁起高原。"]},{"t":"武闱校士二首 其一","f":"五言律诗","c":["闽海烽初净，辽阳檄转催。","徵兵烦十道，策士喜多才。","技已穿杨胜，筹因借箸来。","君王思颇牧，仗钺早登台。"]},{"t":"武闱校士二首 其二","f":"五言律诗","c":["此去频推毂，谁当独请缨。","圣恩深养育，壮志待澄清。","脱颍三千客，蟠胸十万兵。","扶桑弓未挂，须道有干城。"]},{"t":"和少司马陈公除夕忆其伯子孝廉之作","f":"五言律诗","c":["悬车惟绿野，游骑有青丝。","家庆遥相忆，年光暗自移。","槐高王相宅，兰茁谢家儿。","第一天人奏，承恩复阿谁。"]},{"t":"又和元夕四首 其一","f":"五言律诗","c":["细雨尘初净，长宵漏莫催。","园同飞盖会，客并小车来。","列炬红相映，深尊绿正开。","厌厌拚夜饮，不醉未应回。"]},{"t":"又和元夕四首 其二","f":"五言律诗","c":["闾阎多乐事，弦管竞先鸣。","月色晴还见，星光聚转明。","千杯为酒阵，五字作诗城。","折简吾能至，烛残漏几更。"]},{"t":"又和元夕四首 其三","f":"五言律诗","c":["节是三元夜，家同万石君。","宾筵元自羙，众乐总堪群。","授简多吟雪，当歌尚遏云。","笳声何处急，莫向此中闻。"]},{"t":"又和元夕四首 其四","f":"五言律诗","c":["入社能为主，登堂侈集贤。","衣冠惭上客，钟鼓乐初筵。","夜色过新雨，山光落紫烟。","赋才俱擅羙，谁愧在卢前。"]},{"t":"周博士招同观灯四首 其一","f":"五言律诗","c":["改岁风初暖，良宵月更新。","一时俱逆旅，万户却同春。","对语何妨久，相酬不厌频。","周郎能顾曲，徙席正堪亲。"]},{"t":"周博士招同观灯四首 其二","f":"五言律诗","c":["自尔来鸣铎，诸生庆拔茅。","烧兰淹夜酌，馔玉出中庖。","月向芹宫照，花因火树交。","主人情未已，促席句同敲。"]},{"t":"周博士招同观灯四首 其三","f":"五言律诗","c":["华灯连月彩，列炬映星芒。","爱客方投辖，徵歌复绕梁。","更寒听漏永，坐洽引杯长。","不醉应难寐，相看喜欲狂。"]},{"t":"周博士招同观灯四首 其四","f":"五言律诗","c":["凭阑多夜色，入座况春风。","客里芳心并，人间乐事同。","诗成俱倚马，笔落总如虹。","更仗杯中物，相酬慰转蓬。"]},{"t":"司马公游支提山回延过小集别后见贻兼约鳌山之会答和二首 其一","f":"五言律诗","c":["春游何处远，闻道叩双林。","尽得寰中胜，其如别后心。","忽来成美晤，久坐豁尘襟。","礼数难拘束，赓酬到夜深。"]},{"t":"司马公游支提山回延过小集别后见贻兼约鳌山之会答和二首 其二","f":"五言律诗","c":["南天方渐暑，而我坐春风。","秉烛夜方永，当筵月正东。","玄谈称莫逆，高咏总堪同。","案牍逢多暇，相期复桂丛。"]},{"t":"初夏周广文席上","f":"五言律诗","c":["雨过凉生座，云开月近帘。","诗情堪并发，酒戒未须严。","近地欣无警，平畴赖既沾。","喜君清夜酌，笑语解相淹。"]},{"t":"晦翁岩四首有引 其一","f":"五言律诗","c":["闻道龙峰胜，公馀得共攀。","石门高并对，岭树翠相环。","海色苍茫外，湖光渺霭间。","此中有佳处，况是古贤关。"]},{"t":"晦翁岩四首有引 其二","f":"五言律诗","c":["地迥烦先涤，林高暑易残。","云飞自怡悦，竹报日平安。","目极河山远，神游宇宙宽。","当年漂泊意，谁道愧儒冠。"]},{"t":"晦翁岩四首有引 其三","f":"五言律诗","c":["龙山读书处，镌石在云门。","避地迹偏远，得师道愈尊。","斯文应未丧，家学赖常存。","杖屦来从者，衣冠有裔孙。"]},{"t":"晦翁岩四首有引 其四","f":"五言律诗","c":["俯仰千年事，芳名重此山。","渊源俱学孔，伯仲总晞颜。","道与乾坤久，心俱水石閒。","我来登眺暂，觉已出尘寰。"]},{"t":"奉军门檄阅兵海上二首 其一","f":"五言律诗","c":["寓目真无际，洪流远拍天。","楼船多尺籍，沙屿未桑田。","对月还惊燧，迎潮或控弦。","可能风万里，尽扫海门烟。"]},{"t":"奉军门檄阅兵海上二首 其二","f":"五言律诗","c":["井里诛求急，俱缘饷荷戈。","昆明池水阔，赤壁夜帆多。","分队为鱼鸟，扬威杂鹳鹅。","将军同下濑，谁不负铙歌。"]},{"t":"荔枝","f":"五言律诗","c":["南国种偏奇，青林朱实垂。","味分甘露液，色染绛罗衣。","仙子霞为佩，佳人玉作肌。","可怜尘骑远，空解笑杨妃。"]},{"t":"周吴华为刻拙稿先示数篇赋答二首 其一","f":"五言律诗","c":["十载风尘客，谈诗每避人。","喜心宁见猎，寡和觉情亲。","案牍元多暇，宫墙况近邻。","羊何欣有托，空自愧阳春。"]},{"t":"周吴华为刻拙稿先示数篇赋答二首 其二","f":"五言律诗","c":["久缘诗癖在，习静懒敲推。","授简知同调，为模愧后来。","未须忧纸贵，先只惧梨灾。","掌故多文学，如君实爱才。"]},{"t":"喜霁二首 其一","f":"五言律诗","c":["旸雨元多憾，阴晴未可知。","登场期有穫，沉灶尚啼饥。","霓望真同切，云开孰与期。","东方忽已白，明作复当离。"]},{"t":"喜霁二首 其二","f":"五言律诗","c":["霪潦如春雨，今朝喜得常。","翻馀无石燕，舞罢失商羊。","省歛初遵亩，负暄始向阳。","农家欣作颂，更有万斯箱。"]},{"t":"游宗振自莆见过辄有贻赠答和二首 其一","f":"五言律诗","c":["命驾谁千里，神交自昔年。","青云多旧侣，白雪富新篇。","北海尊仍在，南州榻屡悬。","喜君乘兴日，犹及暮春前。"]},{"t":"游宗振自莆见过辄有贻赠答和二首 其二","f":"五言律诗","c":["一自承环后，称诗辄避名。","身容天有幸，才谢国为桢。","政每惭三异，招常虑四轻。","偏师谁劲敌，资尔护长城。"]},{"t":"再报满六首 其一","f":"五言律诗","c":["通籍方逾壮，登朝异晚收。","蹉跎因宦拙，漂泊感年流。","风木多遗恨，烟花几别愁。","寥寥思往事，真自愧潜修。"]},{"t":"再报满六首 其二","f":"五言律诗","c":["远忆西游日，羁栖二载馀。","名当百里起，迹类九夷居。","为国初经野，还家辄倚庐。","有怀知罔极，未得报鸾书。"]},{"t":"再报满六首 其三","f":"五言律诗","c":["拭泪辞先陇，干名赴上都。","璧完初返赵，莼羙又思吴。","马足非吾土，羊肠实畏途。","丛台空有恨，飞梦月同孤。"]},{"t":"再报满六首 其四","f":"五言律诗","c":["益津三辅地，卑湿亦长沙。","谪宦非投远，羁人止念家。","开尊持问月，随伴强看花。","计粒妻拿饱，恩宽早及瓜。"]},{"t":"再报满六首 其五","f":"五言律诗","c":["偶捧除书下，言遵北海东。","邯郸失学步，书社讶论功。","鸿羽哀中泽，萱花悴晚风。","孝慈双陨泪，归路逐飘蓬。"]},{"t":"再报满六首 其六","f":"五言律诗","c":["辞家悲宰木，劝驾藉朋游。","拜阙惭三仕，遭时诵四愁。","海邦仍抚字，桑土但绸缪。","报绩知无补，何因动冕旒。"]},{"t":"寒食前一日拟移尊于南山寺僧舍延宗振小酌代柬二首 其一","f":"五言律诗","c":["僻地淹词客，禅房对晚山。","攒眉因入社，望气似临关。","节是清和候，人乘著述閒。","行厨将禁火，先共醉乡还。"]},{"t":"寒食前一日拟移尊于南山寺僧舍延宗振小酌代柬二首 其二","f":"五言律诗","c":["积雨逢新霁，移尊伴胜幽。","兰亭觞已后，莲社会初投。","啼鸟当窗巧，飞云傍槛浮。","酒阑应得句，更为暝钟留。"]},{"t":"潇湘八景 其一 山市晴岚","f":"五言律诗","c":["洞远飞晴翠，峰高近蔚蓝。","雨馀山树秀，烟净野花酣。","市肆帘初捲，溪桥路可探。","垆头堪竟日，有客漫停骖。"]},{"t":"潇湘八景 其二 烟寺晚钟","f":"五言律诗","c":["寺对群峰寂，门临一径斜。","瀑寒山向暝，烟密树交遮。","僧饭过香积，禅栖伴法华。","似应钟定后，趺坐说三车。"]},{"t":"潇湘八景 其三 渔村夕照","f":"五言律诗","c":["积水环门绿，斜阳隔岸红。","捲纶初系笮，待月更推篷。","泊处依沙柳，歌来杂暮鸿。","得鱼供乐事，沽酒醉应同。"]},{"t":"潇湘八景 其四 远浦归帆","f":"五言律诗","c":["松径因回岸，茅斋对夕阳。","双双翔鹳鹤，片片乱帆樯。","候已乘风便，心宁怯路长。","柴门当半掩，波静舣归航。"]},{"t":"潇湘八景 其五 潇湘夜雨","f":"五言律诗","c":["近水开千亩，凌云挺万竿。","岸容初过雨，林气迥生寒。","植节苍逾劲，含风翠欲攒。","夜闻清籁远，晓望更檀栾。"]},{"t":"潇湘八景 其六 平沙落雁","f":"五言律诗","c":["秋早知寒候，霜前到水涯。","群依鸥鹭侣，声散荻芦花。","潦尽沙痕广，江空月影斜。","何须畏鱼网，长自狎浮槎。"]},{"t":"潇湘八景 其七 洞庭秋月","f":"五言律诗","c":["远水兼天涌，清秋入月来。","龙宫珠乍吐，鸾镜匣初开。","荡漾君山出，苍凉梦泽回。","买舟堪傍此，随意宿沙隈。"]},{"t":"潇湘八景 其八 江天暮雪","f":"五言律诗","c":["浩渺波光阔，霏微野望迷。","远看蓑笠钓，犹傍水云栖。","岛映银涛白，林欹玉树低。","岂无乘兴棹，一入剡山溪。"]},{"t":"秋初答林园相诗酒之惠二首 其一","f":"五言律诗","c":["山林多乐事，秋入兴逾赊。","忽枉传诗句，空惭负岁华。","尊开泉石侣，月照水云家。","更喜秦侯健，青门尚种瓜。"]},{"t":"秋初答林园相诗酒之惠二首 其二","f":"五言律诗","c":["年光看渐晚，秋气又生寒。","鬓欲相催白，颜谁解驻丹。","竹林方慕阮，诗传旧推韩。","斗酒因君赠，羁怀酌自宽。"]},{"t":"感遇三首 其一","f":"五言律诗","c":["世情纷忌直，宦态转为工。","触事情偏感，趋时愿不同。","是非庄蝶梦，得失楚人弓。","汝力虽难致，欣看论已公。"]},{"t":"感遇三首 其二","f":"五言律诗","c":["百里今司牧，俦非保障哉。","食须怜弱肉，吹或借寒灰。","直道凭谁主，狂澜未可回。","逢时应百感，何止七堪哀。"]},{"t":"感遇三首 其三","f":"五言律诗","c":["澹泊明吾志，孤贞谢世嚣。","蛾眉妒任老，鸡肋毁防销。","未拟三休去，真成独酌谣。","自公多暇日，堪自慰蓬飘。"]},{"t":"潘季选比部以颁诏事竣还朝并携其子就试都下赋别二首 其一","f":"五言律诗","c":["六传从天下，三山恋昼游。","波恬看大海，风动遍遐陬。","使节随丹凤，严程待紫骝。","西南仍羽檄，何以借前筹。"]},{"t":"潘季选比部以颁诏事竣还朝并携其子就试都下赋别二首 其二","f":"五言律诗","c":["赴阙春为伴，归朝吏是仙。","署云初号白，疏草旧称玄。","留滞吾同远，飞腾尔独先。","秋来看羽翮，庭下更联翩。"]},{"t":"桃花","f":"五言律诗","c":["隙地才如掌，绯桃亦数株。","秦源迹岂类，潘县意堪俱。","嫩叶含风袅，飞花满径铺。","刘郎偏有恨，竟日忆玄都。"]},{"t":"答陈生子东","f":"五言律诗","c":["风尘淹作宦，朋旧几登仙。","远是匡衡牒，先谁祖逖鞭。","羊肠惊尚怯，豹尾望空悬。","奏课知无补，深惭汉吏贤。"]},{"t":"王生自闻赍平倭捷诏于莆阳有赠赋答","f":"五言律诗","c":["子虚犹未遇，乘传似南行。","大有题桥志，兼怜结袜情。","歌因怀杕杜，心已畀干旌。","老幼知扶杖，瞻天百感生。"]},{"t":"邹太学筑堤防海乡人德之立石纪功为赋二首 其一","f":"五言律诗","c":["银浪兼天远，金堤历岁成。","回澜过砥柱，拯溺遍群生。","沧海将相变，污邪尽可耕。","睹河思绩茂，况已颂如京。"]},{"t":"邹太学筑堤防海乡人德之立石纪功为赋二首 其二","f":"五言律诗","c":["未遇占经济，家声旧度支。","玄夷金授简，黎庶口为碑。","下噀俱仓积，穷檐岂怨咨。","公车他日对，堪作水衡司。"]},{"t":"读陶集有感","f":"古风","c":["彭泽归能早，柴桑遁亦嘉。","一官辞簿领，五柳傍烟霞。","守寂全天性，栖真谢物华。","潇然尘?外，得句转堪誇。"]},{"t":"王百谷谓余久不调意诗为祟也赋答二首 其一","f":"五言律诗","c":["久欲蠲诗癖，三缄渐废言。","官閒时见猎，业在匪专门。","五斗知何物，千秋用自存。","惊人仍丽句，留滞不须论。"]},{"t":"王百谷谓余久不调意诗为祟也赋答二首 其二","f":"五言律诗","c":["海内论骚雅，登坛几代兴。","江山留汗漫，风月竞腾凌。","工自穷应得，吟随困转增。","诗魔宁有祟，天意或堪凭。"]},{"t":"闻雁","f":"五言律诗","c":["羡尔云中雁，春深又北翔。","如何天畔客，岁久尚南荒。","心岂虞缯缴，谋非为稻粱。","静观群物理，漂泊负随阳。"]},{"t":"方生志赓自三吴归索一言以寿其尊人为赋二首 其一","f":"五言律诗","c":["游子心千里，瞻云海一方。","春晖遥爱日，彩服待持觞。","酒酿沧波阔，歌翻白雪长。","倚门仍有望，健翮早飞扬。"]},{"t":"方生志赓自三吴归索一言以寿其尊人为赋二首 其二","f":"五言律诗","c":["旧业资青简，传家事素王。","问奇杨子宅，通德郑公乡。","岁月看逾远，诗书泽未央。","冈陵何所颂，承志在明光。"]},{"t":"寒食后试新茶因忆故山植茶先垄之畔间别者数年矣","f":"五言律诗","c":["何处茶山好，云腴美建溪。","黄芽先蛰出，紫笋入春齐。","持赠逢新火，斜封认远题。","故园应比昔，客梦几樵西。"]},{"t":"惜春四首 其一","f":"五言律诗","c":["客舍馀三月，尘途又一春。","光阴频改岁，风物却愁人。","桃李俱成实，葵榴复渐新。","重来双语燕，如解识相亲。"]},{"t":"惜春四首 其二","f":"五言律诗","c":["几日春将尽，飞花到夏初。","游丝萦陇树，新笋傍畦蔬。","客久谙齐物，愁来学著书。","云山千里外，风雨梦吾庐。"]},{"t":"惜春四首 其三","f":"五言律诗","c":["海畔春常早，炎蒸亦更先。","暖风初启蛰，暑雨旋盈阡。","物候过鶗鴂，谷声响杜鹃。","客怀何所寄，空自惜流年。"]},{"t":"惜春四首 其四","f":"五言律诗","c":["晴雨长相半，山容望转佳。","叶齐烟漠漠，林静鸟喈喈。","云气过亭幔，溪声入舫斋。","伤春无限事，独坐酌茅柴。"]},{"t":"车一中明府报绩寄赠二首 其一","f":"五言律诗","c":["昔年三辅地，挥麈共谈天。","一别风尘隔，相怀道路偏。","握符分海甸，应宿耀星缠。","喜尔书劳最，堪追汉吏贤。"]},{"t":"车一中明府报绩寄赠二首 其二","f":"五言律诗","c":["烽火边亭密，诛求里巷繁。","抡才资保障，别利试盘根。","远徼听舆颂，中朝得主恩。","飞凫将万里，留滞愧同论。"]},{"t":"春日病肺二首 其一","f":"五言律诗","c":["改岁方盈月，韶光逐望开。","畏寒仍伏枕，听雨废传杯。","入树莺交坐，窥檐燕未回。","不言桃与李，朝暮为谁催。"]},{"t":"春日病肺二首 其二","f":"五言律诗","c":["节是中和候，人非卧病时。","雨馀山转丽，寒歛树多姿。","社赛宜春酒，池添梦草诗。","不须传七发，强欲对花枝。"]},{"t":"观刈麦","f":"五言律诗","c":["布谷声初定，欣看麦已秋。","两岐虚颂瑞，八口但消忧。","地薄难盈室，心劳岂植畴。","独怜春雨足，兼可望瓯窭。"]},{"t":"新笋二首 其一","f":"五言律诗","c":["旧干依檐出，新芽拆藓来。","清标霜里劲，生意地中回。","何日能栖凤，先春解友梅。","琴囊与诗卷，还并绿阴开。"]},{"t":"新笋二首 其二","f":"五言律诗","c":["有美凌霜操，千竿羡渭滨。","檀栾开隙地，幽洒绝纤尘。","山月摇光碎，溪烟染翠匀。","频移新雨后，到处易为春。"]},{"t":"雨中答慰林茂才","f":"五言律诗","c":["海上多梅雨，途中滞客衣。","雾当松径合，寒共佛灯微。","骨肉经时别，山川几梦归。","登楼闻作赋，怜尔谬相依。"]},{"t":"久雨二首 其一","f":"五言律诗","c":["燕拂山云满，龙吟壑雾宽。","悬厓皆响瀑，入夜迥生寒。","耕叹霖为潦，行歌路正难。","晚当虹饮涧，倚杖隔林看。"]},{"t":"久雨二首 其二","f":"五言律诗","c":["望海仍为雨，看山尚出云。","林鸠非唤妇，江鹳乱呼群。","天地愁常暝，莺花爱晚曛。","气蒸霞欲变，万里见晴氛。"]},{"t":"佛日","f":"五言律诗","c":["觉路迷尘鞅，空门愧静虚。","心应藏定慧，性自合真如。","礼塔闻金磬，开堂响木鱼。","宰官云可度，吾亦傍僧庐。"]},{"t":"屡丰亭看山五首 其一","f":"五言律诗","c":["半亩随官舍，千岩面众山。","雨鸣溪泼泼，风递鸟关关。","寓目何妨远，会心长自閒。","无须烦蜡屐，选胜待跻攀。"]},{"t":"屡丰亭看山五首 其二","f":"五言律诗","c":["背郭连苍霭，为园护翠微。","峰峦千叠秀，涧道百泉飞。","花落红初歛，阴浓绿转肥。","非关忘物累，惟觉簿书稀。"]},{"t":"屡丰亭看山五首 其三","f":"五言律诗","c":["孤亭山下出，四野坐中看。","缥缈丹霞度，参差绿树攒。","松闻风淅历，竹报日平安。","扫石俱堪坐，羁愁但自宽。"]},{"t":"屡丰亭看山五首 其四","f":"五言律诗","c":["讼简閒应得，公馀隐亦兼。","云流随近远，山色任浓纤。","短槛花相绕，疏林笋为添。","尘心如涤尽，趺坐看楞严。"]},{"t":"屡丰亭看山五首 其五","f":"五言律诗","c":["为爱山容好，都忘吏事劳。","捲帘青嶂入，隐几白云高。","荒似陶潜径，幽同仲蔚蒿。","拄颐多觉爽，飞翠落松涛。"]},{"t":"晚憩园亭","f":"五言律诗","c":["闭户无人过，凭轩到日西。","草为书带长，苔似蔓金齐。","选地看除径，呼僮学灌畦。","客怀偏自动，风静鹧鸪啼。"]},{"t":"寄答张幼于二首 其一","f":"五言律诗","c":["吴会多才子，君家并国工。","高谈倾稷下，独步失江东。","赤帜谁争长，清尊未可同。","传来新丽句，累牍羡词雄。"]},{"t":"寄答张幼于二首 其二","f":"五言律诗","c":["十载空吟越，双钩自美吴。","文成辉五凤，价重等三都。","下里知难和，中原几并驱。","阊门应弭棹，看尔立操觚。"]},{"t":"与客谈西事二首 其一","f":"五言律诗","c":["兵革年来苦，西南衅复开。","兴师勤薄伐，授钺急渠魁。","豕突虞穷寇，鹰扬藉异才。","功成是何日，奏捷羽书回。"]},{"t":"与客谈西事二首 其二","f":"五言律诗","c":["重镇新开府，孤军渐合符。","谋臣多聚米，与国共飞刍。","业更期安堵，悲应免向隅。","论功谁第一，麟阁貌堪图。"]},{"t":"四明毛生为余绘雁图四幅悬之壁间令人有沧洲之想","f":"五言律诗","c":["近识四明客，浮来海上槎。","心专毫素业，迹异博徒家。","匠意丹青巧，游神水石嘉。","潇湘如在目，落雁满平沙。"]},{"t":"褚邑丞以署捕有功院道交奖二首 其一","f":"五言律诗","c":["百里分司牧，千家颂有丞。","全牛看解刃，一鹤对凝冰。","心为穷檐苦，名堪长吏称。","四方今上计，于尔识廉能。"]},{"t":"褚邑丞以署捕有功院道交奖二首 其二","f":"五言律诗","c":["里巷倾豪举，鱼盐挟重赀。","诘奸知胆碎，禦暴见风移。","丹凤腾应远，黄龙兆愈奇。","天曹徵吏绩，誉命此为基。"]},{"t":"寄家书二首 其一","f":"五言律诗","c":["自我违松菊，风尘几不堪。","集忧将满百，缄口未能三。","当户谁称虎，于田或舞骖。","骞腾迟羽翮，何日见图南。"]},{"t":"寄家书二首 其二","f":"五言律诗","c":["看云移白日，乡梦渺愁余。","画虎书频达，屠龙技久虚。","未须惭后乘，且自戒前车。","末路知何似，吾将赋遂初。"]},{"t":"马江候潮","f":"五言律诗","c":["舟楫徒能具，江湖未可行。","转移天地力，留滞古今情。","风漾鸥波细，潮平鹭渚生。","中流看鼓舵，更听棹歌声。"]},{"t":"答林生于玄","f":"五言律诗","c":["海滨留渐久，汉阙望逾高。","造士功何似，忧时念转劳。","迁难超贾傅，贤愧颂王褒。","他日长怀处，诗篇咏木桃。"]},{"t":"答林生君勉","f":"五言律诗","c":["分符淹远宦，化士岂文翁。","桃李无言外，风云变态中。","抡才需北阙，奏赋待南宫。","海色看鹏运，扶桑晓日红。"]},{"t":"闻蝉","f":"五言律诗","c":["大野腾朝旭，芳郊逗远风。","露华知久洁，林响听初同。","渐彻层霄外，长吟化日中。","一枝元自足，感尔思无穷。"]},{"t":"新造舟成与客同泛二首 其一","f":"五言律诗","c":["一苇应难渡，芳洲采木兰。","功成堪利涉，兴在且追欢。","鸥鹭吟边狎，云山望里宽。","风涛长愿息，凉月趁清澜。"]},{"t":"新造舟成与客同泛二首 其二","f":"五言律诗","c":["往返何尝定，江行屡买舟。","忽看浮彩鹢，试共泛清流。","鱼鸟皆成趣，烟波未倦游。","潇然逃暑外，倚棹对沧洲。"]},{"t":"貤恩初下感赋四首 其一","f":"五言律诗","c":["薄宦吾诚拙，君恩喜渐回。","微劳俱不泯，先德故能培。","锡服沾殊典，弹冠及夜台。","九原难复作，风木转堪哀。"]},{"t":"貤恩初下感赋四首 其二","f":"五言律诗","c":["汨没风尘久，鸾书始见褒。","岂因循绩异，庶录义方劳。","就日尧阶远，瞻天汉阙高。","涓埃时欲报，心逐五陵豪。"]},{"t":"貤恩初下感赋四首 其三","f":"五言律诗","c":["往事何须问，承恩孰后先。","幸犹烦记忆，敢自怨留连。","岵屺怀俱积，幽明赉并宣。","异时毕犬马，何以答尧天。"]},{"t":"貤恩初下感赋四首 其四","f":"五言律诗","c":["椿萱成隔世，薄命久荒丘。","菽水欢难足，糟糠愿未酬。","存亡空有恨，俯仰不须愁。","操作还荆布，蘋蘩尚可修。"]},{"t":"和区宫允寄示太液池闻雁之作","f":"五言律诗","c":["灵洲通艺苑，仙液类词源。","晓直趋常早，宸居静不喧。","鹓鸿时并集，霄汉近孤骞。","何似群鸣者，荒烟傍海村。"]},{"t":"答康孟担二首 其一","f":"五言律诗","c":["双鱼何处达，沧海夜生潮。","九漈灵源渺，三山驿路遥。","交神俱翰藻，迹混半渔樵。","字字投珠玉，缄书乏报瑶。"]},{"t":"答康孟担二首 其二","f":"五言律诗","c":["清淑回闽海，词才近若云。","登坛谁竞赏，空谷汝先闻。","拙宦成漂梗，知交久断群。","山阴如弭棹，邀月更论文。"]},{"t":"秋霖大作兼疾风竟日感赋三首有引 其一","f":"五言律诗","c":["山下城如斗，千家共结庐。","风生潮怒后，雨挟海波馀。","谷口奔成潦，溪声溜决渠。","临流三五户，犹恐复为鱼。"]},{"t":"秋霖大作兼疾风竟日感赋三首有引 其二","f":"五言律诗","c":["百雉沿山麓，穿城导众流。","金汤宁恃险，摇落早知秋。","拔木风逾劲，翻盆雨未休。","小民虞及溺，难自听沉浮。"]},{"t":"秋霖大作兼疾风竟日感赋三首有引 其三","f":"五言律诗","c":["何意抱关者，翻操造物权。","剖藩方远险，疏滞得防川。","顺水行无事，康居乃重迁。","未论关禁弛，且幸已图全。"]},{"t":"送从弟少乘还乡二首 其一","f":"五言律诗","c":["握手他乡别，繁霜拂剑花。","官贫腰但折，旅逐鬓将华。","嘲白宁甘寂，怀黄未可誇。","归与荒径外，先为卜宜瓜。"]},{"t":"送从弟少乘还乡二首 其二","f":"五言律诗","c":["海滨留滞日，分袂况斯时。","远道无由息，他乡有所思。","世情憎宦达，吾意虑归迟。","事业将看汝，东篱早咏诗。"]},{"t":"闻谤答林于玄","f":"五言律诗","c":["芳草年年绿，桃今几度花。","好移青雀舫，去傍白鸥沙。","新水烟初净，名山雾不遮。","世情君莫问，趺坐对南华。"]},{"t":"读郑参知传","f":"五言律诗","c":["先生天下士，墓木已苍苍。","寒后知松柏，群中有凤凰。","君王思汲黯，岭海念桐乡。","堪笑当年事，萋菲亦似簧。"]},{"t":"答陈子东","f":"五言律诗","c":["少年追昔日，观国早为宾。","廿载称牛马，何时问鬼神。","世多轻傲吏，吾自佩先民。","却喜归三径，花间任葛巾。"]},{"t":"挽郑文学","f":"五言律诗","c":["自古天难问，盈虚未可论。","斯人去已远，遗业至今存。","萧艾春同长，鱼龙夜不喧。","层霄看羽翮，何日见腾骞。"]},{"t":"答林士岩","f":"五言律诗","c":["世事皆观奕，流年总掷梭。","悲欢恒易老，得丧定谁多。","沧海终须变，浮云任自过。","同仇知汝切，无用赋脩戈。"]},{"t":"抵家后答林君勉二首 其一","f":"五言律诗","c":["昔居滨海地，日上望乡台。","一自离萍梗，相安弃草莱。","无能思养拙，清论付程才。","喜尔还追忆，椷书特远来。"]},{"t":"抵家后答林君勉二首 其二","f":"五言律诗","c":["鼓棹出江湾，风涛动旅颜。","愤难甘蹈海，愚或笑移山。","翘首烟霄外，论心意气间。","雄文终遇合，且傍舞衣班。"]},{"t":"初秋苏叔大招同张仪仲集玄畅堂","f":"五言律诗","c":["伏日炎蒸尽，秋阴爽气鲜。","莼鲈因客久，鸡黍幸君怜。","意自酣馀畅，谈从物外玄。","坐中能赋者，莫诵四愁篇。"]},{"t":"康孟担至自闽","f":"五言律诗","c":["百折闽溪水，归来始就安。","菊苗荒再绿，荔子熟逾丹。","世网从添密，诗盟自不寒。","喜君能命驾，杯酒复同欢。"]},{"t":"姜生磻支自闽来请传其贞母董孺人特嘉勉之赋别二首 其一","f":"五言律诗","c":["世远龙峰下，诗书泽未寒。","始缘家不造，转觉路俱难。","事往悲黄鹄，恩来待紫鸾。","有怀知罔极，休恐误儒冠。"]},{"t":"姜生磻支自闽来请传其贞母董孺人特嘉勉之赋别二首 其二","f":"五言律诗","c":["吏隐孤城日，诸贤忆论文。","山间遍桃李，海上几风云。","虎口惊初定，羊肠望已分。","远天来独鹤，应是出鸡群。"]},{"t":"春日","f":"五言律诗","c":["廿载婴尘网，今方物外游。","閒居聊自赋，世路岂深忧。","梦返隍中鹿，机閒海上鸥。","阳回春事足，吾道本沧洲。"]},{"t":"康山人以新刻锦囊寄示兼有诗劝驾赋此答之","f":"五言律诗","c":["自得幽居趣，无心复汉关。","林泉偏浪迹，猿鹤与同閒。","世态风尘外，知交梦寐间。","著书诚羡汝，堪为副名山。"]},{"t":"赠日者邓生","f":"五言律诗","c":["我自谙齐物，而君善阅人。","林塘新雨净，帘肆一家春。","墨妙多徵贵，谈高解逐贫。","百钱都市日，何异此藏身。"]},{"t":"老人星","f":"五言律诗","c":["天上年何极，长瞻寿有星。","五云连碧落，万里映珠庭。","处士潜光久，贤人聚德馨。","由来俱借耀，千仞烛高冥。"]},{"t":"忆罗浮兼寄何使君二首 其一","f":"五言律诗","c":["屡爽罗浮约，山灵或笑人。","林泉堪浪迹，岩洞几经春。","五鹊时还集，千花岁并新。","寒梅如有待，迟暮转相亲。"]},{"t":"忆罗浮兼寄何使君二首 其二","f":"五言律诗","c":["山色年年好，难逢地主贤。","帷搴朱洞外，榻下铁桥边。","剩有登楼月，俱无警堠烟。","安民多渤海，游骑喜相连。"]},{"t":"送郑别驾督鹾还西粤兼柬薛使君二首 其一","f":"五言律诗","c":["有美家声旧，能忘吏事劳。","官淹庞统骥，佩羡吕虔刀。","早识驹千里，争看凤一毛。","临岐方怅别，西望岭云高。"]},{"t":"送郑别驾督鹾还西粤兼柬薛使君二首 其二","f":"五言律诗","c":["自返闽江棹，相逢却有君。","风尘俄握手，花月几论文。","吏隐鱼盐混，心知道路分。","交亲如问讯，烟水鹭鸥群。"]},{"t":"郊居八咏 其一 廓处堂","f":"五言律诗","c":["草野自寥廓，茅堂此隐沦。","傍林驯鸟雀，开径剪荆榛。","道路风尘息，烟霞岁月新。","浮云随去住，别有一家春。"]},{"t":"郊居八咏 其二 善息斋","f":"五言律诗","c":["岁月疲奔走，归来却就安。","吾庐知自爱，世路识俱难。","偃仰但怀土，风波始息湍。","图南嗟羽翼，聊作一枝看。"]},{"t":"郊居八咏 其三 酿秫斋","f":"五言律诗","c":["万事无过酒，壶觞日可亲。","岩耕多种秫，村酿足娱宾。","滴处愁随破，呼来态转新。","醉乡于此觅，花落自成茵。"]},{"t":"郊居八咏 其四 众芳亭","f":"五言律诗","c":["不厌蓬蒿满，孤亭杂众芳。","竹如三径绿，桂似小山苍。","薋菉宁芜秽，松梅自雪霜。","琴樽聊寄适，未拟百花庄。"]},{"t":"郊居八咏 其五 濯尘轩","f":"五言律诗","c":["款段来城郭，缁尘不可挥。","避喧循野径，访隐到林扉。","曲水堪修褉，沧浪此振衣。","风埃满天地，洞户有清晖。"]},{"t":"郊居八咏 其六 洗墨池","f":"五言律诗","c":["雅爱临池诀，风流忆二王。","毫端宁有彩，诗里祗添狂。","洗砚冲鱼沫，操觚染树香。","小亭宜醉墨，云影落方塘。"]},{"t":"郊居八咏 其七 覆奕台","f":"五言律诗","c":["玩世皆观奕，为园独有台。","移枰依竹树，坐石拥蒿莱。","先后宁遗算，输赢莫浪猜。","解围常竟日，荜户约重开。"]},{"t":"郊居八咏 其八 投辖井","f":"五言律诗","c":["林泉偏引兴，杖屦喜相同。","玩世多浮白，伤春几落红。","棋弹花外雨，翰染竹间风。","甘寂宁遗俗，留宾比孟公。"]},{"t":"重阳前一日林希平民部招饮丛桂山房时桃花与菊并开亦奇事也诗纪之二首 其一","f":"五言律诗","c":["未约龙山饮，先攀桂树丛。","人俱白社客，地似碧云宫。","菊艳今应紫，桃花亦自红。","阳和偏有意，晚暮喜春同。"]},{"t":"重阳前一日林希平民部招饮丛桂山房时桃花与菊并开亦奇事也诗纪之二首 其二","f":"五言律诗","c":["地主多招赏，花神故献奇。","林风吹旷莽，海月照涟漪。","秉烛因清夜，移樽傍曲池。","茱萸明日酒，孰与此中宜。"]},{"t":"九月既望陈勋卿招同穆王二令公登龙津逍遥楼望西樵诸山既暮移酌于东轩就月漫赋二首 其一","f":"五言律诗","c":["未尽登高兴，深樽正可亲。","篱花初满径，秋月更重轮。","野俗看仍朴，康谣听转新。","莫疑双剑合，此地是龙津。"]},{"t":"九月既望陈勋卿招同穆王二令公登龙津逍遥楼望西樵诸山既暮移酌于东轩就月漫赋二首 其二","f":"五言律诗","c":["出郭陪幽赏，临高望故山。","桑麻驯雉地，烟水钓鱼湾。","舄欲淩风起，车留载月还。","客游吾已倦，偏恋狎鸥閒。"]},{"t":"谭太学以春明赴选其诸子于先冬十月开宴为寿索赠二首 其一","f":"五言律诗","c":["衣马追游地，春风念五陵。","梅花今似雪，竹叶况如渑。","诣阙书初就，贻家庆转增。","图南多健翮，天路总骞腾。"]},{"t":"谭太学以春明赴选其诸子于先冬十月开宴为寿索赠二首 其二","f":"五言律诗","c":["欲赴弹冠庆，贪欢舞袖斑。","裁诗俱白雪，对酒倍朱颜。","志壮曾题柱，经传岂度关。","南山他日颂，留待锦衣还。"]},{"t":"对菊忆杜句云每恨陶彭泽无钱对菊花因用钱字","f":"五言律诗","c":["菊花何太妍，摇落暮秋天。","幽意真相惬，孤芳剧可怜。","对吟堪竟日，服食更延年。","但喜东篱满，何须复问钱。"]},{"t":"读重明纪异录二首有序 其一","f":"五言律诗","c":["大夫将母日，纯孝格旻天。","久视留难老，重明岂偶然。","手中还密线，镜里任华颠。","逐子西征后，亲看展骥年。"]},{"t":"读重明纪异录二首有序 其二","f":"五言律诗","c":["传家勋节茂，德聚感仙灵。","露浥萱逾秀，云开婺转荧。","阶庭重戏綵，里闬更垂青。","母视从天视，应教护晚龄。"]},{"t":"张明府六载考绩二首 其一","f":"五言律诗","c":["六载张君政，讴歌遍海乡。","楚材工制锦，汉署待含香。","泽普花封雨，名高柏府霜。","中朝徵异等，早晚觐明光。"]},{"t":"张明府六载考绩二首 其二","f":"五言律诗","c":["薄海真多幸，琴鸣几度花。","量留因保障，召对首清华。","绣斧频推毂，铜章两及瓜。","持衡需启事，知不负皇家。"]},{"t":"至后为李茂才兄弟寿母","f":"五言律诗","c":["节是书云后，堂开献寿初。","海邦符鲁颂，洛涘引潘舆。","爱日欣长至，承欢集庆馀。","层霄三凤羽，应渐送吹嘘。"]},{"t":"瘿木杯有引","f":"五言律诗","c":["劲质依山涧，何心匠石知。","成能非强饰，致用出离奇。","浮处皆为白，行来但诉迟。","金罍堪并列，玉醴总相宜。"]},{"t":"初春十日陈明佐勋卿招同诸公观灯","f":"五言律诗","c":["令节今宵始，宾筵此会高。","城开新菡萏，酒满旧葡萄。","笔为同声试，杯逾隔岁豪。","主人兼爱客，清夜不知劳。"]},{"t":"赠孙户侯","f":"五言律诗","c":["名家推汗血，天路识霜蹄。","推毂才雄擅，弃繻英妙齐。","虎头铜柱外，猿臂玉关西。","今日麒麟阁，功成待尔题。"]},{"t":"答友人客夜见贻","f":"五言律诗","c":["揽衣起难寐，孤灯见客情。","春寒淹夜坐，细雨到天明。","怀土悲王粲，忧时类贾生。","好文当主圣，何日识君名。"]},{"t":"为刘茂才寿其伯隐君","f":"五言律诗","c":["小隐蓬为径，同游竹是林。","冬桃千岁实，春酒百年心。","经暇时娱綵，樽开满盍簪。","兴来因小阮，徙倚复长吟。"]},{"t":"送穆令公入觐二首 其一","f":"五言律诗","c":["辑瑞由虞典，分符藉楚材。","鸣骖俨上路，应宿近中台。","海国烟消日，山程雪霁梅。","圣朝方久任，多是赐金回。"]},{"t":"送穆令公入觐二首 其二","f":"五言律诗","c":["五凤祥云拥，双凫瑞色浮。","玺书辉紫殿，锦服照黄州。","郡国谁高第，关山自壮游。","重来念竹马，莫恋梓乡留。"]},{"t":"刘太学兄弟自闽来访答和二首 其一","f":"五言律诗","c":["上客皆金友，名家自玉人。","登龙难并拟，命驾喜相亲。","设类穆生醴，交逾公瑾醇。","乡心且莫切，作伴待青春。"]},{"t":"刘太学兄弟自闽来访答和二首 其二","f":"五言律诗","c":["拟赋从军乐，翻成访旧来。","莫思身外事，且覆掌中杯。","爱客深投辖，怀人更酌罍。","谁当吹玉律，幽谷动寒灰。"]},{"t":"冬夜","f":"五言律诗","c":["冬夜何如永，寒天未肯明。","穿帘残月影，欹枕远鸡声。","仙梦宁关达，微吟自解酲。","倦眠翻起早，难待日东生。"]},{"t":"为俞生初诞子作二首 其一","f":"五言律诗","c":["海日当长至，门弧应瑞开。","凤雏宁世出，龙种自天才。","窦苑方称桂，王家旧植槐。","登筵多玉果，任醉酒千杯。"]},{"t":"为俞生初诞子作二首 其二","f":"五言律诗","c":["种玉知何始，徵兰在粤城。","充闾初有子，当户此为兄。","练影天中见，珠光掌上生。","多男何俟祝，次第识英声。"]},{"t":"蟠桃图","f":"五言律诗","c":["嘉树何年植，花殷实渐成。","蒸霞先海色，和露足春荣。","液美灵岩髓，香分汉苑茎。","与君持介寿，驾鹤伴吹笙。"]},{"t":"感事二首 其一","f":"五言律诗","c":["阅世逢之子，艰危记并驱。","祇知明得意，未解识穷途。","显晦殊先后，升沉定有无。","至今樽酒外，何地著潜夫。"]},{"t":"感事二首 其二","f":"五言律诗","c":["自许风尘上，乾坤眼底空。","红颜翻易掷，白眼转相同。","逐客书难问，长门赋未工。","为君思往事，真负气如虹。"]},{"t":"梁宪父馆于罗太学家董叔远冯文孺有作次和","f":"五言律诗","c":["上客非高馆，何缘见爱才。","南州逢榻下，北海仗樽开。","翰墨论心富，莺花逐赏来。","主人方梦鸟，堪杂夜明苔。"]},{"t":"孙氏先茔嘉瓜二首 其一","f":"五言律诗","c":["异矣孙钟墓，相传孝可嘉。","感符人化鹤，祥协地宜瓜。","玉井无须羡，朱陵总浪誇。","绵绵比周瓞，他日庆逾赊。"]},{"t":"孙氏先茔嘉瓜二首 其二","f":"五言律诗","c":["改卜茔新兆，泉台傍鲁坡。","山川随地胜，雨露得天和。","积石根元美，东陵事若何。","诸孙能嗣业，应比故侯多。"]},{"t":"答罗尊生","f":"五言律诗","c":["阅世知音少，何因遇子期。","每看高士传，愧勒北山移。","艺苑交如石，流年鬓易丝。","霜蹄开道路，历国总称奇。"]},{"t":"为黎学博题琴书图二首 其一","f":"五言律诗","c":["当年谢羁勒，一径返烟萝。","散帙娱清暇，鸣弦续咏歌。","广陵传后少，禹穴秘中多。","扰扰红尘者，相看意若何。"]},{"t":"为黎学博题琴书图二首 其二","f":"五言律诗","c":["衡门多乐事，何事最相宜。","会意丝桐远，搜神汗竹奇。","圣贤终日对，山水几人知。","儒雅风流并，如君实可师。"]},{"t":"海天松鹤图","f":"五言律诗","c":["共美千年鹤，来依百尺松。","樛枝罥海雾，健翮伫天风。","阅世冰霜久，巢云岁月同。","九皋闻远近，长是应雌雄。"]},{"t":"解邑丞兼郡捕得代还东官二首 其一","f":"五言律诗","c":["贰职双凫最，空群一鹗先。","海方歌赞府，幕下借曹椽。","舒卷忘情外，腾淩议法前。","通才需妙选，随地副班联。"]},{"t":"解邑丞兼郡捕得代还东官二首 其二","f":"五言律诗","c":["佐邑称能吏，兼曹重外台。","绸缪资画诺，保障涤氛埃。","莲幕三城颂，花封百里回。","名因趋府达，当宁解抡才。"]},{"t":"和吴逸士读小刻有作","f":"五言律诗","c":["几忆王孙草，忽传幼妇词。","隐高商皓迹，和有郢人诗。","大雅千秋业，清风百世师。","知君能载酒，独愧子云奇。"]},{"t":"答族侄子馨旅中见怀","f":"五言律诗","c":["露气沾残暑，秋声送早凉。","琴樽怜夜月，书剑返江乡。","何日云鹏起，他山雾豹藏。","主人能爱客，旅思不须伤。"]},{"t":"与诸同年话别于飞云洞二首有引 其一","f":"五言律诗","c":["留滞乡园久，无心更出山。","圣人方罪己，逐客岂投閒。","未敢终违世，何妨更抱关。","招邀惭已再，花下强酡颜。"]},{"t":"与诸同年话别于飞云洞二首有引 其二","f":"五言律诗","c":["廿载通贤籍，难期聚会同。","关山时去住，岐路复西东。","已慕汉阴叟，还希塞上翁。","浪游随所适，终自愧冥鸿。"]},{"t":"辞三司诸公招饯","f":"五言律诗","c":["蓬巷幽栖久，公庭礼法疏。","薄游思汗漫，野服出樵渔。","自觉惭虚席，何劳望小车。","年来俱饱德，无待接宾庐。"]},{"t":"勖崔甥二首 其一","f":"五言律诗","c":["明堂需巨栋，资用匪枚条。","耕凿安时俭，弓旌待国招。","简编聊自富，岁月岂徒消。","羽翼南溟徙，吹嘘或不遥。"]},{"t":"勖崔甥二首 其二","f":"五言律诗","c":["儒冠看嗣业，取效岂寥寥。","力及千钧弩，功殊五石瓢。","贻谋思作室，壮志慕题桥。","仙液终应就，飞腾越世嚣。"]},{"t":"三水舟中别诸亲族二首有引 其一","f":"五言律诗","c":["万里关山道，偏怜后会疏。","风霜仍旅食，花月想閒居。","前路谁知己，新诗重起余。","发船催叠鼓，倚棹更踟蹰。"]},{"t":"三水舟中别诸亲族二首有引 其二","f":"五言律诗","c":["俛仰思前度，魂销几弟兄。","归来重聚首，死别已吞声。","未论干时计，先伤造物情。","交亲期末路，珍重保馀生。"]},{"t":"过飞来寺","f":"五言律诗","c":["寺是前朝幻，舟曾几度过。","江山无恙在，道路此生何。","云气连帆影，谷声应棹歌。","茅堂堪避俗，回首愧烟萝。"]},{"t":"清溪驿阻风适制府戴公书至兼闻西所已报捷云","f":"五言律诗","c":["远道愁风色，停舟问水程。","冻云孤岫白，细雨一溪清。","杯酒阳关意，椷书杕杜情。","西征闻已捷，铙吹动军声。"]},{"t":"舟中寒雨二首 其一","f":"五言律诗","c":["水宿愁零雨，江寒傍客裘。","川原犹万里，漂泊且孤舟。","不为资三径，何缘薄一丘。","关心无限事，揣分愧宜休。"]},{"t":"舟中寒雨二首 其二","f":"五言律诗","c":["寒风催改岁，阴谷待回春。","旅鬓星星短，行厨日日贫。","室家携自累，僮仆转相亲。","即道京华好，难忘旧隐沦。"]},{"t":"读朱公叔绝交论","f":"五言律诗","c":["伐木歌求友，陈雷义独高。","知心谁缟带，恋旧几绨袍。","莫倚甘如醴，真防笑有刀。","古人交欲绝，著论岂徒劳。"]},{"t":"曲江夜雨","f":"五言律诗","c":["静夜风逾响，孤舟雨较多。","听篷惊梦断，欹枕奈愁何。","再想鸣珂入，初残扣角歌。","漫漫皆未旦，天路忆春和。"]},{"t":"晚霁二首 其一","f":"五言律诗","c":["夕照笼山霭，轻霞映水光。","冻消林卉木，暖入客衣裳。","莫自悲游子，教人说漫郎。","天涯信萍梗，或类酒诗狂。"]},{"t":"晚霁二首 其二","f":"五言律诗","c":["未尽江湖兴，转多羁旅情。","众星捲雾出，孤月带川明。","道路宽相忆，家山梦不成。","凄凉追往事，偏唤客愁生。"]},{"t":"度庾关","f":"五言律诗","c":["一入庾关道，方知楚粤分。","岭梅明霁雪，乡树迥看云。","水石应难恋，音书未可闻。","山川成异地，回首思纷纷。"]},{"t":"攸镇夜泊","f":"五言律诗","c":["石齿夹江悬，滩声永夜喧。","凄风鸣断岸，残月照高原。","独客无相问，孤舟谁晤言。","寒鸡催曙色，隐隐出荒村。"]},{"t":"立春日舟过南浦","f":"五言律诗","c":["鼓枻西江道，开樽异地春。","土牛随俗远，綵燕为谁新。","雪片残疏柳，风光转弱蘋。","千门俱淑气，何处可相亲。"]},{"t":"除夕寓玉山客舍","f":"五言律诗","c":["守岁萍蓬里，停骖信宿间。","两宵看腊去，三日见春还。","万里趋金阙，孤灯傍玉山。","天时与人事，客况总相关。"]},{"t":"初春自玉山度岭","f":"五言律诗","c":["率土新王月，他乡有渭城。","阶知蓂渐发，池梦草初生。","去逐春宵雁，行听禁苑莺。","鸡声催晓曙，立马更含情。"]},{"t":"过严子陵钓台","f":"五言律诗","c":["鼓棹出桐江，孤舟类钓艭。","烟霞迹自混，湖海意难降。","千古尊严濑，一丝重汉邦。","客星今寂寂，明月照船窗。"]},{"t":"正月十六夜泊舟槜李城下时天霁月出漫赋二首 其一","f":"五言律诗","c":["万里途方半，千金夜未休。","去年今夕酒，一别几般愁。","士女争浮舫，笙歌别上楼。","寥寥天畔客，漂泊正孤舟。"]},{"t":"正月十六夜泊舟槜李城下时天霁月出漫赋二首 其二","f":"五言律诗","c":["向愁江雨阔，今见海蟾生。","城郭春仍丽，帆樯夜转明。","孤灯篷底思，独酌旅中情。","可惜良宵里，长吟作越声。"]},{"t":"由云阳登陆途中杂咏五首 其一","f":"五言律诗","c":["吴越舟初系，维扬渡不迷。","山川馀应接，岐路任东西。","宦迹存鸡肋，春风送马蹄。","王孙游莫倦，芳草正萋萋。"]},{"t":"由云阳登陆途中杂咏五首 其二","f":"五言律诗","c":["旅席何曾暖，严程不暂遑。","窗间蝴蝶梦，天上鹭鹓行。","晓曙疏星白，风沙大陆黄。","主人粱正熟，驱马复他乡。"]},{"t":"由云阳登陆途中杂咏五首 其三","f":"五言律诗","c":["客路春山远，乡心海国遥。","澹烟催柳变，细雨濯花娇。","策马过回岸，听鸡度板桥。","王遵叱驭意，多恋圣明朝。"]},{"t":"由云阳登陆途中杂咏五首 其四","f":"五言律诗","c":["浊酒当春候，缁尘又客衣。","梨花开野店，燕子入山扉。","已逐行程远，休嫌乐事违。","上林香满树，还待日辉辉。"]},{"t":"由云阳登陆途中杂咏五首 其五","f":"五言律诗","c":["廿载风尘役，三春道路人。","瞻天行渐近，知己仗谁亲。","漂泊悲游子，支离笑逐臣。","绝怜芳草色，随处傍征轮。"]},{"t":"京邸即事二首 其一","f":"五言律诗","c":["独客愁难破，经时念转劳。","园林开芍药，寝庙荐樱桃。","乳燕巢檐急，归鸿绝塞高。","山川凝望远，诗兴为谁豪。"]},{"t":"京邸即事二首 其二","f":"五言律诗","c":["青阳初改谢，绿叶始交加。","细雨生榆荚，微风起楝花。","寂寥虚客况，漂泊感年华。","骨肉两乡远，谁能不念家。"]},{"t":"出京答黄士明吉士","f":"五言律诗","c":["再入长安道，相逢愧逐喧。","文雄官自达，骨傲位难尊。","我更莲花府，君惟竹素园。","预知供奉日，应制几千言。"]},{"t":"将晓渡江","f":"五言律诗","c":["挂席出邗沟，长江接远流。","晴霞光海树，初日起沙鸥。","山色微浮玉，潮痕不辨牛。","忽过京口渡，绝爱晓风柔。"]},{"t":"晚泊广济桥","f":"五言律诗","c":["清浅河桥下，犹传广济名。","画图山里色，环佩水中声。","数幅云帆远，千层雪浪平。","往来多信宿，不尽古今情。"]},{"t":"过草萍驿","f":"五言律诗","c":["楚越间关道，篮舆又草萍。","苔文滋锦石，云气点苍屏。","扰扰浮生役，劳劳送客亭。","秋风迟落木，山较往时青。"]},{"t":"初至豫章","f":"五言律诗","c":["匹马出长安，山川路渺漫。","候人催赴幕，先达笑弹冠。","拙宦羁微禄，非才免素餐。","公馀仍野服，不省是何官。"]},{"t":"余继中都曹招看花二首 其一","f":"五言律诗","c":["地僻元藏拙，官閒更避喧。","花神招密坐，酒态美芳尊。","菊艳先秋发，兰芽过雨繁。","绕庭栽茉莉，睹物尽乡园。"]},{"t":"余继中都曹招看花二首 其二","f":"五言律诗","c":["满座长留客，分曹静放衙。","开帘调舞鹤，入座绕繁花。","胜算棋偏敌，高谈日欲斜。","非君时命酒，何以度年华。"]},{"t":"和何郡丞元日郡楼眺望","f":"五言律诗","c":["物态时时改，春光岁岁逢。","江山留宦迹，花鸟悦尘容。","望阙心千绪，怀人路几重。","岂堪持柏酒，独酌对晴峰。"]},{"t":"送陈任二君入贺长至二首 其一","f":"五言律诗","c":["江国逢秋尽，征轺望阙回。","繁霜沾玉勒，霁雪傍金台。","岁事仍长至，皇休正大来。","向疑帘陛远，阊阖为君开。"]},{"t":"送陈任二君入贺长至二首 其二","f":"五言律诗","c":["帝里瞻天近，王程计日长。","榻思违仲举，御喜得元方。","雪瑞瞻双阙，嵩呼动一阳。","礼成需后会，且莫厌他乡。"]},{"t":"追远诗为张显之赋二首 其一","f":"五言律诗","c":["自得阳城教，偏多狄相思。","陔兰生永慕，风木有馀悲。","捧檄伤乌养，遗经重燕贻。","承恩看奕叶，方信显亲时。"]},{"t":"追远诗为张显之赋二首 其二","f":"五言律诗","c":["已荷丝纶诏，难忘岵屺心。","松楸看渐远，雨露感弥深。","爱日欢能几，终天恨不禁。","显扬知未艾，宁自愧朝簪。"]},{"t":"铁柱宫二首有序 其一","f":"五言律诗","c":["墨绶辞荣日，黄冠入道时。","嵩阳元法地，章水亦瑶池。","柱藉千年镇，宫开万寿基。","睹河思禹绩，移颂大江湄。"]},{"t":"铁柱宫二首有序 其二","f":"五言律诗","c":["赖有诛邪法，堪成拯溺功。","支祁妖自伏，罔象怪应穷。","拔宅登玄阆，遗祠礼玉隆。","鲸鲵多未戮，剑术可能工。"]},{"t":"答邓介繁远寄二首 其一","f":"五言律诗","c":["岁月疲奔走，山林道转尊。","水云淹粤海，吏隐忆江藩。","命驾谁千里，长城自五言。","汉文称有道，何日更承恩。"]},{"t":"答邓介繁远寄二首 其二","f":"五言律诗","c":["寄兴多山水，凭谁为赏音。","远书仍问业，异地更论心。","牛马风难及，鱼鸿信易沈。","何时花月夜，杯酒复同临。"]},{"t":"初春二日二首 其一","f":"五言律诗","c":["青阳才二日，蓂荚为谁新。","散吏偏能暇，他乡别有春。","简编聊自悦，花鸟渐堪亲。","物态长如此，微名强傍人。"]},{"t":"初春二日二首 其二","f":"五言律诗","c":["光阴恒代谢，时命复如何。","雪后惟看竹，春回渐傍花。","阳舒随物理，雌伏念年华。","吏傲元兼隐，羁怀望转赊。"]},{"t":"和希举彦成二宗侯春游诗二首 其一","f":"五言律诗","c":["紫陌条风远，朱门淑气新。","流年堪抚景，结骑好乘春。","红染桃初遍，青垂柳欲匀。","馀寒欣渐散，鱼鸟总相亲。"]},{"t":"和希举彦成二宗侯春游诗二首 其二","f":"五言律诗","c":["当春饶乐事，随处蹑游踪。","百舌林声巧，千章岸影重。","偏提悬屡续，凿落泻初浓。","多少池塘咏，堪谁授简从。"]},{"t":"送崔伯子南归二首 其一","f":"五言律诗","c":["每忆乡园会，山川隔晤言。","愁惟看短剑，喜忽迓高轩。","并合翻疑梦，襟期未细论。","匆匆仍别袂，空自愧盘飧。"]},{"t":"送崔伯子南归二首 其二","f":"五言律诗","c":["客里逢归棹，江干问谪居。","斋閒方喻马，铗在岂歌鱼。","吴楚扁舟路，亲朋几字书。","薄游嗟世味，应复爱吾庐。"]},{"t":"分宜道中小憩宣风亭","f":"五言律诗","c":["避暑疑无地，宣风忽有亭。","云流当户白，山起傍檐青。","隐几看题勒，披襟豁性灵。","不须愁去暮，纤月起林坰。"]},{"t":"过长沙询贾生故宅","f":"五言律诗","c":["汉道犹全盛，君为痛哭书。","少年方志大，前席岂恩疏。","赋鵩悲时外，怀沙吊古馀。","行人多感慨，立马正踌躇。"]},{"t":"宁乡四桂亭","f":"五言律诗","c":["徙倚孤亭下，繁阴逗晚风。","燕山殊未五，淮海不成丛。","秀色偏相媚，幽香暗自通。","独谣还独酌，差可慰飘蓬。"]},{"t":"沅湘交会处","f":"五言律诗","c":["太史南浮日，临沅亦涉湘。","江山藉地胜，藻绘擅人长。","史述龙门隐，书窥禹穴藏。","蛮荒何所重，草木借名香。"]},{"t":"桃源洞二首 其一","f":"五言律诗","c":["一径寻源入，昔人此避秦。","衣冠今孔道，车马日生尘。","涧水难容艇，渔郎孰问津。","仙凡终古隔，耕凿几家邻。"]},{"t":"桃源洞二首 其二","f":"五言律诗","c":["不逢逃世者，空纪遇仙桥。","缨濯龙池洁，笙听鹤岭遥。","居人全类古，生业半为樵。","坐久呼僧语，尘心亦自消。"]},{"t":"辰溪山塘驿二首有引 其一","f":"五言律诗","c":["一别薇垣署，溪山路几千。","花光时记忆，驿舍转娇妍。","胜赏宁夷险，芳心孰后先。","主人兼命酒，坐语息尘缘。"]},{"t":"辰溪山塘驿二首有引 其二","f":"五言律诗","c":["山塘花下酌，仍忆令君香。","岭树遮炎暑，溪风纳午凉。","卑枝含万绿，韡萼擅群芳。","对此烦襟豁，浑忘在异乡。"]},{"t":"黔岭早行","f":"五言律诗","c":["伏尽已多日，炎氛却未清。","晓行听木叶，何树着秋声。","涧草仍生色，山花不辨名。","重重交紫翠，物态转多情。"]},{"t":"沅州中丞府","f":"五言律诗","c":["叹息西征日，曾烦十万师。","星霜驰白羽，洞壑闪朱旗。","授钺增开府，修戈慑远夷。","太平今有象，谁为惜疮痍。"]},{"t":"华元洞","f":"五言律诗","c":["一入华元洞，方知境界清。","荆榛何代辟，门户总天成。","地迥尘难到，室虚白亦生。","野僧能供佛，那得罢逢迎。"]},{"t":"贵竹署中忆薛德茂侍御二首有引 其一","f":"五言律诗","c":["法署今如昨，题诗墨尚鲜。","万山曾历涉，一别已长捐。","激浊多违愿，修文或有权。","不堪闻笛意，霜露转凄然。"]},{"t":"贵竹署中忆薛德茂侍御二首有引 其二","f":"五言律诗","c":["文酒难重晤，泉台更奈何。","君今为异物，余复出烟萝。","世路悲浮梗，流年感掷梭。","诸孤谁嗣业，雨露看庭柯。"]},{"t":"忠节并茂卷为谢奉常作","f":"五言律诗","c":["闽海钟奇烈，难逢萃一门。","乾坤俱正气，先后各殊恩。","省以兰逾洁，舟于柏共存。","盈庭多宝树，世泽衍诸孙。"]},{"t":"送谢苗黄三孝廉以校士毕共赴春试三首 其一","f":"五言律诗","c":["作客乾坤里，驱车各异乡。","看山忘近远，得马出骊黄。","赋就偏怀阙，名高拟擅场。","当春桃李色，能傍早梅芳。"]},{"t":"送谢苗黄三孝廉以校士毕共赴春试三首 其二","f":"五言律诗","c":["万里西南道，逢君亦欲东。","初看鹏翮健，辄讶马群空。","诗礼趋庭旧，天人诣阙同。","异时看隔坐，多在建章宫。"]},{"t":"送谢苗黄三孝廉以校士毕共赴春试三首 其三","f":"五言律诗","c":["自涉湘沅日，于君识楚兰。","芳香佩里出，气味语中看。","别我时怀李，诸生总愿韩。","曲江春色好，供奉接金銮。"]},{"t":"绥宁候夫役不至留者逾日漫成三首 其一","f":"五言律诗","c":["行路难如此，山程信宿留。","尚馀庄舄咏，再上仲宣楼。","旅况真无赖，乡心不自由。","望中分楚粤，云外忆芳洲。"]},{"t":"绥宁候夫役不至留者逾日漫成三首 其二","f":"五言律诗","c":["几日秋将尽，山中叶乱飞。","凄凉时物改，漂泊旅心违。","王事应难缓，他乡孰可依。","故人犹在远，云树转霏微。"]},{"t":"绥宁候夫役不至留者逾日漫成三首 其三","f":"五言律诗","c":["计程殊不定，鸟道未全过。","目断来鸿少，心惊叱驭多。","梦随乡思渺，寒奈客衣何。","咫尺川原隔，中流想棹歌。"]},{"t":"行次关峡值官舍倾坏寄宿民家","f":"五言律诗","c":["野外无官舍，山间到夕阳。","言投居士宅，遥傍水云乡。","耕凿安时俭，风尘慰路长。","儿童知礼客，庭户喜辉光。"]},{"t":"麻滩驿舍睹壁间留咏忆钱五卿二首 其一","f":"五言律诗","c":["记忆三年外，题诗问月岩。","风尘今道路，宾主孰东南。","酒态应还美，诗篇任自耽。","江州司马泪，何地湿青衫。"]},{"t":"麻滩驿舍睹壁间留咏忆钱五卿二首 其二","f":"五言律诗","c":["两度分符竹，千重到楚山。","骥途翻蹇滞，鸟道总间关。","行役思乡远，驱车畏路难。","滩声从百折，阅尽见安澜。"]},{"t":"舟过湟川访莫元慎褐玉轩小酌道旧二首 其一","f":"五言律诗","c":["里闬声相慕，萍蓬意倍亲。","君今仍短褐，众共惜儒珍。","未可城归赵，谁言客负秦。","深杯聊慰藉，雪后有阳春。"]},{"t":"舟过湟川访莫元慎褐玉轩小酌道旧二首 其二","f":"五言律诗","c":["自入维桑里，偏多伐木情。","山光连众壑，云气抱孤城。","地有人怀玉，途逢客聚星。","不缘今夕酒，何以见同声。"]},{"t":"清溪驿见梅花盛开","f":"五言律诗","c":["未入庾关道，梅花已自开。","南枝偏较早，春信独先回。","浊酒他乡暮，邮亭旅客杯。","能诗非水部，见尔亦徘徊。"]},{"t":"别匡庐","f":"五言律诗","c":["吏隐名山下，翻虚蹑屐从。","轮蹄纷俗状，岁月总尘容。","绿泛重湖水，青窥五老峰。","何时攀鹿洞，更听虎溪钟。"]},{"t":"泊舟湖口有折梅相赠者","f":"五言律诗","c":["春入寒梅久，侵寻到北枝。","林疏江月白，香细晓风吹。","驿使来能几，花神遇转奇。","一杯篷底绿，堪动法曹诗。"]},{"t":"舟夜湖风骤起","f":"五言律诗","c":["静夜风逾急，维舟客未安。","鱼龙应启蛰，浦溆遍生澜。","睡美愁仍起，更长梦亦寒。","呼灯危坐久，独酌慰惊湍。"]},{"t":"答谢伯高刺史","f":"五言律诗","c":["江光澄似练，吾忆谢玄晖。","五马称良牧，双鱼念远违。","衰迟惭宦达，留滞感知希。","羡尔来三辅，声名满帝畿。"]},{"t":"有斐堂感咏二首有引 其一","f":"五言律诗","c":["徙倚空堂寂，徘徊忆旧游。","荣枯随物理，远近感年流。","培植昔人意，彫零异代愁。","此君风节在，所至属王猷。"]},{"t":"有斐堂感咏二首有引 其二","f":"五言律诗","c":["西堂春富贵，丹艳映传觞。","劲节当年植，清风何处扬。","难将霜后色，得拟露华香。","别有栽培力，还应待凤凰。"]},{"t":"谢公墩","f":"五言律诗","c":["王谢游俱远，兴亡代几更。","双林苍霭入，一径黛烟横。","胜地何常主，青山不世情。","倚阑方罢酒，风静听禽声。"]},{"t":"寄黄士明太史二首 其一","f":"五言律诗","c":["秘阁摊书尽，恩光下帝庭。","层霄看渐羽，南斗避文星。","有客仍飘梗，何年更聚萍。","蓬莱清切地，忆尔日谈经。"]},{"t":"寄黄士明太史二首 其二","f":"五言律诗","c":["梦卜频年切，储才仗异时。","趋朝初述史，下直富摛词。","更想韩云殿，齐欢谢草池。","汪波俱相度，先后美规随。"]},{"t":"答邓介繁二首 其一","f":"五言律诗","c":["多君乘兴日，愧我远游人。","道路皆羁旅，枌榆念结邻。","曲高弥和寡，交淡却情真。","鞭弭中原足，堪谁作后尘。"]},{"t":"答邓介繁二首 其二","f":"五言律诗","c":["岁月疲奔走，江湖信梗萍。","歌惭郢里调，文谢北山铭。","旅舍怜今雨，他乡望客星。","迢迢孤棹远，天外数峰青。"]},{"t":"孝陵陪祀毕登钟山感赋","f":"五言律诗","c":["旧识蟠龙胜，今来驻马看。","衣冠游正渺，雨露感初残。","入望山河远，钟祥宇宙宽。","绎思时不尽，庙貌出巑岏。"]},{"t":"清凉台饯谢友可南还二首 其一","f":"五言律诗","c":["步出清凉界，山川入望来。","云光宫阙近，野色画图开。","地可登高赋，人宜避暑杯。","不堪仍送远，徙倚思悠哉。"]},{"t":"清凉台饯谢友可南还二首 其二","f":"五言律诗","c":["二仪方览胜，三伏已知秋。","舣棹将归客，开尊更并游。","凉飙生绿树，胜地即丹丘。","明发孤帆渺，遥看雁骛洲。"]},{"t":"送苏陈二比部考绩北上二首 其一","f":"五言律诗","c":["趋府方连武，登车复解携。","臣劳三载懋，国典二都齐。","曙阙随鹓仗，清秋驻马蹄。","中朝嘉异绩，纶札自天题。"]},{"t":"送苏陈二比部考绩北上二首 其二","f":"五言律诗","c":["宦达推闽海，台星两耀时。","喜君初上绩，结主复先资。","会应风云起，恩承雨露私。","秋高重聚首，何用怅临岐。"]},{"t":"黄季文过访适张子云继至各示新篇赋答二首 其一","f":"五言律诗","c":["官閒不谢客，二妙忽来过。","敢比青云附，俱听白雪歌。","宦情原已少，羁思渐还多。","非藉论文侣，其如秋气何。"]},{"t":"黄季文过访适张子云继至各示新篇赋答二首 其二","f":"五言律诗","c":["海国三千路，钟陵尺五天。","薄游成故里，嘉会总高贤。","学览无今古，诗传孰后先。","并驱知竞美，休愧在卢前。"]},{"t":"访季文不遇承以诗谢再答","f":"五言律诗","c":["千里朋簪盍，初秋爽气新。","非因同调者，宁问和歌人。","作客无常主，盈门岂杂宾。","知君能好我，佳句未辞频。"]},{"t":"姚巽卿见过遇雨而返辄有赠言答和二首 其一","f":"五言律诗","c":["政拙居閒久，声同聚会难。","羊何多和客，李杜孰登坛。","白下流俱胜，黄初语并看。","蜗庐休自悼，随处好追欢。"]},{"t":"姚巽卿见过遇雨而返辄有赠言答和二首 其二","f":"五言律诗","c":["乍得清秋雨，炎氛已自消。","诗成元寡和，兴尽转难招。","倒屣空延伫，虚堂倍寂寥。","公馀仍下榻，听尔一长谣。"]},{"t":"苏茂才溺舟江上仅以身免余解衣衣之并资其行李之困乏赋此慰勉","f":"五言律诗","c":["万古江流在，帆樯竟日过。","每凭舟楫用，得藉往来多。","未破乘风浪，翻愁泛日波。","君才原利涉，且自慰蹉跎。"]},{"t":"后醒子二首 其一","f":"五言律诗","c":["万古非长夜，斯人岂故吾。","静观随物理，真悟出迷途。","独返襄城驾，初收象罔珠。","更堪师后觉，启翼与为徒。"]},{"t":"后醒子二首 其二","f":"五言律诗","c":["世苦多岐路，君知梦觉关。","斲轮欣自悟，游刃得馀閒。","无欲观常妙，明心见所还。","指南端有赖，末学可晞颜。"]},{"t":"送陈太学东归二首 其一","f":"五言律诗","c":["自昔论交意，于今送远情。","绸缪匪一日，许与见平生。","肝胆堪相照，飞腾俟晚成。","朔风吹雁候，江上片帆轻。"]},{"t":"送陈太学东归二首 其二","f":"五言律诗","c":["槐市秋飙急，兰舟越水长。","桥门经术就，京国姓名香。","业衍箕裘裔，心悬燕喜堂。","春池归梦草，何似滞他乡。"]},{"t":"初冬同王户曹饶考功刘职方周驾部项光禄登景阳阁","f":"五言律诗","c":["良月堪临眺，登楼复景阳。","高低连井里，远近见帆樯。","山色微含树，云光傍举觞。","相逢须共醉，宁觉在他乡。"]},{"t":"答潘少临将军","f":"五言律诗","c":["寄梅来驿使，慰我梦思劳。","宦拙悲鸿渐，官閒类马曹。","登坛应业就，图阁自名高。","更拟双龙合，慇勤解佩刀。"]},{"t":"送梁国博之任滇南郡丞","f":"五言律诗","c":["万里西南道，看君拥传车。","金沙江色净，铜柱瘴烟疏。","桃李环门后，桑麻卧阁馀。","循良徵异等，应有汉廷书。"]},{"t":"送张懋功比部出守镇远二首 其一","f":"五言律诗","c":["驿骆驱驰远，专城保障雄。","五溪衣服外，六诏往来中。","荒徼宜良牧，天朝命钜公。","张君为政乐，先拟颂声同。"]},{"t":"送张懋功比部出守镇远二首 其二","f":"五言律诗","c":["一水穿重峡，双旌望远人。","东方千骑出，西岭万家春。","烽火年来净，闾阎俗自淳。","伫看徵异绩，岂但玉为麟。"]},{"t":"秦伯起报满南还以途中近作见示赋答","f":"五言律诗","c":["羡尔朝天去，承恩归路长。","风尘随驿骑，霜雪满衣裳。","客咏多千首，皇纶重十行。","从兹看远驭，何地不康庄。"]},{"t":"和巽卿至后登台二首 其一","f":"五言律诗","c":["客久岁云暮，阳生春渐回。","梅花催作赋，柏叶待传杯。","天地凝寒歛，江山淑景开。","旅吟随处好，休比望乡台。"]},{"t":"和巽卿至后登台二首 其二","f":"五言律诗","c":["乡望情何极，蕨薇长故山。","拂尘看剑锷，对月问刀环。","父老歌风后，园陵望气间。","登临随杖屦，云水意同閒。"]},{"t":"腊月朔日伯起招同诸公赏雪","f":"五言律诗","c":["一冬犹未雪，此日喜同看。","极目琼楼远，开帘玉宇寒。","丰年仍兆瑞，高会总成欢。","郢调君应富，歌来和正难。"]},{"t":"次和友人岁暮旅怀十首 其一","f":"五言律诗","c":["异地生羁思，残年傍客愁。","月馀鳷鹊观，寒满鹔鹴裘。","旧侣多离索，新篇负唱酬。","帝城春又至，岁序忽如流。"]},{"t":"次和友人岁暮旅怀十首 其二","f":"五言律诗","c":["旅馆俱无赖，深杯且莫辞。","以余方滞迹，犹尔未归时。","抚景情俱剧，探春事不迟。","品题新岁月，都入郢中词。"]},{"t":"次和友人岁暮旅怀十首 其三","f":"五言律诗","c":["白社非尘境，青山不世情。","浮生俱扰扰，谢俗寡营营。","酒破千愁阵，诗高五字城。","几人同述作，艺苑识宗盟。"]},{"t":"次和友人岁暮旅怀十首 其四","f":"五言律诗","c":["白雪知君富，黄金总让人。","江湖双短鬓，天地一閒身。","萍水长为客，莺花又及春。","臈残诗祭罢，喜复岁华新。"]},{"t":"次和友人岁暮旅怀十首 其五","f":"五言律诗","c":["风流江左地，千古尚依然。","世远齐梁后，诗称鲍谢前。","微名甘负俗，健翼愧垂天。","触物同怀土，登楼有仲宣。"]},{"t":"次和友人岁暮旅怀十首 其六","f":"五言律诗","c":["玄冬霜雪尽，暖逐琯灰来。","寒色旅中夜，春光何处台。","青归淮畔柳，红入陇头梅。","底事能娱客，深樽有绿醅。"]},{"t":"次和友人岁暮旅怀十首 其七","f":"五言律诗","c":["片愁消大白，万事倚穷苍。","萍梗经漂泊，松筠自雪霜。","龙颜燕阙远，雁字楚天长。","莫漫悲游子，摊书但满床。"]},{"t":"次和友人岁暮旅怀十首 其八","f":"五言律诗","c":["礼复朝元会，香分列署含。","地同天尺五，人岂象魁三。","宾从时投辖，知交未解骖。","独谙官况冷，孤月印寒潭。"]},{"t":"次和友人岁暮旅怀十首 其九","f":"五言律诗","c":["宦思多寥寂，吟怀强自宽。","早春将送暖，馀臈尚生寒。","求友怀黄鸟，游仙慕紫鸾。","更谁如李白，被酒赴金銮。"]},{"t":"次和友人岁暮旅怀十首 其十","f":"五言律诗","c":["光阴催改岁，日月惜徒过。","世事长如此，年劳较孰多。","祗应骚客咏，都付雪儿歌。","伫听阳春曲，凭陵更若何。"]},{"t":"画梅","f":"五言律诗","c":["万木犹含冻，一枝渐着花。","寒香风里动，素影月中斜。","老干仍春色，孤芳自岁华。","巡檐方索笑，触目兴先赊。"]},{"t":"客有求绍介于李明府者却寄二首 其一","f":"五言律诗","c":["乡里衣冠后，如君岂乏贤。","分符初一命，飞舄已三迁。","绿鬓神明宰，丹心日月悬。","海波长愿息，泽为圣人宣。"]},{"t":"客有求绍介于李明府者却寄二首 其二","f":"五言律诗","c":["薄海三年爱，穷檐万户春。","福星随地远，膏雨应时新。","治行推高等，朝恩异众伦。","台垣虚席久，迟尔对枫宸。"]},{"t":"暮春李长卿偕梅子庾移樽过访赋答二首 其一","f":"五言律诗","c":["案牍元多暇，知交亦自稀。","径深芳草没，门静落花飞。","胜赏春将尽，行游愿屡违。","喜君能顾我，竟日对晴晖。"]},{"t":"暮春李长卿偕梅子庾移樽过访赋答二首 其二","f":"五言律诗","c":["奇字无堪问，何当载酒来。","池光摇拂麈，柳色映传杯。","渭北人怀李，吴门客姓梅。","高情逢二妙，谈咏旅愁开。"]},{"t":"送杨比部归綦江二首 其一","f":"五言律诗","c":["极目天涯道，乡心越万山。","握兰违省署，折柳出江关。","车骑西南徼，风尘客子颜。","遥知家庆集，多恋锦初还。"]},{"t":"送杨比部归綦江二首 其二","f":"五言律诗","c":["井里兵戈后，怀归几梦思。","赐环新岁月，驱传旧旌麾。","古峡啼猿远，高峰到雁迟。","陇梅堪寄候，当复出山时。"]},{"t":"首夏即事","f":"五言律诗","c":["柳尽风前絮，葵含雨后英。","宦情同白下，岁序又朱明。","积贮穷檐竭，烽烟几处生。","至尊忧独切，何日见澄清。"]},{"t":"送何敬渐改北成均二首 其一","f":"五言律诗","c":["帝里衣冠集，看君鼓箧行。","一经韦少子，六馆汉诸生。","大有承家誉，偏多恋阙情。","平津开阁日，端合起高名。"]},{"t":"送何敬渐改北成均二首 其二","f":"五言律诗","c":["世德先朝重，家声奕叶存。","赏延思报国，业在识专门。","礼秩东曹旧，儒宗上序尊。","凤毛元五色，此去见腾骞。"]},{"t":"答少司马陈公二首 其一","f":"五言律诗","c":["一从归棹渺，离况迥难舒。","薄宦重于世，耆年久遂初。","家承韦氏学，架美邺侯书。","却喜仪刑近，传经在石渠。"]},{"t":"答少司马陈公二首 其二","f":"五言律诗","c":["极目群峰外，长江复渺瀰。","颇存枥马志，却冒海鸥疑。","望逐前驱远，功方后进迟。","丹山多穴凤，次第见来仪。"]},{"t":"送姚生君会还揭阳二首 其一","f":"五言律诗","c":["海畔三千里，君今赋北游。","瞻天来上国，结客慕名流。","骤列冠裳会，宁甘水石俦。","以余方滞迹，却自愧荆州。"]},{"t":"送姚生君会还揭阳二首 其二","f":"五言律诗","c":["昔我曾游地，青齐控海门。","城开莒子国，路出穆陵原。","良牧声初起，交亲谊独存。","江山应有助，归去美词源。"]},{"t":"为尹太学寿其贞母二首 其一","f":"五言律诗","c":["槐市新凉入，游人念倚庐。","飞云瞻狄舍，晴雨想潘舆。","上国衣冠始，家庭燕喜初。","冈陵今日颂，都属庆之馀。"]},{"t":"为尹太学寿其贞母二首 其二","f":"五言律诗","c":["昔看慈母线，今阅女仙图。","天上麟为二，人间凤不孤。","歌馀陶氏鹄，綵并老莱乌。","岂藉阳城教，先能念母劬。"]},{"t":"寄张孟奇计部分司浒墅二首 其一","f":"五言律诗","c":["一水通吴越，中朝出度支。","艅艎纷并集，币物总多奇。","早夜惟持算，东南更察眉。","使君非榷吏，公暇日删诗。"]},{"t":"寄张孟奇计部分司浒墅二首 其二","f":"五言律诗","c":["千里方愁潦，频年急上供。","岂堪歌杼轴，无计问租庸。","蒿目筹俱尽，丹心事可封。","怀君非在远，秋水隔芙蓉。"]},{"t":"陈茂才父母偕寿","f":"五言律诗","c":["里聚德星久，堂开寿域长。","对持春酒绿，共看晚花黄。","双鹤龄逾健，蟠桃叶正芳。","翩翩三凤羽，将近五云翔。"]},{"t":"送袁伯益比部南还二首 其一","f":"五言律诗","c":["客里秋高日，谁能不望乡。","离杯新酒绿，异地晚花黄。","五岭停云远，三城去路长。","遥知家庆集，旋见蚤梅香。"]},{"t":"送袁伯益比部南还二首 其二","f":"五言律诗","c":["客席应初暖，临岐又解携。","但欢重昼锦，何惮促歌骊。","驿路随南雁，山程听晓鸡。","春江花月待，弭棹到城西。"]},{"t":"长至前二日送周驾部考绩二首 其一","f":"五言律诗","c":["述职初三载，朝天近一阳。","仙郎方绿鬓，世业自青箱。","司马为圻父，留都是帝乡。","庙谟根本重，简在有辉光。"]},{"t":"长至前二日送周驾部考绩二首 其二","f":"五言律诗","c":["丰镐惟南国，干城实楚材。","凤麟明世出，骐骥远途开。","宦绩堪殊考，皇恩正大来。","春光辞帝阙，归及咏官梅。"]},{"t":"罗母太宜人八十二首 其一","f":"五言律诗","c":["南陆清和始，北堂燕喜初。","会成青鸟信，恩重紫鸾书。","五马何妨远，三鳣自不虚。","盈阶多宝树，雨露更何如。"]},{"t":"罗母太宜人八十二首 其二","f":"五言律诗","c":["报道瑶池宴，君家萼绿华。","已看珈是玉，更美枣如瓜。","丹诏衔双凤，琼浆进九霞。","年年歌寿母，乐事总堪誇。"]},{"t":"至后送谢友可考绩二首 其一","f":"五言律诗","c":["几度皇华使，三年法署郎。","臣劳今上考，岁序又初阳。","驿骑风尘远，天朝雨露长。","鹓鸾多旧侣，剑佩待明光。"]},{"t":"至后送谢友可考绩二首 其二","f":"五言律诗","c":["宦迹淹南国，才名重两都。","风云仍傍阙，雨雪但征途。","念旧恩逾渥，酬劳愿不孤。","庙堂安石略，留以弼皇图。"]},{"t":"得假南归答秦伯起赠别","f":"五言律诗","c":["天涯归思切，不省漫为官。","驿路随杨柳，花期复牡丹。","尊违徵赏集，琴念别离弹。","去住情俱系，苍波正淼漫。"]},{"t":"颜茂才过访舟中","f":"五言律诗","c":["二载诗相忆，重逢但客舟。","深尊宁十日，片语亦千秋。","并合元难定，支离可自由。","临岐需后会，天路有鸣驺。"]},{"t":"送苏明府入觐二首 其一","f":"五言律诗","c":["万里趋朝者，孤城保障哉。","一琴单父后，双舄尚方来。","雨露穷檐普，风云傍阙回。","瞻天浮瑞色，郎宿近中台。"]},{"t":"送苏明府入觐二首 其二","f":"五言律诗","c":["去日秋氛净，归时春意浓。","明光催晓漏，长乐听疏钟。","治绩过三异，恩光下九重。","苍黎争舞蹈，不负远朝宗。"]},{"t":"重过郊居有感","f":"五言律诗","c":["自出郊居日，风尘涉旅途。","颜知芳杜厚，迹以菉薋芜。","花鸟何常主，琴尊非故吾。","重来呼旧侣，别是酒家胡。"]},{"t":"答友人寄怀","f":"五言律诗","c":["远书凭过雁，时物感寒螀。","久别霜侵鬓，相思月在梁。","望穷千转径，愁绝九回肠。","露满蒹葭夕，佳人水一方。"]},{"t":"清赏斋二首 其一","f":"五言律诗","c":["胜地无常主，高人自结庐。","环门多水竹，混迹岂樵渔。","万卷连床富，群花向日舒。","琴尊俱乐事，何羡府中居。"]},{"t":"清赏斋二首 其二","f":"五言律诗","c":["习静成真隐，耽幽艺众芳。","一亭杨子宅，三径蒋公堂。","渐喜飧霞侣，将休结客场。","江湖心尚远，松菊岂全荒。"]},{"t":"答钟茂才二首 其一","f":"五言律诗","c":["一别逾三纪，鱼鸿各渺然。","赋才推并美，蹇步愧余先。","雾豹宁终隐，云鹏拟共翩。","桑榆犹未晚，挥霍待龙渊。"]},{"t":"答钟茂才二首 其二","f":"五言律诗","c":["钟子元同调，知音近转疏。","摛文皆五凤，念旧更双鱼。","一水蒹葭外，层霄羽翼初。","暮云思握手，赋奏待公车。"]},{"t":"夜泊洸口昔回自贵竹时所取道也感赋三首 其一","f":"五言律诗","c":["陇树收残雨，江舟带暮烟。","客程今夜宿，乡梦几宵悬。","水接湖南路，山开岭外天。","昔时孤骑绕，过此重凄然。"]},{"t":"夜泊洸口昔回自贵竹时所取道也感赋三首 其二","f":"五言律诗","c":["二水浈阳合，千峰楚甸分。","驱车曾鸟道，弭棹此鸥群。","作客春多雨，怀人树有云。","江声缘瀑急，永夜此中闻。"]},{"t":"夜泊洸口昔回自贵竹时所取道也感赋三首 其三","f":"五言律诗","c":["舟楫频来往，江山自渺漫。","风湍聊暂息，旅酌不成欢。","旧事追相忆，新愁别转难。","推篷占霁色，羁思稍能宽。"]},{"t":"夏日泛舟秦淮","f":"五言律诗","c":["十里秦淮胜，偏能悦客游。","家家凭水槛，处处上兰舟。","箫鼓时相应，壶觞夜不休。","绝怜城郭里，弭棹得临流。"]},{"t":"桃叶渡","f":"五言律诗","c":["桃叶知何处，犹传旧渡名。","休论千古恨，且喜四难并。","婀娜江花媚，留连夜月生。","何言不用楫，满听棹歌声。"]},{"t":"天界社集赋得薰风自南来殿阁生微凉二首 其一","f":"五言律诗","c":["永日宁逃暑，微风入户来。","炎威三伏失，爽气二仪开。","暗度过新竹，轻飘动午槐。","坐添吟思好，复进掌中杯。"]},{"t":"天界社集赋得薰风自南来殿阁生微凉二首 其二","f":"五言律诗","c":["台殿元虚敞，披襟更纳凉。","飙含槐柳色，气袭芰荷香。","解阜歌虞帝，清泠快楚王。","炎氛俱涤尽，夏日正堪长。"]},{"t":"郑生偕行自闽远来索赠二首 其一","f":"五言律诗","c":["昔游闽岭外，无地不菁莪。","业自承家远，书因诣阙多。","云霄看健翮，雨露出新柯。","藏器年来久，程功近若何。"]},{"t":"郑生偕行自闽远来索赠二首 其二","f":"五言律诗","c":["绿鬓年华始，青襟誉逮时。","三冬元易足，一字愧难师。","旧里皆通德，新篇几白眉。","秋风鹏运早，九万正堪期。"]},{"t":"题署中君子轩二首 其一","f":"五言律诗","c":["司计逢多暇，开轩面此君。","高枝时近日，密叶每披云。","并美不雕操，长瞻有斐文。","祗缘风节在，随地见清芬。"]},{"t":"题署中君子轩二首 其二","f":"五言律诗","c":["满林皆绿玉，更长碧琅玕。","入夏能清暑，经霜不畏寒。","渭滨休拟富，嶰谷可同看。","日有平安报，应教俗虑宽。"]},{"t":"寄答内弟体健","f":"五言律诗","c":["岭外传书至，知君念我劳。","听鸿欹草阁，步马忆兰皋。","白雪歌难和，碧云望转高。","各天俱夜月，谁傍锦宫袍。"]},{"t":"同乡合祀湛文简公","f":"五言律诗","c":["昔日谈经处，多贤尚景从。","圣朝无学禁，吾道有儒宗。","共喜芳仍远，休疑大莫容。","宫墙千古在，俎豆记遗踪。"]},{"t":"答霍益芳自山中寄怀","f":"五言律诗","c":["名山多副墨，水石更堪娱。","嗜古翻成癖，探奇却类迂。","我犹淹拙宦，君亦著潜夫。","意气应相许，何能学破觚。"]},{"t":"寄金华周使君","f":"五言律诗","c":["远驿连荒徼，当年奉属车。","抡才忽五马，叙旧几双鱼。","阖境闻舆颂，中朝待玺书。","循良徵异等，郡国更谁如。"]},{"t":"送张子云之任梧州府僚","f":"五言律诗","c":["苍梧新佐郡，玄草旧名家。","案牍分劳始，风云入望赊。","檄缘亲为喜，才识吏而华。","画诺当谁主，中和咏复嘉。"]},{"t":"周氏蔽席庐","f":"五言律诗","c":["六合匪云远，吾庐亦自宽。","四时皆乐境，万象纵遐观。","架上充图史，床头有镆干。","席门多长者，孰与此中看。"]},{"t":"代赠吉祥寺碧云上人","f":"五言律诗","c":["并入招提境，慈云护吉祥。","飞来山共碧，映处谷为光。","缥缈诸天外，纷纶慧日旁。","萧斋能礼客，时拟惠休章。"]},{"t":"送广生南还二首 其一","f":"五言律诗","c":["仗剑来游日，西风白雁初。","称诗随旅况，持论慰离居。","禹穴探书罢，秦淮问酒馀。","乡心逢岁暮，聊复爱吾庐。"]},{"t":"送广生南还二首 其二","f":"五言律诗","c":["朔气寒方凛，游人念故园。","早梅迎客骑，疏柳对离樽。","白雪新篇富，青云旧业存。","谢庭多赋客，归与共玄言。"]},{"t":"冬日冶城晚眺分韵得支麻字二首 其一","f":"五言律诗","c":["万壑阳回后，层轩夕望时。","落霞光倒映，爱日影西移。","未拟登楼赋，先赓伐木诗。","倚阑思正渺，灯火夜归迟。"]},{"t":"冬日冶城晚眺分韵得支麻字二首 其二","f":"五言律诗","c":["说剑城为冶，开尊物有华。","同来浮白者，俱是草玄家。","净社依青嶂，高斋傍赤霞。","官閒期会少，吟眺景偏赊。"]},{"t":"送丁茂淑缮部出榷芜湖二首 其一","f":"古风","c":["入社怜同调，分曹重?材。","简书宁勿畏，案牍苦相催。","别酒临岐尽，仙帆带日开。","相违休道远，南望只江隈。"]},{"t":"送丁茂淑缮部出榷芜湖二首 其二","f":"五言律诗","c":["牒随将作署，费藉水衡钱。","祗信迹难合，何知利有权。","吟怀应尚壮，物力转须怜。","揽胜逢公暇，诗筒好为传。"]},{"t":"送周伯绳比部给假归昆山二首 其一","f":"五言律诗","c":["青阳欣改序，白社恋同声。","准拟吟怀豁，翻令别思生。","看花违共赏，折柳重含情。","锦里春偏丽，催君事昼行。"]},{"t":"送周伯绳比部给假归昆山二首 其二","f":"五言律诗","c":["游子思乡切，春风献岁初。","娄江归兴远，钟阜旅怀纾。","列署刑堪措，连枝会不虚。","莺花随处好，应念社盟疏。"]},{"t":"读俨思录二首有序 其一","f":"五言律诗","c":["大孝思能永，精诚感易通。","丹青图画里，陟降有无中。","梦想前修渺，瞻依此日同。","庆馀知未艾，光裕慰而翁。"]},{"t":"读俨思录二首有序 其二","f":"五言律诗","c":["念祖将绳武，贻孙待作求。","音容宁遂泯，英爽故能留。","列柏栽培远，丛兰雨露周。","龙章他日锡，端可发潜幽。"]},{"t":"荆花二首 其一","f":"五言律诗","c":["百卉春交媚，荆花亦自妍。","迎风摇绛雪，得雨濯红泉。","纤绿间重锦，繁芳染瑞烟。","桃蹊看并美，堪为纪新篇。"]},{"t":"荆花二首 其二","f":"五言律诗","c":["年光嗟荏苒，睹物若为情。","每忆三荆合，偏令百感生。","梗漂怜聚散，花落任枯荣。","且喜庭芳满，均沾雨露成。"]},{"t":"分菊","f":"五言律诗","c":["种菊依檐下，曾经两度秋。","根移新雨润，叶美早春柔。","生意从今达，群芳羡独幽。","三年居此地，更为晚花留。"]},{"t":"咏古四首有序 其一 董生","f":"五言律诗","c":["道丧嬴秦后，传经属汉儒。","天人初召对，伊吕此为徒。","列国诸侯相，中朝子大夫。","究寻灾异理，时论却为愚。"]},{"t":"咏古四首有序 其二 诸葛武侯","f":"五言律诗","c":["隆中高卧日，闻达岂知求。","三顾时非偶，一言意自投。","忠贞期灭魏，运祚失兴刘。","出处应难并，休论愿未酬。"]},{"t":"咏古四首有序 其三 陆宣公","f":"五言律诗","c":["所学真无负，恩深内相初。","敷陈本道德，诏令感州闾。","罢献能防侈，忧谗不著书。","祗今看奏议，法戒尚昭如。"]},{"t":"咏古四首有序 其四 韩魏公","f":"五言律诗","c":["五云先兆瑞，相业卜当年。","筦库宁留滞，乾坤待转旋。","两朝光定策，四路靖临边。","识量多宏伟，功成付彼天。"]},{"t":"暮春送邹道卿驾部考绩二首 其一","f":"五言律诗","c":["春服喜初成，逢君又北征。","归朝先对马，觐阙际迁莺。","课绩过三载，程材擅二京。","留都根本在，当宁不胜情。"]},{"t":"暮春送邹道卿驾部考绩二首 其二","f":"五言律诗","c":["仙郎方绿鬓，宦业此初升。","剑气新硎发，文光健笔凌。","枢曹推上考，艺苑见中兴。","试最加恩后，悬知秩倍增。"]},{"t":"丁比部招同诸旧僚赏署中花适以公阻赋谢二首 其一","f":"五言律诗","c":["自别玄湖署，曾经几度花。","放衙宾又集，对酒日初斜。","旧侣能相忆，新诗并可誇。","不堪期会阻，独自惜年华。"]},{"t":"丁比部招同诸旧僚赏署中花适以公阻赋谢二首 其二","f":"五言律诗","c":["列署多红药，繁阴更满廊。","山光移毓秀，湖润浥呈芳。","胜赏皆仙侣，离群一漫郎。","花神烦寄谢，风末送馀香。"]},{"t":"和友人首夏即事四首 其一","f":"五言律诗","c":["首夏清和节，春归景亦妍。","薰风才入户，暑雨未盈阡。","花送馀香满，林交万绿鲜。","乐游随处好，选胜任披筵。"]},{"t":"和友人首夏即事四首 其二","f":"五言律诗","c":["青阳初告谢，南陆肇朱明。","巢起将雏燕，林娇唤友莺。","葵榴将吐艳，荷芰各敷荣。","窗草皆书带，芊绵绕砌生。"]},{"t":"和友人首夏即事四首 其三","f":"五言律诗","c":["江南梅欲雨，陇上麦初秋。","蝶向残花恋，鱼吹嫩藻浮。","开尊清景玩，倚杖绿阴留。","细瀑穿林出，泠泠山更幽。"]},{"t":"和友人首夏即事四首 其四","f":"五言律诗","c":["永昼逢多暇，开帘阅众芳。","粉含竹翠润，絮净柳阴凉。","鸟哢时增巧，蝉吟声始扬。","北窗无俗客，差可傲羲皇。"]},{"t":"樱桃","f":"五言律诗","c":["满林看结实，百果此为先。","赤玉色同美，明珠颗并圆。","寝园新始荐，内殿赐方传。","亦有筠笼赠，堪充野赏筵。"]},{"t":"送吴翁晋光禄考绩二首 其一","f":"五言律诗","c":["吏隐居南国，书劳在禄勋。","词才方共美，宦绩更先闻。","入奏随鹓侣，北归逐雁群。","好文当此日，知羡赋凌云。"]},{"t":"送吴翁晋光禄考绩二首 其二","f":"五言律诗","c":["上林花正好，四月似芳春。","赴阙瞻天近，趋朝就日频。","燕台金结士，汉署玉为人。","奏最如君几，恩当次第新。"]},{"t":"初夏出南郊历天坛至神乐观道院宴集得深林二字四首 其一","f":"五言律诗","c":["朱明初启夏，万绿满芳林。","春去无多日，时和转惬心。","出郊行结轸，随处坐披襟。","景物俱清胜，流观并助吟。"]},{"t":"初夏出南郊历天坛至神乐观道院宴集得深林二字四首 其二","f":"五言律诗","c":["昼永随南陆，朋游况盍簪。","郊原细藉草，林泽纵听禽。","石扫残花片，车停茂树阴。","飞云从杖屦，远俗称幽寻。"]},{"t":"初夏出南郊历天坛至神乐观道院宴集得深林二字四首 其三","f":"五言律诗","c":["远忆郊天日，千官扈驾临。","皇图依北极，御路隐中林。","王气瞻从昔，游怀畅自今。","两都曾作赋，应与续遗音。"]},{"t":"初夏出南郊历天坛至神乐观道院宴集得深林二字四首 其四","f":"五言律诗","c":["历览芳原胜，谈玄道院深。","野霞纷掩映，林木更萧森。","姹女丹从授，贤人酒谩斟。","羽觞移就月，杂坐听鸣琴。"]},{"t":"醴泉井有引","f":"五言律诗","c":["二仪崇秩祀，俯仰见嘉祯。","圣德通灵贶，明禋遇礼成。","金盘仁泽美，玉窦乳流清。","芳润馀应远，沾濡及众生。"]},{"t":"送从叔岁荐北上","f":"七言律诗","c":["几度乘秋阅岁华，瑾瑜曾共惜微瑕。","腾蛟未破南溟浪，试马先看上苑花。","庾岭烟开迎客旆，粤江春暖泛仙槎。","青萍长价应千倍，紫气还瞻耀晚霞。"]},{"t":"送比部陈先生之南都","f":"七言律诗","c":["三年遗爱粤东隅，黄白攀辕引别裾。","岂谓圣朝严法署，独凭公望寄刑书。","昼游彩鹢过南浦，秋到青箱启直庐。","自入品题惭国士，不知何以副吹嘘。"]},{"t":"崇胜寺再集儒林会","f":"七言律诗","c":["双林寂寂敞禅关，听法年年此日还。","蓬转几能同白社，浪游随处客青山。","群公合式乡闾外，诸子相推意气间。","醉里复从尘鞅去，淹留那得共僧閒。"]},{"t":"过漂母祠","f":"七言律诗","c":["停舟几夜宿寒原，雪后登临感慨存。","古庙相传祠漂母，旅游曾忆重王孙。","千金孰意当年赐，一饭难忘未遇恩。","独有汉皇终薄报，弓藏云梦只荒村。"]},{"t":"谒孟庙","f":"七言律诗","c":["柏桧森森荫绿苔，清高庙貌出城隈。","七篇仁义三迁始，百代渊源一贯来。","皓皓尚馀秋日烈，岩岩虚道泰山颓。","可怜此地空祠庙，谁识当年命世才。"]},{"t":"下第出京","f":"七言律诗","c":["客舍听鸡问去程，青青柳色唤愁生。","六街歌管尘随马，万井烟花树绕莺。","归日彩云空恋阙，谁家白璧重连城。","燕金结客知何在，且与沙鸥狎旧盟。"]},{"t":"杨青驿","f":"七言律诗","c":["漂泊风尘怅远游，杨青亭下暂维舟。","故乡门巷经梅雨，客路山川到麦秋。","潦倒诗篇时自适，飘零杯酒暮堪愁。","几宵尚忆长安道，北斗遥瞻接凤楼。"]},{"t":"荆门驿","f":"七言律诗","c":["草绿荆门柳更浓，别来霄汉一萍踪。","馀寒四月衣初袷，落日孤舟路几重。","千里帆樯新禹贡，百年耕凿旧尧封。","美人自古伤迟暮，回首天涯可易逢。"]},{"t":"舟次怀旧","f":"七言律诗","c":["忆昔扁舟此地过，樽前谈咏得羊何。","几回梦断清秋月，何处重听子夜歌。","远道炎蒸愁赤日，孤村云石蔓青萝。","山阳笛在偏增感，不尽离怀对绿波。"]},{"t":"月下与诸叔季小集","f":"七言律诗","c":["夜色苍茫暑渐移，临流堪待月高时。","清谈暂觉尘寰远，长啸俱忘世路悲。","王氏论从叔湛易，谢家篇就弟连诗。","更阑未尽溪头语，星聚何当太史知。"]},{"t":"秋晓步月","f":"七言律诗","c":["落落寒衣恨转蓬，五更人在月明中。","庭前昨夜秋声急，梦里单衾客思丛。","叶下井梧随堕露，声闻城柝送长风。","更听嘹喨层云外，或有音书付塞鸿。"]},{"t":"归自山中道过张茂才","f":"七言律诗","c":["薜衣藜杖翠微隈，习习清风两腋回。","问字堪过杨子宅，论文况羡襧生才。","相推白璧连城重，自有黄金索骏来。","迟尔长杨秋色里，好怀春并蓟门开。"]},{"t":"陈比部先生出守雷州寄怀二首 其一","f":"七言律诗","c":["家世才名美豫章，专城遥寄出东方。","西曹法象人争睹，南海恩波故未忘。","共喜文翁宜蜀郡，谁言长孺薄淮阳。","褰帷满听歌来暮，异等应追汉吏良。"]},{"t":"陈比部先生出守雷州寄怀二首 其二","f":"七言律诗","c":["起草风流汉两都，东来千骑下平芜。","含香久重郎官署，露冕初分刺史符。","象郡儿童新竹马，羊城人吏旧仙凫。","山中几度空相忆，欲寄云椷路转纡。"]},{"t":"喜友人举人兼怀未遇诸子","f":"七言律诗","c":["怪尔明珠屡暗投，偶传消息到沧洲。","三年灯火山中社，五岭风云海上秋。","狗监尚邀陈猎赋，骏台堪羡过都游。","翻疑楚璞终难献，摇落渔矶问钓舟。"]},{"t":"过三归台","f":"七言律诗","c":["空郊立马久徘徊，相国曾称天下才。","一笑功名终小器，万年凄寂只荒台。","樵苏晚傍牛羊下，禾黍争喧鸟雀来。","书社不知谁是主，夕阳萧索转堪哀。"]},{"t":"国学释褐答友人","f":"七言律诗","c":["十载尘途甘短褐，一朝帝里亦长裾。","萍蓬乍喜他乡合，棫朴均沾圣泽馀。","恋阙敢随温饱后，环桥犹似听观初。","中朝此日须贤哲，早为皇家事远图。"]},{"t":"早朝","f":"七言律诗","c":["晓共衣冠拜冕旒，天街寒露湿鸣驺。","祥烟渐绕浮鹓仗，旭日初腾接凤楼。","声度玉珂听渐远，心依华衮去还留。","近臣只爱天颜喜，宵旰宁知圣主忧。"]},{"t":"读臣鉴有感","f":"七言律诗","c":["宝鉴何时出上方，几回披对忆宣皇。","忠邪已向当年别，予夺仍垂百代长。","周典六官箴并肃，虞廷三载义同彰。","明明法戒应无斁，喜起重歌庶事康。"]},{"t":"送梁维襄司教顺义","f":"七言律诗","c":["几度乘春入帝乡，看君犹是丈人行。","天南偶伴歌萍鹿，冀北凭谁识牝黄。","经术暂为秦博士，科名终属汉贤良。","蓿盘莫叹官初冷，咫尺还饶上苑芳。"]},{"t":"送于子步归济宁时得请终养其母太淑人","f":"七言律诗","c":["几回觞咏为君留，忍看离袂对初秋。","心随潘岳扶舆返，梦怯王遵叱驭游。","庭下槐阴存手植，堂前萱草号忘忧。","何时访尔扁舟过，问月同登太白楼。"]},{"t":"送潘彦恒令洛阳","f":"七言律诗","c":["郎秩初颁自建章，便从潘令醉离觞。","秋辞上国闻新雁，路出清河指故乡。","疆域正临周土俗，功名宁让汉循良。","春光满县花如锦，谁道河阳似洛阳。"]},{"t":"黎明府移治平乐","f":"七言律诗","c":["古来良吏独称难，宦拙那能走上官。","改道方知齐晏子，求名应薄汉倪宽。","行过桂岭闻猿狖，别后邾城忆凤鸾。","从此治平堪第一，徵书早拟下长安。"]},{"t":"冼光禄迁应天别驾","f":"七言律诗","c":["几载鹓班侍冕旒，承恩南下秣陵秋。","留都旧美蟠龙胜，别驾元堪展骥游。","六代江山馀指顾，先朝勋业衍箕裘。","知君恋阙情何限，清梦还依五凤楼。"]},{"t":"寄高正甫","f":"七言律诗","c":["京国凉生旅梦寒，思君持赠只秋兰。","风尘远道怜三益，意气交情羡二难。","海内同声堪此别，吟边孤月与谁看。","慇勤尺素聊相寄，会见联翩双羽翰。"]},{"t":"赠段明府","f":"七言律诗","c":["与君射策向明光，捧檄还承宰一方。","凋敝已知询瘼久，错盘端合借材长。","九江枫叶随乡路，五岭梅花待客觞。","南顾不须廑圣主，汉家元自有循良。"]},{"t":"寿王太淑人八十","f":"七言律诗","c":["经国才猷美度支，主恩聊慰倚门思。","三朝贻翼青箱旧，八座承欢綵服宜。","南极有光缠婺影，北堂重庆荷纶私。","家庭昼锦常相并，岁岁翘冠映寿卮。"]},{"t":"天宁寺谒詹观察先生时以入贺至","f":"七言律诗","c":["万里旬宣驿路遥，暂来兰若驻星轺。","每缘推毂怀知己，犹记乘骢肃百僚。","消息几能通蜀栈，瞻依何易切云霄。","况逢北极呼嵩日，金鉴亲看上圣朝。"]},{"t":"苏国博以考绩至迁官南大理复还金陵","f":"七言律诗","c":["十年声誉满词垣，璧水传经道愈尊。","报绩已从南国重，承恩新自汉宫蕃。","秣陵风月还相待，廷尉刑章定不冤。","杯酒雄谈殊未悉，忍看离袂出都门。"]},{"t":"送周子时司理岳州","f":"七言律诗","c":["翩翩裘马帝城新，交态何如公瑾醇。","观礼共随宗伯后，承恩先借洞庭春。","郡中民瘼疑堪谳，阙下徵书念转频。","到日岳阳登览处，勋名端拟范公伦。"]},{"t":"至后梁从甫招同郭学宪雪中小集时余捧檄将就道矣","f":"七言律诗","c":["书云初罢雪濛濛，岁岁阳生景略同。","对酒总怜时屡改，论文堪羡赋争雄。","他乡缥缈风尘外，俗吏驱驰怅恋中。","握手与君仍几醉，夜来先梦岭云东。"]},{"t":"送徐敬舆令浮梁","f":"七言律诗","c":["几人齐客郑公门，推毂同君礼并尊。","高谊更联宗伯署，清谈曾笑石壕村。","惭余墨绶恩俱下，喜尔青箱业尚存。","共道圣朝资献纳，早看星聚切微垣。"]},{"t":"留别陈正甫","f":"七言律诗","c":["数月燕都屡接游，季方才调迥难俦。","名流本自钦前辈，交谊何因得并投。","起草正悬题柱望，折梅先动索居愁。","风尘远道真相忆，宵梦还随谒凤楼。"]},{"t":"答汤义仍","f":"七言律诗","c":["薄宦宁愁寄远荒，岭云偏喜近吾乡。","论文后会应怀李，载酒何人复姓杨。","雪里共听骊唱别，春来苦忆雁书长。","君才照乘元堪美，按剑还谁骇夜光。"]},{"t":"道出徐州值冰始泮莫兵宪助以舟役","f":"七言律诗","c":["一骑南来雪里寒，风尘那有罄交欢。","使君高谊谁当似，独客羁怀好自宽。","波静吕梁冰始泮，春生淮海腊初残。","乘流几日扁舟下，不记人间叹路难。"]},{"t":"舟中望匡庐","f":"七言律诗","c":["江光荡漾片帆轻，更喜庐山入望晴。","飞瀑直随群嶂出，断虹遥挂数峰明。","难骖白鹿云中驾，暂借青龙水上行。","试问紫阳人去远，九经还似宋诸生。"]},{"t":"西行抵端州同崔计部黄宪副郭茂才话别","f":"七言律诗","c":["风雨长途黯不开，可堪新别故乡来。","江头薄暮聊停舸，客里逢君漫举杯。","秉烛剧谈消永夜，推篷暝色落荒台。","交亲怅念分携处，却苦津人解缆催。"]},{"t":"舟次浔洲赠薛明府有引","f":"七言律诗","c":["孤舟暂泊浔江濆，地主西来孰似君。","南国交游伤共远，东藩雨露忆曾分。","象贤不愧中朝武，手泽还藏百代文。","四字生平思燕翼，一枝长播桂林芬。"]},{"t":"送李明府迁守陆凉","f":"七言律诗","c":["六载分符抚字劳，梦悬丹陛协三刀。","遐荒雨露初能遍，万里风云迥自高。","此日棠阴思卧辙，他宵月下忆同袍。","专城汉阙恩非薄，异绩还看赐玺褒。"]},{"t":"金将军招集镇南楼赋赠二首将军曾有事东粤兹移镇楚 其一","f":"七言律诗","c":["杯酒南楼寄兴新，将军礼意为谁真。","清平乐事逢今日，儒雅风流识主人。","四野苍茫馀杀气，千山迤逦隔边尘。","论文好及韬戈会，无那旌麾拥传频。"]},{"t":"金将军招集镇南楼赋赠二首将军曾有事东粤兹移镇楚 其二","f":"七言律诗","c":["忆君授钺向东行，谈笑曾销渤海兵。","两粤风尘兼节制，五溪荒服待旄旌。","龙城久幸无蜂扰，麟阁还期有骏声。","圣世莫嫌虚抱武，且将休养答升平。"]},{"t":"和陈使君赠童参戎","f":"七言律诗","c":["忽看持节下南州，况值新凉满郡楼。","共喜升平当此会，敢云凋敝不宜秋。","几年绝徼俱归马，阖境何人更带牛。","最是威名堪服远，祗应公暇美同游。"]},{"t":"喜峒蛮来附","f":"七言律诗","c":["怪尔凭陵岁月长，复岩深箐古夷荒。","岂因为政非鸾凤，自是难驯似犬羊。","买犊世无兵作祟，占鸡人乐醉为乡。","从今勿作羁縻态，天子宵衣待越裳。"]},{"t":"跃鱼岩偕诸文学小集","f":"七言律诗","c":["背郭灵岩境最幽，翛然暑气到全收。","孤峰巀嶪耸丹壑，旷野苍茫惊素秋。","政暇不妨随胜会，调同常拟续仙游。","醉来欲挹龙潭水，遍洒民间八月畴。"]},{"t":"送赵生兄弟岁荐北上二首 其一","f":"七言律诗","c":["万里瞻天思正纷，几回飞梦绕彤云。","一门学冠诸生业，双剑光摇五纬文。","客路风尘休怅别，帝城消息好先闻。","五陵衣马皆豪俊，到日花殷酒并醺。"]},{"t":"送赵生兄弟岁荐北上二首 其二","f":"七言律诗","c":["千金骏马待燕台，三径难留二仲开。","谢客久誇池草咏，蜀人应荐子虚才。","已看威凤翔丹穴，更拟骊龙起蛰雷。","明到京华秋兴好，裁书须及雁南来。"]},{"t":"得劳明府书","f":"七言律诗","c":["绝徼分符亦汉曹，怜君曾此试牛刀。","非缘今日催科拙，那识前人抚字劳。","共惜单车成薏苡，岂容三径即蓬蒿。","伫看论定徵岩穴，喜见双凫傍阙高。"]},{"t":"镇粤楼同朱文学吴将军董孝廉宴集","f":"七言律诗","c":["百尺危楼对夕曛，旅中觞咏得同君。","并游词客皆能赋，自识将军雅好文。","近地喜无豺虎穴，荒郊多牧马牛群。","秋风入夜从萧索，独客愁应醉里分。"]},{"t":"陈使君报绩","f":"七言律诗","c":["使车何日莅双旌，忽喜三年报政成。","泽以褰帷深粤徼，恩堪赐盖下承明。","昔闻蜀郡歌来暮，今见河南课治平。","共道寇君能几借，徵书早晚下龙城。"]},{"t":"答友人九日道中见寄","f":"七言律诗","c":["谁共登临醉夕晖，宦情萧索赏心微。","黄花已负尊前约，红叶偏愁客里飞。","但喜新诗能寄远，不妨游子未言归。","吟馀独酌杯中酒，漫忆人间复授衣。"]},{"t":"送石使君之泸州二首 其一","f":"七言律诗","c":["喜闻皂盖新传命，休记明珠旧暗投。","未得鸣珂还帝里，且看建节出炎州。","行边露冕春盈野，公暇裁诗月满楼。","知有文章能谕蜀，依稀乘传赋西游。"]},{"t":"送石使君之泸州二首 其二","f":"七言律诗","c":["远宦何妨更典州，徵书指日下龙楼。","人情黯淡云和雨，世事浮沉春复秋。","莫以长途嗟疋马，已于游刃少全牛。","渡泸暗忆前朝事，开济能无念武侯。"]},{"t":"喜童将军凯旋","f":"七言律诗","c":["腊尽初看秉钺行，春明已奏凯歌声。","共言荒徼时将泰，喜见长缨事竟成。","蛮峒总知瞻北极，圣朝无复议南征。","夜来风雨溪头急，疑是天河洗甲兵。"]},{"t":"柳侯子厚刘贤良蕡二祠落成","f":"七言律诗","c":["宫墙并峙遗容俨，俎豆重新岁祀齐。","唐室几人堪密勿，诸君何事总蛮溪。","当时望逐铜驼远，千古魂依越鸟栖。","圣代表章逢使者，共瞻英爽贯虹霓。"]},{"t":"答佘孝廉","f":"七言律诗","c":["何处双鱼远寄声，若怜漂泊滞龙城。","乡园几度逢归雁，词客多时愧友莺。","一载催科还自拙，十年献赋待君成。","明庭结士恩非薄，况已才华动汉京。"]},{"t":"寄郑承孟明府","f":"七言律诗","c":["别后琴声各一方，梦回千里忆传觞。","官贫案牍逢多暇，人远音书望转长。","粤社诗才推俊逸，汉家治行继循良。","等閒纵目云山外，宾从无由托郑庄。"]},{"t":"送朱孝廉春试","f":"七言律诗","c":["西方才子动相闻，艺苑名高孰似君。","藏豹几年深泽雾，从龙今日定为云。","且辞博士秦朝禄，共识贤良汉代文。","明到曲江春信好，可堪天外忆离群。"]},{"t":"赠严明府归桂林","f":"七言律诗","c":["羡君壮岁即投簪，绿野堂开桂树林。","松菊故缘三径在，风尘宁受二毛侵。","岩前种秫黄云满，洞里餐霞紫气深。","往日甘棠休更问，年来知己遍城阴。"]},{"t":"入省次洛容登舟","f":"七言律诗","c":["日晚凉生洛水头，行人初上木兰舟。","暂辞案牍为公暇，且与琴书作漫游。","永夜窥床怜月色，短篷欹枕听溪流。","五更梦觉渔歌起，湖海分明思复悠。"]},{"t":"孤村","f":"七言律诗","c":["尽日经行草满原，萧然云石几家村。","飞岚片片山当户，宿雾濛濛江对门。","稚子凄凉看饮犊，邻人阒寂伴听猿。","追论往事时相慰，兵后诛求幸独存。"]},{"t":"宿宣成书院二首 其一","f":"七言律诗","c":["寥寥院宇倚城开，秋草离离满砌台。","新月夜悬人境远，西风时过女墙来。","隔池红落莲初老，高树黄侵叶并催。","信宿旅怀堪对此，呼儿聊进掌中杯。"]},{"t":"宿宣成书院二首 其二","f":"七言律诗","c":["重门深锁绝纷嚣，客思难裁转寂寥。","几树寒蝉过永昼，半云孤雁到清宵。","金飙飒飒檐边度，玉露垂垂槛外飘。","秋夜故长难得寐，隔城听彻几声箫。"]},{"t":"十五夜同颜使君陈别驾谢明府对月","f":"七言律诗","c":["次第看秋到此宵，月圆秋满兴初饶。","商声淅历吟风叶，凉气微茫湿露条。","万里清光开玉宇，千年胜事拟银桥。","同来问月人俱醉，一曲狂歌杂凤箫。"]},{"t":"寄黎思正明府","f":"七言律诗","c":["忆昨逢君出帝城，分符吾亦向西行。","盈盈一水双离绪，寂寂经年各宦情。","兵后疮痍劳抚字，民间休养颂生成。","明堂计吏还今日，闻道昭潭最有声。"]},{"t":"秋试后邵子任明府招集风洞山","f":"七言律诗","c":["桂岭秋高木叶丹，翠微深处共凭阑。","风云气壮三江色，乡国怀增九月寒。","醉里顿令羁思改，坐来不觉夕阳残。","公馀此会应难数，赋笔凭君纪所欢。"]},{"t":"赠童将军移镇平乐","f":"七言律诗","c":["闻道昭潭始罢兵，买牛何地不归耕。","远夷向德应难恃，当宁抡才复此行。","安养但同淮蔡日，隐忧宁笑洛阳生。","圣明待尔纾南顾，特典还看次第成。"]},{"t":"送沈医归淮安","f":"七言律诗","c":["医业旧精淮海上，济人功亦满南荒。","眼中瘴雾殊非恶，肘后丹砂总异方。","桂岭霜高闻旅雁，柳江波静泛归航。","壮怀复有游燕约，喜尔名先入帝乡。"]},{"t":"送陈使君入觐","f":"七言律诗","c":["遐荒两度入朝天，此日登舟望若仙。","瘴海秋清携鹤远，上林春暖听莺迁。","过家綵服新承诏，拜阙班行旧接联。","边郡已知难借寇，东南民力仗谁怜。"]},{"t":"人日饮计郡守宅","f":"七言律诗","c":["五马归来组绶轻，背城别有醉翁亭。","披筵胜会逢人日，投辖深宵恋客星。","早岁遗荣机尽息，閒居养邃德全馨。","春光共引林塘兴，宦迹休论水上萍。"]},{"t":"喜明府家叔自楚中适至","f":"七言律诗","c":["无复青毡为楚留，南来疋马古融州。","十年不愧诸生长，三仕宁惭百里侯。","莫以棘栖堪卧理，共看民力总须愁。","风尘道路何多日，且对芳樽话故丘。"]},{"t":"饮丁别驾园亭因见其二子","f":"七言律诗","c":["驱驰岁月旅中过，谁解招携到薜萝。","出郭小车春已暮，逢君浊酒兴还多。","短墙暗度烟霞色，丛桂新成雨露柯。","自惜赏心羁簿领，可能花下惯来歌。"]},{"t":"送陈郡丞归闽","f":"七言律诗","c":["何事移居到郭西，数函图籍一诗奚。","蛮烟瘴雨行俱遍，宦思羁怀转自凄。","两粤口碑今未改，百年心事古堪齐。","归时莫恋渔矶约，天路旋看动马蹄。"]},{"t":"客有诗挽先君者依韵答之二首 其一","f":"七言律诗","c":["浮世埃尘一亩宫，可怜遽问若堂封。","音容永隔幽明路，涕泪虚悬旦暮钟。","野服祇伤残薜荔，秋江何用怨芙蓉。","凭谁为作招魂赋，缥缈烟霞七十峰。"]},{"t":"客有诗挽先君者依韵答之二首 其二","f":"七言律诗","c":["龙城薄宦已三霜，几度瞻云忆故乡。","十里畹兰幽可佩，一朝风木恨偏长。","难逢鹤驭归华表，未得鸾书下建章。","独客徘徊伤远道，尚怀倾盖赋山阳。"]},{"t":"劲节遐思卷","f":"七言律诗","c":["悠悠往事总堪伤，百载深闺作未亡。","自有陈情知令伯，何妨挺节比共姜。","松楸冢上冰霜凛，兰玉阶前雨露长。","莫写幽词嗟薄命，女中谁得并流芳。"]},{"t":"送叶贡士入京","f":"七言律诗","c":["十载芹宫纪上才，承恩初许集蓬莱。","明经敢谓逢时晚，奏赋争看诣阙来。","上国秋高鹏翮远，帝城春暖杏花开。","谢家兰玉传芳早，为道黄金满郭台。"]},{"t":"送林文学自三水迁夹江令二首 其一","f":"七言律诗","c":["绛帐几年瞻讲席，青衿多日傍词坛。","恩逢百里符初授，望入千山别亦难。","化雨春馀三水绿，明霜秋到夹江寒。","悬知谕蜀文成日，堪寄同毡旧所欢。"]},{"t":"送林文学自三水迁夹江令二首 其二","f":"七言律诗","c":["为忆春风岭外覃，分携犹自意难酣。","传经并美三鳣兆，博古多从二酉探。","奇字久无嘲尚白，诸生应有谢成蓝。","相从不尽临岐思，此地留传即道南。"]},{"t":"送谭金吾北还","f":"七言律诗","c":["家本东南海上村，先朝甲第入中原。","常瞻岭树怀乡国，忽拥宫衣下故园。","载道儿童争笑问，百年父老款相存。","乘轺复送朝天去，喜到都门亦里门。"]},{"t":"送高中甫春试兼寄仲子正甫时季子初为茂才","f":"七言律诗","c":["握手河梁将送远，君家兄弟意堪亲。","休论赵璧偿城晚，须信燕金结士频。","海内时名三凤起，斗间剑气二龙新。","到来欢极提携舞，花萼能辉紫陌春。"]},{"t":"易太学游吴还过访值余服阕索赠赋此","f":"七言律诗","c":["三年风木绾愁心，病起萧然思不禁。","尘榻偶逢高士下，淡交真向古人寻。","阳春敢谓无同调，流水还应有赏音。","君听吴趋殊未厌，怪来翻忆越人吟。"]},{"t":"起复赴选答邓玑伯使君","f":"七言律诗","c":["几从岭外忆明光，又向河梁别故乡。","谁恋孤舟聊信宿，忽来五马旧循良。","新诗赠我仍停棹，浊酒逢君更尽觞。","圣主若还幽侧问，拟于天路待□骧。"]},{"t":"答杨茂才","f":"七言律诗","c":["汉阙频年策治安，雄才敢拟众人看。","同时□□相如赋，清世堪弹贡禹冠。","燕市和歌如可待，越坛盟好未应寒。","邮亭说剑悲离索，长忆君家有镆干。"]},{"t":"濛里舟中","f":"七言律诗","c":["江风吹浪雨犹寒，面面群山碧霭攒。","贾客帆樯依岸出，人家灯火隔林看。","渐于僮仆情亲厚，转怯关山路渺漫。","半月离家殊未久，短吟聊放客怀宽。"]},{"t":"南浦旅怀","f":"七言律诗","c":["羁栖无奈旅愁攻，寂寞凭谁问转蓬。","江上正多梅子雨，波间还起石尤风。","南州高士名虚在，旧馆仙人事已空。","最是浦云长不断，几回飞护客舟同。"]},{"t":"湖口阻风","f":"七言律诗","c":["不尽天风扬素波，扁舟几日滞江沱。","客情久识难行路，旅调新翻无渡河。","莫计邮程悲远道，且看鸥鹭狎渔蓑。","南中风候何常定，五两旋催彩鹢过。"]},{"t":"舟次清江冯睢阳以简招辞之继就酌舟中","f":"七言律诗","c":["何处怀人水一方，每依云树望睢阳。","双鱼忽至长淮外，驷马仍过孔道旁。","对酒谩疑河朔饮，坐谈深接令君香。","风尘此会知非偶，何必还登单父堂。"]},{"t":"总河潘公遣役护行舟次报谢二首 其一","f":"七言律诗","c":["岭海霜威早避骢，三朝经济主恩隆。","翕河久藉扬周烈，睹洛真如颂禹功。","东土绣裳新白简，西曹曳履旧青宫。","君王眷念知无已，开阁清时复许同。"]},{"t":"总河潘公遣役护行舟次报谢二首 其二","f":"七言律诗","c":["停车何地不春阳，中外名高四十霜。","功满朝端瞻赤舄，业传江左试青箱。","泰云挟雨崇朝遍，海国歌风化日长。","惭愧卑微叨礼数，更容诗句发清狂。"]},{"t":"舟抵清源曹侍御宅忧在里再过舟中","f":"七言律诗","c":["留滞江南望阙回，逢君暂亦出西台。","百年风木情偏感，千里萍蓬笑乍开。","白马众疑骢马避，缟衣人道绣衣来。","中朝旧侣时相忆，法座星光切上台。"]},{"t":"九日登丛台","f":"七言律诗","c":["何处登高选胜游，异时歌舞此中收。","风尘日上龙山帽，月色初分庾亮楼。","已有白衣能送酒，何须黄叶共悲秋。","逢迎少暇成高会，只愧无能抗督邮。"]},{"t":"元夕过宋子顺署中小饮","f":"七言律诗","c":["沉沉院落雪初消，月色溶溶逗绮寮。","火树夜寒花并美，璧门星聚景偏饶。","行游士女多欢洽，羁旅朋交岂寂寥。","不为主人增酒态，千金何以直兹宵。"]},{"t":"周进士赴柳州司理枉过见赠赋答","f":"七言律诗","c":["孤城忆我曾游地，此日逢君感慨深。","拙政祇能宽积赋，远民敢自厌殊音。","身辞瘴岭惭无补，梦绕蛮烟思不禁。","愿得谳疑冤尽洗，敢劳城郭问棠阴。"]},{"t":"送王君聘令瓯宁","f":"七言律诗","c":["宜人秋气蓟门时，仙令飘飘万里驰。","五岭乡心随白雁，八闽海色动青骊。","烽烟西北频惊眼，民力东南可察眉。","我亦分符同作吏，知君为政是吾师。"]},{"t":"答易山人","f":"七言律诗","c":["邮亭杯酒昔相别，忆尔难忘白玉羁。","秋梦两悬南海月，春风还隔上林枝。","经年尺素重来日，万里危楼入望时。","勿道武陵堪避俗，桃花流水使人知。"]},{"t":"送子顺令彭泽","f":"七言律诗","c":["几年坛杏有辉光，百里新恩近拜郎。","匹马西风辞冀北，扁舟明月度浔阳。","莫思漉酒柴桑径，祇合鸣琴单父堂。","回首可言天渐远，双凫还傍五云乡。"]},{"t":"和陈新之雪后见贻","f":"七言律诗","c":["晓起琼花扑素琴，开帘犹道月华侵。","书云合奏丰年瑞，歌雪先倾下里心。","物候正随灰管动，客怀偏仗酒杯深。","知君复有官梅兴，清赏何由并汝阴。"]},{"t":"对雪忆梅","f":"七言律诗","c":["北风吹雪渐成堆，恨少寒稍雪里梅。","卧阁琴囊空自拂，法曹诗卷为谁开。","春前庾岭同乡梦，月下罗浮忆旧杯。","亦有江南逢驿使，了无相寄一枝来。"]},{"t":"行役肥乡境上小集张方伯别业同广陵宗良弼","f":"七言律诗","c":["春风境上揽晴芳，倾盖停骖漫举觞。","贤聚久为冠盖里，吏来翻似石壕乡。","不因行役红尘内，那得招携绿野旁。","况是广陵新制曲，传来花下兴偏长。"]},{"t":"春夜宴集丛台听箫","f":"七言律诗","c":["春游吏事苦相催，秉烛何妨入夜来。","野色全迷窗外树，星光环照坐中杯。","流觞曲水虚良月，飞盖西园复上才。","娇管清歌怜并发，教人重拟凤箫台。"]},{"t":"送薛侯宣使郑便道归省","f":"七言律诗","c":["剑骑翩翩出蓟门，春光逢尔醉平原。","天潢带砺恩长厚，使者皇华礼并尊。","休沐暂辞丹凤阙，承欢仍在卧龙村。","锦游况值秋初好，桂月松风满故园。"]},{"t":"暮春登紫金山二首有引 其一","f":"七言律诗","c":["一春风物报将阑，乘兴还来问紫山。","寓目总堪容傲吏，振衣疑渐出尘寰。","王乔洞在凫先起，太保堂空鸟自还。","怀古思乡宁废酒，难逢杯酌共云间。"]},{"t":"暮春登紫金山二首有引 其二","f":"七言律诗","c":["紫气遥来出紫宫，金光隐见有无中。","玄坛并建群灵拥，宝塔双瞻瑞霭通。","万顷桑麻春雨后，千家城郭日华东。","披襟已尽兰台胜，宋玉何劳对大风。"]},{"t":"圣井有引","f":"七言律诗","c":["凿井何年纪圣名，总缘神贶及群生。","银床倒映冰壶冷，碧甃长涵水镜平。","霖旱一方沾沛泽，润馀千里挹澄清。","地灵若更周民隐，不待祈年雨亦行。"]},{"t":"宋文学自以忧郁不乐远游适志赋此别之","f":"七言律诗","c":["雨过郊原万绿稠，客星初动碧云头。","四愁不尽张衡赋，五岳堪为向子游。","谈里有天皆碣石，花间无地不丹丘。","汾亭旧业应常在，莫恋他人倒屣留。"]},{"t":"送顺德张使君迁苑马卿贰","f":"七言律诗","c":["几载邢州政独奇，一方讴颂满褰帷。","竹符幸借分三辅，麦瑞重看秀两岐。","谁挽福星留卧辙，但悬卿月照前麾。","他年太史收循吏，何似民间口作碑。"]},{"t":"答李长庚","f":"七言律诗","c":["多年抚字愧功成，窃禄长惭负圣明。","宾客为谁誇北海，文章于尔识西京。","草茅书就张天觉，鹦鹉才高祢正平。","秋好会当随计吏，骏金还自重燕城。"]},{"t":"闻谤答陈新之","f":"七言律诗","c":["几从畏路戒前车，望入羊肠恨转赊。","彭泽故栽门外柳，河阳羞对县中花。","稍疑落莫诗为祟，谩道冲腾剑有华。","犹幸主恩宽放逐，敢将漂泊怨长沙。"]},{"t":"答赵孝廉","f":"七言律诗","c":["满目风涛祇自伤，十年回首笑为郎。","含沙每恨形难见，下石翻愁计易长。","畏路岂须悲失马，高冈谁为惜鸣凰。","樗材止合甘留滞，潦倒江湖忆庙廊。"]},{"t":"别诸僚友","f":"七言律诗","c":["梗萍千里结同袍，此际分携思独劳。","时事敢云堪怒发，世人真亦善吹毛。","穷愁未变心如水，积毁从他笑有刀。","别后秋怀应渐好，丛台孤月为谁高。"]},{"t":"别乡大夫","f":"七言律诗","c":["握手相看感慨存，逐臣真自负平原。","几从月下陪长啸，或忆尊前赋大言。","薄态已成曾氏杼，高情还过翟公门。","临岐未洒穷途泪，薄谴能无识主恩。"]},{"t":"别诸生","f":"七言律诗","c":["二载栖栖动越吟，敢将岁月问升沉。","循声自我无三异，拙宦从今学五禽。","引咎不须惭白简，思玄多是愧青衿。","秋高上国看鹏翼，次第扶摇慰远心。"]},{"t":"别众父老","f":"七言律诗","c":["宦情萧索与谁论，直道斯民喜尚存。","岂有循良堪作传，谩劳苍赤苦攀辕。","暗投已分无完璧，广照何由到覆盆。","底事慇勤酬别绪，愿祈丰岁惠元元。"]},{"t":"寓真州僧舍夜梦登恒山志感","f":"七言律诗","c":["单车几度涉滹沱，此日重来感慨多。","回首不堪时事改，低眉祇傍畏途过。","尘纷暂远宜僧话，酒禁初宽足浩歌。","一梦恒山秋色远，芙蓉千叠奈愁何。"]},{"t":"谒别吕翁祠","f":"七言律诗","c":["南北支离叹此身，相逢俱是梦中人。","久知鸟道多危辙，曾见盐车解绝尘。","社酒尚违元亮菊，秋风又美季鹰莼。","滔滔骑从群游客，莫笑卢生梦未真。"]},{"t":"赠苏羽士","f":"七言律诗","c":["城郭何人识隐沦，黄冠绿发一閒身。","早从相鹤仙群侣，更许笼鹅墨客亲。","宅以谈玄誇胜事，室同虚白净纤尘。","刘郎别后知何处，空记桃花满院春。"]},{"t":"寓清源诸乡友携具过访","f":"七言律诗","c":["萧索西风独倚楼，殊方落日正悲秋。","忽逢杯酌成嘉会，似为风尘慰倦游。","一醉浑忘身是客，微名真与世同浮。","相酬不尽乡园意，徙倚堪消万斛愁。"]},{"t":"对菊","f":"七言律诗","c":["久淹末路秋多思，尚喜东篱菊有花。","杯酒未曾输蒋径，诗篇犹自拟陶家。","休悲摇落霜逾峻，独对幽香日未斜。","不是岁寒徵晚节，却教桃李尽年华。"]},{"t":"得从兄伟侯书却寄","f":"七言律诗","c":["书至遥怜汝尚存，几回飞梦绕乡园。","风涛已恨惊蓬鬓，泉石何妨老席门。","海上碧云悬故里，天涯芳草倦王孙。","可能扫石溪头坐，往事同君仔细论。"]},{"t":"月夜泛舟","f":"七言律诗","c":["携壶理棹出江干，乘兴安流夜未阑。","霜月浸空秋色老，风林摇岸叶声乾。","短箫凄断中川听，长剑凭陵傍斗看。","坐久黑貂寒渐彻，诗成还仗酒杯宽。"]},{"t":"慰同寓者思归","f":"七言律诗","c":["长风万里困南图，游子天涯望眼枯。","愧我出山成小草，怜君远道忆文芜。","清江渡口听鸿雁，明月楼中唱鹧鸪。","稍待青春堪作伴，何须雨雪问征途。"]},{"t":"送内弟体健南回","f":"七言律诗","c":["几回愁望雁南征，雪里何当复送行。","投辖总难宽别绪，歌骊徒自切归情。","渐看客散堪罗雀，谁及春来共听莺。","兄弟故园如有问，十年不愧旧书生。"]},{"t":"自清源入京","f":"七言律诗","c":["长途匹马又朝天，曾记驱车入赵年。","惨淡风霜欺旅鬓，萧条山水傍孤弦。","流言促驾成三仕，拙宦何阶待九迁。","堪笑几回霄汉上，为他人望已登仙。"]},{"t":"长至日宿河间客舍","f":"七言律诗","c":["年年至日愁为客，此夕愁怀倍不舒。","失路未论先策足，征途翻自怅离居。","五更清梦随天阙，一点丹心到玉除。","最恨邻鸡催晓曙，暗尘旋复满巾车。"]},{"t":"京中贻诸游好二首 其一","f":"七言律诗","c":["千里驱车又帝城，相看悲喜不胜情。","旅颜尚带风涛色，生计重依日月明。","且共狂歌燕市饮，休嗟故步寿陵行。","当年志意飞扬甚，此夕还应剑气横。"]},{"t":"京中贻诸游好二首 其二","f":"七言律诗","c":["九陌红尘上玉珂，不妨文酒借烟萝。","谈天气压青云壮，待月词雄白雪多。","万里风霜驱傲骨，重来霄汉入悲歌。","应刘此日公车满，轮囷无因奈若何。"]},{"t":"送何进士令嘉兴","f":"七言律诗","c":["吴越山川足胜游，喜君仗剑出皇州。","阳回蓟北催征骑，春在江南舣客舟。","民力总应宽保障，主恩有待借前筹。","请看此日朝阳凤，棘地何能更复留。"]},{"t":"饮杨贞复太史宅遇雪","f":"七言律诗","c":["白玉堂前满六花，天然色相斗瑶华。","兴来不假山阴棹，坐久频煎学士茶。","鳷鹊影分光入户，鹔鹴寒仗醉为家。","罗浮一别无消息，忆共看梅到海涯。"]},{"t":"送杨肖韩民部谪陜州","f":"七言律诗","c":["执戟曾疲阙下班，那堪世路复多艰。","流言尽属杯中影，同病俱怜镜里颜。","二室莺花供客赏，五陵衣马待君还。","周南岂必嗟留滞，逸驾长途未可攀。"]},{"t":"送王孝廉奔讣还柳州","f":"七言律诗","c":["长年旅食傍金台，意气看君亦壮哉。","岂以浪游忘寸草，祇缘先泽在三槐。","云边泪眼天无极，雪里愁肠日几回。","归去蓼莪应暂废，公车还待尔重来。"]},{"t":"昼锦四荣诗为举主大司寇张公作加宫保","f":"七言律诗","c":["华发天书喜屡褒，乞归仍录旧臣劳。","一时礼秩隆三少，二省恩光冠六曹。","北斗声华悬郑履，上公休瑞应虔刀。","已闻侧席思贤硕，须信东山卧未高。"]},{"t":"赐飞鱼服","f":"七言律诗","c":["都门争御衮衣频，又见中朝锡服新。","光夺彩云摇剑佩，喜传丹陛动簪绅。","尚方箧笥优承诏，五色文章稳称身。","明到集贤欢昼锦，白衣谁道是山人。"]},{"t":"赐金","f":"七言律诗","c":["诏许辞荣访逸林，更于蕃赉识皇心。","非缘绿野光亭榭，便与香山助醉吟。","清德久传杨氏里，湛恩宁比陆生金。","相携宾旧多欢洽，总沐天朝惠予深。"]},{"t":"赐驰驿","f":"七言律诗","c":["一自东都祖二疏，抗章谁复早悬车。","寒辞蓟苑荣休沐，春望丛台赋遂初。","乘传遍临先赐履，拥旄遥爱旧吾庐。","祇怜负弩非前令，目极洺关一怆予。"]},{"t":"都门僧舍答黄汝纶岁暮述怀之作","f":"七言律诗","c":["相逢衣袂满缁尘，总是天涯一旅人。","幸舍岂孤弹铗客，玄林空笑宰官身。","吟馀白雪年垂暮，颂入青阳岁又新。","即道淹留家万里，可能虚度帝城春。"]},{"t":"人日汝纶过访留酌","f":"七言律诗","c":["东风随岁入长安，万户春光纵眼宽。","幸与人同今日胜，更留君叙隔年欢。","菜羹旅食堪循俗，柏酒馀杯解送寒。","忽向江湖怜杜老，私忧直道路行难。"]},{"t":"与林孝廉小酌论旧并柬诸乡友","f":"七言律诗","c":["乡书十载忝齐贤，何意看花一日先。","弱羽翻疑淹九万，彩毫终待奏三千。","陵阳泪尽方呈璞，流水音高未绝弦。","为问同来燕市客，有谁还愧在卢前。"]},{"t":"林志和明府过谈旅舍","f":"七言律诗","c":["马首当年忆并东，从前消息半相同。","重来大集明堂吏，一笑谁怜塞上翁。","百里多君工制锦，孤臣何地托飘蓬。","亦知双剑时还合，未若延津气似虹。"]},{"t":"别上计诸子","f":"七言律诗","c":["都门二月送征轮，冰雪寒消暖渐新。","柳眼暗窥今日酒，花神潜动去年春。","明堂礼就应增秩，独客愁多畏傍人。","怪得望穷仙舄远，尚留衣袂满京尘。"]},{"t":"送何参军之衡阳","f":"七言律诗","c":["十年清誉美何郎，此日承恩出建章。","细柳繁烟开梦泽，绿蘋疏雨渡潇湘。","自缘簪组光莲幕，更喜风云傍梓乡。","公暇尺书如有念，可因回雁寄衡阳。"]},{"t":"春日登毗卢阁","f":"七言律诗","c":["燕山胜事在青阳，与客乘閒叩上方。","风转法云空外度，天开化日望中长。","红尘端不侵莲界，紫气偏能入羽觞。","宦海只今多自苦，欲移般若作慈航。"]},{"t":"答徐太学","f":"七言律诗","c":["握手他乡各问年，敝裘羸马总萧然。","尊如北海宾长集，榻有南州士独贤。","去就此时难任性，升沈末路只由天。","汉朝故事须公等，诣阙书成合四迁。"]},{"t":"留别袁敬德","f":"七言律诗","c":["千树桃花去后栽，玄都何日更重来。","黄金笑我非奇骨，綵笔怜君自逸才。","易水馀寒侵别骑，阳关新绿照行杯。","漂零剑气何由合，望极龙光烛上台。"]},{"t":"钱使君惠茶","f":"七言律诗","c":["春早仙芽出洞天，清泠堪试惠山泉。","年年采撷占雷候，片片鎗旗爱雨前。","一院真香烹野服，几杯沉困破愁眠。","月团谏议恩元渥，祇阅斜封愧玉川。"]},{"t":"王郡丞有赠未答旋复惠酒并谢","f":"七言律诗","c":["驱车前后出金台，天末萍踪并傥来。","官冷未应徒伏枕，公馀差可慰衔杯。","亭因好事相携酒，我亦怀人姑酌罍。","莫怪诗情太寥寂，苦无头上雨云催。"]},{"t":"益津八景 其一 霸台朝阳","f":"七言律诗","c":["先朝遗胜有高台，晓日登临霁色开。","望似泰山标日观，气如沧海射蓬莱。","五云彩彻层霄迥，万里辉腾八极回。","任是阳光能被远，苍凉先向此中来。"]},{"t":"益津八景 其二 老堤晚渡","f":"七言律诗","c":["郡城南接大堤游，日晚人归古渡头。","家傍寒塘鱼作市，门临荒渚鹜为洲。","夕阳舟楫频来往，野水乾坤任拍浮。","景色不须愁已暮，月明还照荻花秋。"]},{"t":"益津八景 其三 环城烟柳","f":"七言律诗","c":["郊原烟雨递相催，柳色微茫拂翠来。","林际迁莺如上苑，街前走马类章台。","栽移彭泽诗千首，折向阳关酒一杯。","造物固知饶近地，春光漏泄遍城隈。"]},{"t":"益津八景 其四 堂淀风荷","f":"七言律诗","c":["东南凝望尽湖光，冉冉红蕖十里芳。","渌水明霞娇欲语，白蘋过雨暗生香。","吴娃曲调堪移舫，楚客衣裳好纳凉。","似道今人俱解爱，淩波争艳水云乡。"]},{"t":"益津八景 其五 岳庙波光","f":"七言律诗","c":["崇祠寂寂出中阿，新涨环门有白波。","草绿似因蓬作岛，天光疑用镜降魔。","堂前说法龙堪绕，台上翻经鸟屡过。","闻道泰云时挟雨，故添沧水濯盘涡。"]},{"t":"益津八景 其六 觐光山色","f":"七言律诗","c":["城上高楼俯樾丛，山光隐映画图中。","总无竞秀千岩逼，却有寻芳一径通。","天入中原形具美，地临三辅势偏雄。","郁盘灵淑知无尽，长为皇家壮镐丰。"]},{"t":"益津八景 其七 盐河春鸟","f":"七言律诗","c":["东风几日满城陬，冰雪凝寒已渐收。","漠漠水云春自足，飞飞林泽鸟相求。","即看市近机仍狎，何必山深景更幽。","翔集总缘天性在，偶来觞咏亦沧洲。"]},{"t":"益津八景 其八 苑口秋涛","f":"七言律诗","c":["一线江流引急湍，奔腾长作劲潮看。","九河瓴势浮空下，八月涛声杂雨寒。","自是百川能学海，岂无砥柱善回澜。","千年疏凿功思禹，咫尺沧溟大壑宽。"]},{"t":"山斗图为掌院李公赋","f":"七言律诗","c":["早年芳誉彻丹霄，此日中台凛百僚。","总为霜棱推独坐，更缘风采重三朝。","登龙故溢名贤礼，旋马堪同圣相谣。","伫望黄扉资燮理，八荒何地不春韶。"]},{"t":"喜雨","f":"七言律诗","c":["新瀑穿林出岸隈，雄风吹雨歇还来。","霏微四野枯全润，霢霂三农望正开。","昨日桑林成泽国，一时蓬巷已春台。","不知旱魃归何处，更祝为霖遍八垓。"]},{"t":"大司马王公席上对月","f":"七言律诗","c":["待月庭阶月正圆，中天云净出婵娟。","金波泛露辉长夜，玉宇生凉到四筵。","七十主人方健饭，二三宾客尽忘年。","高谈洛下应难数，会有安车自日边。"]},{"t":"闻岛夷犯朝鲜时西贼未平而朝鲜遣使告急不绝于道","f":"七言律诗","c":["二载宵衣正备胡，却传海上又鸣桴。","一时斥堠多烽火，到处闾阎困转输。","使者徵兵催草檄，藩邦乞援望衔舻。","神州敢谓天将厌，干羽还能格后夫。"]},{"t":"送薛德茂自文安应召入京","f":"七言律诗","c":["分符元傍五云乡，第一徵书荷圣王。","日转觚棱腾凤羽，天开阊阖望龙光。","硎新百鍊青萍壮，台重千金紫燕良。","此日送君增感慨，揶揄花外笑偏狂。"]},{"t":"和车一中七夕旅怀","f":"七言律诗","c":["华月娟娟入户明，开帘露下气初清。","我惭儿女年年巧，君念关山处处情。","天上独怜桥鹊影，人间无奈砌蛩声。","罗浮一水非河汉，莫向牵牛恨未平。"]},{"t":"同一中夜集慈华寺","f":"七言律诗","c":["南北飘零寡所欢，驱驰空自愧微官。","秋风念旧鲈鱼脍，夜雨怜君苜蓿盘。","客路相逢乡语熟，禅房深坐漏声寒。","何时得共罗浮月，松露潇潇洒鹖冠。"]},{"t":"十五夜王观察招饮狎鸥亭月色无几雷雨继至感而成咏","f":"七言律诗","c":["西园清夜忝嘉招，尊酒论文乐正饶。","月魄何缘光乍掩，雨师疑亦妒难销。","高谈列炬林鸦散，客思停觞旅雁遥。","稍待风生云雾歛，一轮还自出层霄。"]},{"t":"和大司马王公同钱使君月下园池泛舟之作二首 其一","f":"七言律诗","c":["辞荣十载惬投簪，其奈苍生属望心。","庭下郎君能世业，座中宾客总词林。","忘年许集耆英会，得句如闻正始音。","况是大夫能作赋，胜游应不负招寻。"]},{"t":"和大司马王公同钱使君月下园池泛舟之作二首 其二","f":"七言律诗","c":["水满池塘月满舟，芳亭难遽号宜休。","且拚乐事归三径，自以閒身傲五侯。","别墅开樽时坐啸，西园飞盖每淹留。","已闻疏辅虚前席，此地何能绊绛驺。"]},{"t":"秋夜杜工部凝香亭宴集时周太学兆通自吴下新至","f":"七言律诗","c":["杜曲穿花此会难，深尊谁与罄交欢。","饮醇自昔知公瑾，命驾于今似吕安。","入夜霜高闻朔雁，一时星聚对南冠。","劝君且莫歌长铗，客里茱萸好共看。"]},{"t":"九日登霸台时月落西方倒映台榭倚楼数酌而别","f":"七言律诗","c":["风雨连朝欲满城，今宵喜见月华明。","半轮影动登高兴，万里光馀落帽情。","两地茱萸分客思，几家砧杵乱秋声。","酒酣莫更归来缓，怕遣楼头百感生。"]},{"t":"初冬送杜虞部入京","f":"七言律诗","c":["过里衣冠喜乍逢，尊前谈笑几相从。","谢家池草多康乐，阮氏竹林有仲容。","白下歌棠非宦巧，班生行李自仙踪。","中朝若遇询卑湿，天气长沙赖已冬。"]},{"t":"永清境上遇张孝廉夜酌","f":"七言律诗","c":["谪宦何知复买邻，一时倾盖偶相亲。","南州愧我非高士，东道逢君识主人。","径拥蓬蒿怜仲蔚，辖投宾从美陈遵。","追欢正合持螯醉，况喜当筵月色新。"]},{"t":"再过张孝廉与张太学贾刘二茂才同集","f":"七言律诗","c":["扁舟容与水云乡，弭棹重逢有二张。","狎坐更应推贾垒，高谈谁复短刘墙。","黄催落叶羁愁晚，绿泼新醅旅兴长。","闻说上林将献赋，声华久矣达明光。"]},{"t":"寄卢唐宪明府时起复至都下","f":"七言律诗","c":["回首尘途忆聚星，春风棠杏满龙城。","交游本是同声侣，骨肉元非异姓兄。","南望总愁云远去，北来犹怯路难行。","岁寒莫道冰霜久，已见阳和次第生。"]},{"t":"答王存初大行四首有引 其一","f":"七言律诗","c":["汉家嗣业有玄成，倾盖何如止慕荆。","洛社漫开真率会，瀛洲初重斗山名。","江湖尚识先忧在，云水聊教俗虑清。","况是圣朝思宪老，几回侧席不胜情。"]},{"t":"答王存初大行四首有引 其二","f":"七言律诗","c":["背郭涟漪漾碧塘，雨馀新绿上茅堂。","芙蕖拂艳依秋水，鸥鹭忘机狎野航。","谢俗固多难老诀，羁人亦有却愁方。","曾同飞盖沾清露，月色溶溶过海棠。"]},{"t":"答王存初大行四首有引 其三","f":"七言律诗","c":["龙卧当年忆滞淫，草庐曾自托悲吟。","连城岂合终怀璞，流水多应会赏音。","帝里风光淹彩笔，家庭乐事寄瑶琴。","飞来一片云间月，照见游人此夜心。"]},{"t":"答王存初大行四首有引 其四","f":"七言律诗","c":["艺苑何人最白眉，风前闻尔奏朱丝。","敢云黄牡皆骊牝，直看飞雄愧伏雌。","海上烽烟思赋槊，眼中景物类观棋。","知君使节乘春下，花信先传梦草池。"]},{"t":"答徐内翰见讯","f":"七言律诗","c":["早春曾记傍金台，花下逢君识异才。","恩并三朝殊赉渥，班联四辅近颜开。","紫宫籍府连东璧，彩笔词垣切上台。","清暇子虚如有问，可能促席慰衔杯。"]},{"t":"答曾启东文学","f":"七言律诗","c":["樗散才名愧豫章，燕金敢自叹留良。","寒馀渐见生春色，暗里谁凭识夜光。","迟日煖浮千树晓，条风和动百花庄。","栽培羡尔多桃李，茅茹还看应会昌。"]},{"t":"将之临朐答大司马王公赠别二首 其一","f":"七言律诗","c":["绿野堂前醉别觥，春林好鸟自嘤嘤。","不同赋鵩忧时命，却喜登龙署姓名。","此日孤琴随鹤远，他宵明月怅乌惊。","祇应有待开东阁，会听彤墀曳履声。"]},{"t":"将之临朐答大司马王公赠别二首 其二","f":"七言律诗","c":["投赠慇勤且复留，江湖何地不堪忧。","四愁未若孤臣切，一顾难忘国士酬。","暖入东风碧草细，烟消南浦绿波浮。","华夷自昔知司马，即拟安车下帝州。"]},{"t":"答王之绥","f":"七言律诗","c":["漂泊怜君义独高，小斋曾与读离骚。","莫愁沈约频移带，拟赠王祥有佩刀。","春水五渠江路渺，暮云千里客心劳。","长吟两地空相忆，多暇应难似马曹。"]},{"t":"江应雷偕诸太学追送余苏家桥暮酌有赠答和二首 其一","f":"七言律诗","c":["柳色青青思独劳，霸桥星聚五陵豪。","已因别赋分玄草，更遣离愁付浊醪。","并马尘轻苏市雪，歌骊声散苑家涛。","公车此日需贤哲，谁解诗成得锦袍。"]},{"t":"江应雷偕诸太学追送余苏家桥暮酌有赠答和二首 其二","f":"七言律诗","c":["握手徘徊却为君，旅中那不念离群。","探春预约花为主，入社何妨酒并醺。","两地复悬千里月，长途遍历万山云。","欲知别后相怀处，驻马题诗日正曛。"]},{"t":"答车一中","f":"七言律诗","c":["异乡为客混风尘，薄宦相从似买邻。","世态共看思往事，主恩初下及孤臣。","蛾眉渐老应难妒，鸡肋微名岂遂湮。","汉室谈经推董相，早将三策为君陈。"]},{"t":"答王司封","f":"七言律诗","c":["客舍并州岁乍更，长途匹马又东征。","腰肢自觉虚徇禄，奔走由来只为名。","北海尊罍思旧处，春风岐路别君情。","微才敢附山公启，祇笑嵇康是懒生。"]},{"t":"答郭茂才二首 其一","f":"七言律诗","c":["几年奔逐愧飞黄，去矣怜君酒一觞。","但使高台收骏骨，何言末路有羊肠。","徘徊别意看新柳，淡荡春风入野棠。","后会不知何处是，每依北斗望龙光。"]},{"t":"答郭茂才二首 其二","f":"七言律诗","c":["杯酒临岐别友生，一时去住却关情。","恩仍凤阙随新牒，义似鸡坛恋旧盟。","芳草王孙游渐远，绿波南浦雨初晴。","上林托猎君应赋，得意还能荐马卿。"]},{"t":"百丈厓在东镇沂山","f":"七言律诗","c":["海上岧峣拥翠回，当霄壁立势雄哉。","青春洞口犹含雪，白日泉声似带雷。","天造故悬千尺险，地灵何藉五丁开。","诸峰罗列俱难比，不尽浮云任去来。"]},{"t":"瀑布泉在百丈厓","f":"七言律诗","c":["缥缈丹梯最上头，何来千仞泻飞流。","初疑银汉从天下，忽讶沧波倒峡浮。","草木春回馀作润，江山人藉此相留。","红尘久负登临兴，沾洒欣从物外游。"]},{"t":"初夏宴集迟中丞别墅时牡丹盛开","f":"七言律诗","c":["莫道春归独掩门，春光还在百花村。","几丛蝶舞留芳径，数啭莺歌住短垣。","傍槛故多姚魏品，招游何减李桃园。","公馀雨霁烟霏净，恰好移樽坐晚轩。"]},{"t":"答李张二郡博二首 其一","f":"七言律诗","c":["问月曾同李谪仙，风尘去住感流年。","翻从异地思联榻，犹记芳樽恋别筵。","海上兵戈烽未息，天涯朋旧梦相悬。","八行欲寄加餐字，搔首云间一雁还。"]},{"t":"答李张二郡博二首 其二","f":"七言律诗","c":["薄宦栖迟旅思劳，故人谁与问绨袍。","长吟渭北天边树，未识玄都观里桃。","旧雨不堪诗伴隔，荒台曾共月轮高。","此时对酒空相忆，何处天风下玉璈。"]},{"t":"登朐山","f":"七言律诗","c":["雨足芳郊万绿齐，看山携伴过前溪。","云閒杖屦花迎入，日永壶觞鸟劝提。","比屋喜逢鸡犬静，公庭那有簿书迷。","不妨取醉成高会，共听流莺自在啼。"]},{"t":"读旌孝录为故郡大夫杜公作","f":"七言律诗","c":["早年射策向明光，疆项归来一草堂。","善养岂嫌三釜薄，承恩偏幸百年康。","庭前爱日斑衣永，冢上居庐白发长。","使者几回劳博采，圣恩今已下龙章。"]},{"t":"答云中吕观察","f":"七言律诗","c":["锁钥云中久借恂，秋风戎马净边尘。","登楼坐啸千门月，挟纩长留万里春。","拙宦我甘随牒远，忘年君自托交神。","已闻公府资为宪，伫见天书下紫宸。"]},{"t":"寄高比部","f":"七言律诗","c":["风尘漂泊海东方，翘首金茎路渺茫。","青社赐环栖傲吏，白云题柱忆仙郎。","赋才合迩西山色，谳奏能消六月霜。","不分清曹多燕暇，几时握手近含香。"]},{"t":"寄怀广武诸旧游","f":"七言律诗","c":["一别丛台隔两秋，漂零身世海东头。","伤心往事俱流水，屈指当年几旧游。","投赠我惭青玉案，索居谁问黑貂裘。","此时广武城边月，正好同君大白浮。"]},{"t":"答梁茂才二首 其一","f":"七言律诗","c":["何处新诗念旧裁，忽传尺素傍愁开。","几瞻岭外云边树，犹记尊前月下杯。","泉石祇怀寻壑侣，风波宁有济川才。","于今夜夜看南极，遥见光华入望来。"]},{"t":"答梁茂才二首 其二","f":"七言律诗","c":["五岭群峰万叠高，思乡无奈寸心劳。","吟边桂树非南国，梦里梅花似法曹。","每愧登仙追景倩，空怀纵壑颂王褒。","十年自历羊肠遍，牢落风尘一敝袍。"]},{"t":"秋夜宴吕观察新宅时侍者奏塞上曲","f":"七言律诗","c":["堂构初成燕自来，几人今夕对传杯。","微风却暑娱清夜，细雨生凉引绿醅。","坐客总深碧玉调，塞儿新制紫云回。","休嫌近市仍湫隘，数武阶前且植槐。"]},{"t":"钱使君寄寿老母赋答","f":"七言律诗","c":["忆别河梁越岁华，云山千叠总为家。","芳樽已隔吟边月，彩笔犹传梦里花。","自引斑衣娱爱日，难将春酿拟流霞。","遥闻双白重开宴，几颂南山庆倍嘉。"]},{"t":"寄题益津八敌台","f":"七言律诗","c":["提封千里尽春台，又见崇台面面开。","云物迥连天阙下，股肱独近帝城隈。","霞光睥睨飞常入，烽色萑苻净不来。","自是修文非讲武，登高时有大夫才。"]},{"t":"题杨中丞思亲楼二首 其一","f":"七言律诗","c":["背郭重新百尺楼，楼前霜露迥生愁。","辞荣不羡千秋观，善养曾轻万户侯。","馀庆祇看归绿野，浮生何处觅丹丘。","每瞻堂构思贻翼，却喜传家解作裘。"]},{"t":"题杨中丞思亲楼二首 其二","f":"七言律诗","c":["一上高楼思悄然，片心长在白云边。","蓼莪最引终天恨，岵屺难忘爱日年。","锡命几回瞻拜阙，承欢但欲赋归田。","至今明发怀如旧，强对开帘月万川。"]},{"t":"望京楼和张中丞二首 其一","f":"七言律诗","c":["极目楼头望紫烟，梦回宫阙思悠然。","蓬莱地隔鸿书渺，阊阖天高象魏悬。","万国衣冠同拜舞，当年江汉忆旬宣。","于今独抱葵心在，欲奏南山第几篇。"]},{"t":"望京楼和张中丞二首 其二","f":"七言律诗","c":["江湖幽思近何如，天畔楼孤望帝居。","御苑春饶莺语合，仙茎露下雁来初。","悬车尚忆齐鸣佩，闭阁惟耽自著书。","此际经纶看世业，升平俱沐圣恩馀。"]},{"t":"常比部谳狱关内事竣还朝时方露祷无以酌别赋此代觞","f":"七言律诗","c":["青青城畔柳条新，折向河桥赠远人。","行部霜飞三辅肃，归朝花发五陵春。","亦知枌社情偏系，可奈桑林念转频。","明到宵衣如召对，不须重拟大东陈。"]},{"t":"初夏过冯将军别墅","f":"七言律诗","c":["将军池馆即仙家，万木森森野水涯。","入户且须先看竹，开樽还似坐餐霞。","林间晓色多啼鸟，帘外风香有落花。","岂厌升平虚抱武，耽幽长自对瑶华。"]},{"t":"珠泉","f":"七言律诗","c":["何处青山海上浮，浮来山下是龙湫。","一潭滉漾沧浪色，万颗匀圆合浦流。","深竹况宜逃暑会，野航真作弄珠游。","与君坐对冰壶澈，可道无因尚暗投。"]},{"t":"赠张司理","f":"七言律诗","c":["楚材钟岳自衡阳，射策声华满建章。","诏下九重辞北阙，官持三尺莅东方。","随车待遍千家雨，谳牍看消六月霜。","闻道圣朝资献纳，更须丹笔侍虞唐。"]},{"t":"答易山人送腊","f":"七言律诗","c":["春前淑气将舒柳，腊尽馀寒已送梅。","愁里酒杯添寂寞，病来诗句废敲推。","年光荏苒真虚度，宦业逡巡岂上才。","羡尔久盟泉石侣，赏心何限白云隈。"]},{"t":"海珠寺谒李忠简公遗像","f":"七言律诗","c":["钟祥曾道应星光，岭海仍流异代芳。","忠赤有心悬疏草，勋猷何意在旂常。","提戈自障鲸波险，请剑宁辞鸟道长。","遗像清高瞻拜肃，珠江犹自胜桐乡。"]},{"t":"赠俞参军","f":"七言律诗","c":["何来趋府擅才华，绿水池边几度花。","走檄名高谁具美，请缨年少自堪誇。","三城钤辖归油幕，五岭风云护绛纱。","文武一时推妙选，湛恩仍待早宣麻。"]},{"t":"韩公祠祠在西樵山上公名雍时总制两广奏免茶税山人德之后为中官所谮引疾乞归卒谥襄毅","f":"七言律诗","c":["一径穿云入翠微，中丞祠庙出林霏。","诛求榷吏恩能逭，采摘山家愿不违。","力食总馀君子泽，绣裳真念小人依。","春来处处茶畦雨，彷佛甘棠露未晞。"]},{"t":"白云洞","f":"七言律诗","c":["岩岩翠壁倚天开，冉冉閒云度壑来。","野瀑细流成曲水，石床积润带苍苔。","芳亭岁引看山屐，纡径时同避暑杯。","贪赏夕阳天忽晚，又从云里戴星回。"]},{"t":"甘棠税驾卷为杨兵宪作","f":"七言律诗","c":["车骑重看到海乡，褰帷夹道旧甘棠。","几年蔽芾依留荫，此日澄清慰奉尝。","故老短筇瞻节钺，使君新绶并银黄。","关西世泽应长在，更普商霖下大荒。"]},{"t":"送袁敬德游勾漏","f":"七言律诗","c":["欲问丹砂事有无，采真何必惮长途。","三江乍泛袁宏舫，五岳新携向子图。","紫气东来星是客，碧云西望月同孤。","如闻葛令当年诀，分取刀圭到药垆。"]},{"t":"听莺","f":"七言律诗","c":["雨后千林翠欲流，春馀高柳绿偏稠。","迁乔野外声初巧，求友枝间意独幽。","闭户不禁司马渴，出门堪并少陵游。","笙簧满耳听难尽，徙倚同消万斛愁。"]},{"t":"寄答张山人","f":"七言律诗","c":["何来双鲤傍江干，三径如同仲蔚看。","佩以蕙兰芳泽远，诗成珠玉夜光寒。","人从斗色知龙剑，君为鸥盟恋鹖冠。","愧我浪游虚岁月，东篱犹负落英餐。"]},{"t":"赈荒后为吴令公作","f":"七言律诗","c":["东南民力久堪怜，菜色何曾似近年。","老稚不禁途有殍，流离多是突无烟。","三城未下蠲租诏，十郡都烦劝赈钱。","此日孓遗方记忆，江头曾挽令公船。"]},{"t":"新兴姚明府封母","f":"七言律诗","c":["板舆亲奉出苕溪，三载分符粤岭西。","十郡循良推异等，孤城辽绝托卑栖。","霜含荐牍腾乌府，天动褒书下紫泥。","燕喜北堂歌寿母，忘忧今见集全褆。"]},{"t":"题瑞龟桥","f":"七言律诗","c":["百尺虹桥截海成，何劳驱石到东溟。","群游尽讶无天险，异迹还徵有地灵。","河上欢声齐万户，洛中馀瑞协千龄。","几人壮志能题柱，此地堪留驷马亭。"]},{"t":"赠康星士","f":"七言律诗","c":["百钱都市未全贫，华发飘飘白氎巾。","眼底乾坤堪玩世，壶中日月好藏身。","心从知命应逾彻，口到谈天类有神。","若向尘埃先物色，十年曾已识平津。"]},{"t":"晚泊","f":"七言律诗","c":["野人常占白鸥沙，今夕同舟对落霞。","鸿雁几声停客棹，蒹葭一水望仙槎。","风含露下炎蒸散，月拥潮平逸兴加。","何处鸣榔听不尽，推篷真乐在渔家。"]},{"t":"寿杨民部兼送寿卮","f":"七言律诗","c":["汉庭积贮念司农，粤社诗盟有国工。","客自歌狂休叹凤，人从慕弋不惊鸿。","黄花栗里初三径，丛桂淮南旧八公。","赠尔飞觞供载酒，问奇多过草玄雄。"]},{"t":"送金兵宪起复","f":"古风","c":["四海年来羽檄频，宵衣长念?兵臣。","松楸故里心难系，节钺中朝命转新。","庾岭梅花迎客旆，蓟门芳草驻征轮。","不知何地当除拜，到处苍生望紫宸。"]},{"t":"题邓氏孝友堂","f":"七言律诗","c":["风教从谁仰范模，义门今在凤山隅。","君陈本自心为政，公艺何须忍作图。","堂构功高人并美，棣兰色秀晚全敷。","由来召顺膺多福，试听斯干颂岂无。"]},{"t":"赠王别驾时署县有荐","f":"七言律诗","c":["才名共仰三川旧，治行咸推百粤先。","郡以分猷看展骥，邑缘试剧待烹鲜。","霜含白简俱称最，春满黄堂各颂贤。","珍重佩刀酬解赠，君家元沐主恩偏。"]},{"t":"陈司训膺奖","f":"七言律诗","c":["璧水谈经道已尊，霜台飞檄誉兼存。","苏湖教化新移俗，邹鲁诸生并在门。","桃李风前争自媚，鹍鹏霄际待齐骞。","讲堂喜报三鳣兆，何厌阑千苜蓿盘。"]},{"t":"挽易山人","f":"七言律诗","c":["冬来犹及寄双鱼，岂道翻成绝笔书。","壮志未能周五岳，残编谁为惜三馀。","岁寒祇自荒松径，龙卧何因叩草庐。","欲拟山阳思旧赋，不堪闻笛却愁予。"]},{"t":"送周方大读书清城兼寄朱少襄","f":"七言律诗","c":["家学濂溪逮紫阳，传经嗣业喜重光。","渊源道脉流俱远，伯仲交游意并长。","两岸莺花春气象，一江烟雨客衣裳。","主人旧约飞泉胜，乘兴因君思欲狂。"]},{"t":"王明府调任龙门","f":"七言律诗","c":["已看骑竹慰儿童，复有宣麻下汉宫。","飞舄未论天近远，分符宁限地西东。","讴歌渐起鸣琴外，悲怨翻传别调中。","何事山城偏借寇，萧条榛莽入春风。"]},{"t":"送方伯胡公入贺","f":"七言律诗","c":["福星才照粤江头，又报乘轺入帝州。","喜慰邦人新四岳，言修岁事古诸侯。","陈谟金鉴臣心展，咨牧纶麻上意优。","杼轴大东看若此，可因前箸动宸旒。"]},{"t":"送高正甫比部还朝时谳狱江北便道归省","f":"七言律诗","c":["白云仙吏下蓬莱，笑索扬州雪里梅。","作伴青春来昼锦，承欢綵服映霞杯。","琼枝乍见庭阶集，芳草翻从驿路催。","到处汀洲新绿满，喜供吟咏达金台。"]},{"t":"佘处士六十初度从子孝廉来索寿诗","f":"七言律诗","c":["江上春明二月初，东风吹绿满閒居。","鸟窥寿席歌相答，花映斑衣锦不如。","蜗角懒看尘俗态，蝇头翻阅少年书。","竹林小阮欢多洽，更喜潘园并导舆。"]},{"t":"赠张医官张家世淮阳其术兼明太素","f":"七言律诗","c":["淮南丹术旧称良，羡尔传为肘后方。","海上不须求大药，壶中已自胜长桑。","阴功岂但千人活，国手无容二竖藏。","察脉况知荣悴理，似闻七发尽飞扬。"]},{"t":"赵司教报满赵柳州人其门下杨生索诗为赠","f":"七言律诗","c":["十年曾记柳江湄，折柳樽前赠别离。","望远星高荀氏里，怀人春满谢家池。","鱼鸿异地风尘渺，桃李山城雨露私。","最喜弹冠将及代，鳣堂遗事总堪期。"]},{"t":"送何太学入京","f":"七言律诗","c":["秋到炎消海上天，新凉堪引孝廉船。","向来珠树依三秀，此去金茎待四迁。","藉藉才名芳水部，寥寥经术老菑川。","中朝自有山公在，姓字都从启里传。"]},{"t":"送何茂才游太学","f":"七言律诗","c":["握手秋江送画船，为君初赋远游篇。","三朝故事青箱习，千里轻蹄赤汗鲜。","翡翠明珠方贡越，黄金白璧重游燕。","京华到日思何逊，谁遣梅花笛里传。"]},{"t":"韶州谢使君考绩","f":"七言律诗","c":["江流曲抱九成台，冉冉芙蓉夹岸开。","山郭但逢廉叔晚，苍生终赖谢公才。","心劳雁泽荒为政，诗劝雌堂暇自裁。","报绩九重先赐玺，徵书还自日边来。"]},{"t":"送谢参军转赋二首 其一","f":"七言律诗","c":["财赋东南藉上供，梯航此日远相从。","亦知岁事穷檐苦，独喜春光帝里逢。","治粟功多秦内史，持筹心慰汉司农。","莲花幕下风流客，伫见贤声达九重。"]},{"t":"送谢参军转赋二首 其二","f":"七言律诗","c":["清才每喜分曹暇，王事都缘国计劳。","行里山程梅雪霁，望中亲舍岭云高。","四方民力随飞挽，此日宵衣念转漕。","待尔承恩辞阙下，鲲游应及赋秋涛。"]},{"t":"赠樵南隐居","f":"七言律诗","c":["七十峰前结近庐，考槃终日对清虚。","云边自种陶家秫，花下时翻邺架书。","白石岂须歌短褐，青山一任赋閒居。","飞腾已有天池翮，莫忆王门更曳裾。"]},{"t":"起复北上答友人寄赠二首 其一","f":"七言律诗","c":["柳色青青似渭城，翩翩文藻出西京。","閒居水石心难系，前路莺花春始明。","寸禄祗应随世用，尺书无奈别君情。","秋怀万里风云壮，彩笔还看起大名。"]},{"t":"起复北上答友人寄赠二首 其二","f":"七言律诗","c":["几载鱼鸿已杳然，椷书犹喜及行鞭。","碧云久自三城隔，玉树长从一水悬。","客舍偏能追往事，尘途应为感流年。","阶前六翮今何似，日向层霄拟共翩。"]},{"t":"人日三水舟中与两弟暨诸亲族言别","f":"七言律诗","c":["几度乘春入帝州，最逢春早是今游。","蓂开七叶同人日，水长三江自客舟。","笛里条风催折柳，尊前新雨谢盟鸥。","临岐预问重携手，消息还应待好秋。"]},{"t":"都门送赵明府之琼山","f":"七言律诗","c":["黄金台下忆琼台，万里须君保障哉。","栖棘南陲新凤羽，空群北冀旧龙媒。","琴鸣流水潮声入，剑拂清霜蜃气开。","观海不须愁望远，飞凫容易日边来。"]},{"t":"同郭宫允包廷尉登台望西山兼待夜观星感赋","f":"七言律诗","c":["杯酒同登望远亭，蓬莱下直辍谈经。","披襟爽气来千叠，入夜祥光拥万灵。","贯索分明联法象，紫微清切傍天庭。","孤臣十载称郎宿，此夕长安尚客星。"]},{"t":"出京阻雨由潞河登舟","f":"七言律诗","c":["积雨连城黯未收，冲泥何似问江舟。","膏车柳外回纡径，倚棹鸥边濯远流。","畏日却无三伏暑，雄风先送二仪秋。","刀头明月推篷见，散发披襟涤旅愁。"]},{"t":"清湖客舍","f":"七言律诗","c":["历尽炎蒸万里途，喜逢此地是清湖。","楼头纤月秋将半，天末凉风暑渐徂。","客路栖迟惭旅食，山家幽绝类仙都。","休论雁断音书渺，且傍寒灯浊酒壶。"]},{"t":"仙霞岭","f":"七言律诗","c":["穿云何处觅仙家，缥缈丹梯度赤霞。","曲涧尚鸣千瀑雨，幽厓常带四时花。","客留竹院多题壁，僧叩篮舆屡献茶。","最是尘游兼胜览，秋清况助物华赊。"]},{"t":"四望楼晚晀","f":"七言律诗","c":["群峰迤逦对凭阑，风物他乡醉里看。","出壑淡烟笼野色，过云疏雨送秋寒。","地分瓯越关山迥，天尽东南宇宙宽。","何必杖藜誇济胜，卧游吾已历千盘。"]},{"t":"次延津","f":"七言律诗","c":["曾向丰城傍玉壶，延津此日复停舻。","天边紫气疑明灭，波底玄灵讶有无。","佩自双钩莲锷歛，吹惟一吷斗文孤。","莫须神物终当化，珍重时看玉辘轳。"]},{"t":"初至长乐","f":"七言律诗","c":["长乐钟声谒帝游，今宵长乐是遐陬。","海滨何处非王土，吏牍劳人敢自愁。","西北战尘犹未息，东南民力总堪忧。","四方但幸长无扰，不怨天涯更滞留。"]},{"t":"送王君聘明府迁比部","f":"七言律诗","c":["秋风海上送秋曹，几载怜君抚字劳。","何必拾遗思汉汲，且看明允重虞皋。","白头慈母新纶檄，玄鬓仙郎旧佩刀。","若道爰书非得意，于门他日为谁高。"]},{"t":"送张孝廉春试","f":"七言律诗","c":["四方传檄未休兵，圣主临轩待请缨。","凤阙天开春信早，马江风静昼潮生。","骊歌渐逐停云远，剑气先看傍斗明。","此去登坛誇胜事，教人海上忆金茎。"]},{"t":"迎春","f":"七言律诗","c":["腊尽凝寒午未开，喜闻青帝隔年回。","争喧社鼓迎仙仗，共对春盘引客杯。","海上阳和应独早，人间岁月递相催。","亦知燮理非吾分，却拟年丰入颂来。"]},{"t":"和周文学守岁二首 其一","f":"七言律诗","c":["羁旅壶觞亦岁华，不知何处是天涯。","宜春綵帖新传胜，守岁椒盘更颂花。","剪烛似添更漏永，题诗偏动客怀赊。","知君恋阙情无限，每忆鸣珂谒帝家。"]},{"t":"和周文学守岁二首 其二","f":"七言律诗","c":["海内称诗富谢陶，中原鞭弭复吾曹。","鸿篇自愧才名后，彩笔谁干气象高。","改岁韶华增舜历，异乡交谊得周醪。","休怜客思多寥寂，次第春风入李桃。"]},{"t":"送练生还峡江并柬黎明府有引","f":"七言律诗","c":["海畔移家号义门，忠魂馀庆及闻孙。","此生自幸天无外，异地长怀江有源。","物色几年劳梦寐，奉尝千里托蘋蘩。","荒凉故宅成羁旅，推食犹凭地主恩。"]},{"t":"答赠少司马陈公二首 其一","f":"七言律诗","c":["百丈鳌山带紫霞，修真几度转河车。","抛书午倦惟看竹，操笔年来更梦花。","司马园开耆会胜，太丘门聚德星华。","安车会见来天上，欢舞还应遍万家。"]},{"t":"答赠少司马陈公二首 其二","f":"七言律诗","c":["东山岁月混烟霞，汉阙千秋待小车。","温室尚留当日树，玄都重看旧时花。","两朝经济推人杰，一代文章见国华。","共拟主恩思故剑，老成端不负皇家。"]},{"t":"祀汾阳王","f":"七言律诗","c":["曾是唐家社稷忠，南来庙貌喜俱隆。","藻蘩尚荐山间沚，舶趠能清海上风。","今古安危思国老，岁时伏腊感村翁。","衔恩自笑非前令，祗为民艰报祀崇。"]},{"t":"为宋黄勉斋先生竖坊兼立其裔孙奉祀答周文学二首 其一","f":"七言律诗","c":["想像遗踪五百年，溪山留胜尚依然。","一时厉禁浑无恙，万古斯文赖有缘。","仰止将兴闽绝学，景行端藉曾多贤。","讲堂况复馀光霁，桃李当春已自妍。"]},{"t":"为宋黄勉斋先生竖坊兼立其裔孙奉祀答周文学二首 其二","f":"七言律诗","c":["丛祠水石郁森森，闽海儒宗擅士林。","俎豆几人陪秩祀，衣冠千载续徽音。","奉尝不愧家声远，绳武应知世泽深。","可道厥修无念祖，须从此日惜分阴。"]},{"t":"谢节妇","f":"七言律诗","c":["相谈往事辄悲辛，气节闺闱孰与伦。","不作未亡伤吊影，宁甘一死伴栖神。","贞心尚抱重泉恨，荒冢曾经几度春。","使者采风能及远，幽冥端拟被恩新。"]},{"t":"林烈女","f":"七言律诗","c":["千年青史仗谁收，女行同推第一流。","百两未能宜尔室，九原何遽乐斯丘。","露零宿草悲鸳幔，风韵疏松忆凤楼。","此日表扬先郡邑，恩光还拟下皇州。"]},{"t":"大中丞陈公招饮鳌山别墅","f":"七言律诗","c":["东海何年化巨鳌，南山千仞对城高。","悬车密拥蓬三径，浮苇时航水一篙。","竹坞云来歌并遏，松厓风入酒俱涛。","初疑桂树能招隐，去后翻成倚醉逃。"]},{"t":"课诸生二首 其一","f":"七言律诗","c":["争将丽藻试新裁，笔下文光灿灿开。","奎聚似看联五曜，地灵端合应三台。","功成岂类屠龙技，赋就堪誇绣虎才。","从此年年瞻首石，一鸣一度报春魁。"]},{"t":"课诸生二首 其二","f":"七言律诗","c":["皇家此日大张罗，麟凤时看上苑过。","海内风云期并合，古来勋业与谁多。","连城价重归珍席，九陌花深待玉珂。","文运喜当全盛世，观风何地不菁莪。"]},{"t":"建朱文公祠崇祯堂","f":"七言律诗","c":["师友渊源聚乐时，于今俎豆复同祠。","儒林有传归青史，异世无阶迩绛帷。","千载图书留故业，一时堂构践遗基。","同来宇下频瞻拜，共仰清高作训彝。"]},{"t":"和擒倭志喜","f":"七言律诗","c":["赤羽频年急备倭，论功犹自藐山河。","鲸渊夜涉天无险，蜃阁晴嘘海亦波。","小丑未须烦武略，微劳先已动诗魔。","不知十万王师出，何日听君拟凯歌。"]},{"t":"送金友玙归龙溪","f":"七言律诗","c":["三十年前问蹇修，曾将名姓达荆州。","只缘卞璧初难遇，犹幸燕金晚见收。","当日挂冠人已远，此时倾盖义偏投。","于公门第多馀庆，看尔扶摇九万游。"]},{"t":"从张高二宪使阅视舟师","f":"七言律诗","c":["扬波无奈杞人忧，赖有材官据上游。","水寨当关雄虎豹，楼船截海壮貔貅。","衣袽实切中流戒，桑土能周未雨谋。","但得务农销战甲，免从烟水问戈矛。"]},{"t":"同诸生登紫阳阁","f":"七言律诗","c":["紫阳高阁枕山阿，纡径层厓长绿萝。","分得异莲疑玉井，飞来细瀑似银河。","境超下界尘俱寂，坐对南薰暑亦和。","何必学仙仍学佛，此中真乐已云多。"]},{"t":"和祷雨有应","f":"七言律诗","c":["枯厓草木未须怜，野老还称大有年。","此日方知霖济旱，小民依旧食为天。","瓯窭尽可登千亩，解阜齐看入五弦。","枕簟夜凉诗思好，传来清润见新篇。"]},{"t":"林左史惠荔枝兼以诗来和答","f":"七言律诗","c":["暑雨初晴日正东，枝头火实映云红。","筠笼解致琼浆美，笔札兼传雪调工。","海国林园推异品，旅人乡味忆芳丛。","投瓜尚乏琼瑶报，杯酒徒令怅未同。"]},{"t":"诞日答为寿者二首 其一","f":"七言律诗","c":["浪迹人间几十霜，茫茫苦海仗慈航。","难将墨绶为仙吏，却望红云隔玉皇。","岛净轻风含细柳，波恬旭日映扶桑。","但看圣化同天远，不厌尘中岁月长。"]},{"t":"诞日答为寿者二首 其二","f":"七言律诗","c":["壮气销来负镆干，许多心事寄毫端。","已知白社为初服，何得青门遂挂冠。","末路祗怀丛桂隐，秋风又美落英餐。","苍生此日需贤哲，惭愧东山有谢安。"]},{"t":"中秋夜宴集值天将雨","f":"七言律诗","c":["雨色微茫渐近城，今宵谁解卜阴晴。","冰轮未向云间现，暑气先从野外清。","密坐岂妨成四美，深杯那厌欲三更。","夜阑澄霁天如洗，依旧辉光万里生。"]},{"t":"得钱五卿书却寄","f":"七言律诗","c":["千里龟蒙壮大东，风流佐郡几人同。","过曹尚美心如结，颂鲁遥知乐在公。","斗畔双龙违未合，霜前一雁信能通。","君从海岱游偏胜，定有新诗慰转蓬。"]},{"t":"李明府迁居延平忆旧里春宵之景有作见怀赋此和答","f":"七言律诗","c":["千金何处买春宵，春事先从海国饶。","入夜笙歌清漏永，彻明灯火绿尊骄。","家声尔恋延平旧，斗色人看剑浦遥。","应是池塘飞梦远，双鱼传咏思飘飘。"]},{"t":"赠刘明府报绩","f":"七言律诗","c":["仙令才名藉豫章，栽花能自胜河阳。","邑饶耕凿淳风古，户有弦歌化日长。","百里上游推保障，三山驰誉遍循良。","采金见道烦中使，索骏应同入尚方。"]},{"t":"陈孝廉以司马公命来招赏牡丹赋谢二首 其一","f":"七言律诗","c":["海畔春光似洛阳，同来花下对花王。","锦如旧赐绯衣色，艳压重开绿野芳。","座上彩毫新制曲，尊前歌袂暗浮香。","更誇移植依琼树，不羡雕阑百宝装。"]},{"t":"陈孝廉以司马公命来招赏牡丹赋谢二首 其二","f":"七言律诗","c":["楼前韡萼号天香，手植何来雨露长。","对酒竞看春富贵，明膏犹共夜爃煌。","轻红谩映斑衣焕，浅白遥连玉树芳。","最是花光饶上苑，清平迟尔进君王。"]},{"t":"报绩答张孝廉","f":"七言律诗","c":["留滞天南祗自怜，寥寥山水入孤弦。","花从种处时开落，薪任积来有后前。","薄禄仅当才百里，微劳重上绩三年。","双凫浪说飞腾易，弱羽无因向日翩。"]},{"t":"陈廷尉封其父如己官","f":"七言律诗","c":["饰吏逡巡守一经，义方初录贲林扃。","于门及见齐容驷，荀里宁占但聚星。","野服不过求骏市，皇纶偏到狎鸥亭。","悬知教仕心逾切，自可移忠报帝庭。"]},{"t":"中秋夕喜霁呈司马公","f":"七言律诗","c":["昨宵风雨闭门时，何意秋澄会转奇。","晚日碧云宁但合，东山明月更堪期。","影飘桂树金波丽，尘净兰阶玉宇宜。","似为主人能爱客，西园乐事许追随。"]},{"t":"秋夜与友人对酌","f":"七言律诗","c":["江山何事苦相留，握手逢君慰倦游。","话旧且亲徐孺榻，思归休上仲宣楼。","月临对坐通宵昼，风洒酡颜满面秋。","怪是更阑人未寝，旅怀今夕不知愁。"]},{"t":"周文学再膺院奖","f":"七言律诗","c":["海上重逢骢马使，儒林声价羡君高。","横经久聚诸生乐，课绩宁论一字褒。","坛月穿云明散帙，官梅含雪照挥毫。","好文主圣看殊擢，造士功成合叙劳。"]},{"t":"寄蔡孝廉初上春官南还","f":"七言律诗","c":["去岁秋高海上天，九霄长翮竞腾骞。","明珠照乘初辞粤，神骏筑台已入燕。","阙下请缨孤仗剑，道旁饮马更投钱。","端明待制君家事，会有祥云奏殿前。"]},{"t":"送左司寇谢公还朝二首 其一","f":"七言律诗","c":["至后阳生春又旋，春光万里送朝天。","丹心渐向燕台近，紫气遥从汉殿悬。","行色远携沧海月，旅吟都附白云篇。","九重侧席今逾切，会见隆恩阙下传。"]},{"t":"送左司寇谢公还朝二首 其二","f":"七言律诗","c":["冬尽梅花海国饶，折来堪以赠行轺。","五云望阙殊知遇，三殿抡才岂寂寥。","春色漫随征旆入，主忧定向借筹消。","孤臣十载犹漂泊，开阁何时或见招。"]},{"t":"除夕守岁","f":"七言律诗","c":["徘徊不寐漏声残，漂泊天涯笑镆干。","凋鬓尚堪羁薄禄，远书长是慰加餐。","山川异地同为客，岁月明朝又履端。","今夜灯前对儿女，吟怀差胜昨年欢。"]},{"t":"拟酌游宗振于兰若公阻弗克承示对酒之作聊和其一","f":"七言律诗","c":["载酒重为问字来，翠微一径与谁开。","官因五斗频移棹，客傍双林独上台。","巧鸟若还呼对酌，飞花如解劝深杯。","江天夜月应同色，却负新诗两地裁。"]},{"t":"答罗秀卿武进","f":"七言律诗","c":["年来拊髀重推轮，羡尔恩从阙下新。","仗剑鹰扬当异域，借筹虎略已先人。","黄龙便拟寒毡酪，白雉还须款介鳞。","何日功成报天子，云台堪并汉勋臣。"]},{"t":"寄答陈公衡仪部时在忧中","f":"七言律诗","c":["岁月风尘可易逢，都门空忆旧游踪。","官仍抚字甘留滞，署有清华待秩宗。","海畔买邻千树隔，郢中传调八行封。","百年礼乐须今日，早别松楸向九重。"]},{"t":"送宗振归莆中二首 其一","f":"七言律诗","c":["漫游随处挟飞仙，更向禅林息万缘。","同调喜联交似水，卑栖愧羡翼垂天。","吟成或写忧时涕，施尽难馀买赋钱。","君岂负刍如越石，阳春无地不人怜。"]},{"t":"送宗振归莆中二首 其二","f":"七言律诗","c":["坐残山月耽玄静，听彻天风送步虚。","结客几能金比诺，傍禅堪證觉为如。","门留独客谁题凤，铗对狂歌岂羡鱼。","归去马卿仍四壁，箧中惟有异人书。"]},{"t":"闻岛夷遁归二首 其一","f":"七言律诗","c":["几载东征仗钺旄，忽闻候骑报追逃。","兵声自足寒群胆，师老何忧长二毛。","海外暂宽飞挽檄，军中齐看大环刀。","由来干舞夷能格，不信功惟汗马高。"]},{"t":"闻岛夷遁归二首 其二","f":"七言律诗","c":["如林虎旅训逾精，环海多开骠骑营。","选战锋前俱列寨，受降城下渐连甍。","攻心自昔谋为上，清野于今策已成。","最是君王神且武，远人先尽慑威名。"]},{"t":"答周方大二首 其一","f":"七言律诗","c":["造物由来总未公，世间暌合几能同。","惭余客舍琴虚在，怪尔王门瑟自工。","鸿雁影传书近远，斗牛光射剑雌雄。","亦知风月馀光霁，笑语何时得再逢。"]},{"t":"答周方大二首 其二","f":"七言律诗","c":["大海难从一苇航，粤闽迢递隔他乡。","漂零似我甘留滞，疏逖凭谁识茂良。","十载游从堪记忆，几年兵眚益荒凉。","青山白石元无恙，不得同君共举觞。"]},{"t":"王百谷为余序谈诗类要赋此寄谢","f":"七言律诗","c":["箧笥犹存旧寄诗，品题何意复吾私。","玄言并入临池兴，彩笔兼传幼妇词。","羲献风流元代美，邹枚儒雅总堪师。","可能便舣吴门棹，载酒从君更问奇。"]},{"t":"元夕司马陈公宅观灯答和二首 其一","f":"七言律诗","c":["雨后条风扇海濆，三阳芳景属平分。","尊仍柏叶招游骑，阁引藜光照论文。","五曜迥连当户月，九华交映隔山云。","同歌玉树春无限，耆社何当意独勤。"]},{"t":"元夕司马陈公宅观灯答和二首 其二","f":"七言律诗","c":["五夜徵歌四座哗，今宵投辖会偏嘉。","漫同星聚陈丘里，不数风流白傅家。","坐似斗间乘贯月，杯如天上酌流霞。","安车会有询幽侧，应共宸游扈翠华。"]},{"t":"赵仁甫由梁山令量移池州别驾","f":"七言律诗","c":["匹马翩翩自蜀回，依然犹共鹤琴来。","倚门白发斑衣在，拂袖红尘笑口开。","万里听猿经栈道，几时图骏傍金台。","量移敢谓恩犹薄，似解怜君展骥才。"]},{"t":"复儿生答诸贺者四首 其一","f":"七言律诗","c":["至后梅梢点雪清，阳回花萼接春荣。","徵兰有梦祥初协，种玉何缘事若成。","喜附一星荀里聚，敢云枝桂郤林生。","多君雅意相期许，帝籍还看爰锡名。"]},{"t":"复儿生答诸贺者四首 其二","f":"七言律诗","c":["月照悬弧旅夜明，书云况属礼初成。","庭阶暖向春前入，海国阳从至后生。","馀庆几人推令子，季方何日见难兄。","箕裘直羡君家远，岂拟燕山桂树荣。"]},{"t":"复儿生答诸贺者四首 其三","f":"七言律诗","c":["海色寒馀渐向阳，官梅香并佩兰香。","握中玉似蓝田秀，掌上珠疑合浦光。","未卜他年为凤羽，欣占此日是熊祥。","承君为奏将雏曲，彩笔何如错弄獐。"]},{"t":"复儿生答诸贺者四首 其四","f":"七言律诗","c":["传来秀句不辞频，又枉瑶篇纪送麟。","间世敢当王者瑞，应时先毓海之春。","驹能千里名方大，璧是连城价始珍。","若比汉臣多活狱，里门将亦许重新。"]},{"t":"答康孟担寄赠四首 其一","f":"七言律诗","c":["逢人高士说南州，尚有诗篇阻唱酬。","司马不须徒慕蔺，仲宣何用更依刘。","观风独美閒居赋，对月时登近水楼。","花下政馀无一事，远烦书札话千秋。"]},{"t":"答康孟担寄赠四首 其二","f":"七言律诗","c":["窗外禽声竟日闻，午晴花气送馀芬。","久随波荡为孤客，拟遣穷愁咏五君。","旧侣几逢千里驾，他乡长梦故山云。","何当谢却浮名累，挥麈谈诗到日曛。"]},{"t":"答康孟担寄赠四首 其三","f":"七言律诗","c":["一片閒云去住频，随风出岫到瓯闽。","漂零寓目愁羁旅，迟暮伤心为美人。","园静止堪窥竹素，公馀端合对花神。","由来傲吏能兼隐，往事何知问积薪。"]},{"t":"答康孟担寄赠四首 其四","f":"七言律诗","c":["回首人间万态空，独留山水寄丝桐。","尘途扰扰思前日，海国泱泱见大风。","车马未成今雨约，烟霞惟慕小山丛。","中朝若更求岩穴，召对还应集汉宫。"]},{"t":"寄屠纬真仪部","f":"七言律诗","c":["兰省当年近国光，逢君徵拜正含香。","黄金入市惊龙种，白雪登坛渺雁行。","彭泽未归元亮隐，鉴湖先遂季真狂。","瑶篇示我过玄晏，何必三都重洛阳。"]},{"t":"送陈仁甫归豫章二首 其一","f":"七言律诗","c":["片帆千里下无诸，僻地淹留忽月馀。","花县对怜潘令鬓，锦囊潜带邺侯书。","一庭兰玉浑相似，十日壶觞迥不如。","快睹凤毛长五色，何年天上送吹嘘。"]},{"t":"送陈仁甫归豫章二首 其二","f":"七言律诗","c":["喜伴春来笑语温，一腔心事颇同论。","逢迎昔幸登徐榻，容接何当道李门。","累叶象贤堪继武，几人国士未酬恩。","由来世泽中朝远，迟尔飞腾并帝阍。"]},{"t":"夜宿梅花城","f":"七言律诗","c":["两度寻梅未着花，孤城僻绝海之涯。","鲛人并列横江戍，岛客能乘上汉槎。","官阁夜声潮撼急，女墙秋色月临斜。","由来保障称兹土，喜颂升平彻万家。"]},{"t":"答游宗振时闻有松江之行","f":"七言律诗","c":["一从绾绶出枫宸，十载焦劳任积薪。","见尔昂藏知国士，怜余飘泊滞孤臣。","方看赵邸归长铗，又向吴江忆细鳞。","闻道云间推二陆，此行端称和歌人。"]},{"t":"答罗太学","f":"七言律诗","c":["海月当空岛雾消，片心难忘故山樵。","远书漫劝加餐食，高咏堪凭慰寂寥。","云树岭边思共渺，露茎天外望俱遥。","已闻历国骅骝去，喜见轻蹄逐电骄。"]},{"t":"得崔子玉书并诗赋答","f":"七言律诗","c":["客梦迥悬南海月，乡心故恋北山薇。","鹏程建翮看今始，鸟道长鸣笑昨非。","多难况逢需用切，壮怀休道宦情微。","风尘我亦仍留滞，何日重逢上路騑。"]},{"t":"答熊楚伯","f":"七言律诗","c":["粤社诗盟见汝才，碧云千里梦初回。","山中旧业依丛桂，海畔春阴怅落梅。","闻道赋缘招隐就，似怜人尚折腰来。","何时得共餐霞侣，涧月岩花照举杯。"]},{"t":"答季弟少得","f":"七言律诗","c":["千里缄书问远离，海云僻绝路逶迤。","池塘别后春何似，松菊荒来梦所思。","短鬓渐彫辉萼色，旅愁翻剧及瓜时。","祇应雁序联翩起，傍我东篱浊酒卮。"]},{"t":"答游山人初春在吴门见怀三首 其一","f":"七言律诗","c":["异地羁愁已渐分，春来花鸟自堪群。","朋游祗恨同声远，消息徒劳隔岁闻。","王月漫赓椒里颂，客星仍傍海东云。","山川吴越俱形胜，芳草王孙却为君。"]},{"t":"答游山人初春在吴门见怀三首 其二","f":"七言律诗","c":["春烟染绿渐盈条，莺语花容次第娇。","客里风尘淹日月，天涯书札问渔樵。","一官自笑头颅改，双阙长悬道路遥。","十八年来虚梦想，还如汉节未归朝。"]},{"t":"答游山人初春在吴门见怀三首 其三","f":"七言律诗","c":["蓬莱宫阙望逾高，吏牍无须叹久劳。","燕市自应求騄駬，凉州何用致葡萄。","新诗念我能贻远，佳句怜君半入骚。","乘兴马江仍进棹，看潮不及广陵涛。"]},{"t":"五日同诸公观竞渡二首 其一","f":"七言律诗","c":["三年海上笑栖迟，又到壶觞五月时。","竞渡闾阎还楚俗，并游儒雅总吾师。","光添舞袖辟兵綵，红映酡颜续命丝。","岁稔民间饶乐事，临流卮酒未应辞。"]},{"t":"五日同诸公观竞渡二首 其二","f":"七言律诗","c":["天留霁色傍江开，画舸轻桡叠鼓催。","渔父不知吟泽恨，楼船堪并济汾来。","风含兰气宜新浴，霞带蒲香入旧醅。","傍晚榜歌听互答，舟前争道锦标回。"]},{"t":"莆阳林生以诗来贽赋答二首 其一","f":"七言律诗","c":["愧乏雄文惊海内，嗟因拙宦滞天涯。","金茎望外长怀国，绿绮声中自放衙。","公暇挥毫情稍惬，远来倾盖义偏嘉。","壮游未藉雕虫末，况已新篇丽彩霞。"]},{"t":"莆阳林生以诗来贽赋答二首 其二","f":"七言律诗","c":["海畔栖迟似隐沦，旅怀相慰转情亲。","盐车渐逐泥涂老，金市遥看岁月新。","久客关山怜落魄，淡交风味见吾真。","玄言若就当谁识，门下侯芭有几人。"]},{"t":"恭遇平倭颁诏答石参藩","f":"七言律诗","c":["几年飞挽佐东征，凯奏才闻入帝城。","岛屿鲸鲵千浪息，丝纶日月万方明。","休誇校猎长杨馆，但听铙歌细柳营。","不是舞干能格远，勋名谁解动公卿。"]},{"t":"答赵仁甫秋日见怀","f":"七言律诗","c":["公馀一榻为南州，乘兴谁堪并子猷。","混迹久甘牛马应，神交偏忆凤鸾俦。","栖迟尔傍山中社，摇落余怜海上秋。","试问东篱餐菊后，几人邀月共登楼。"]},{"t":"答大宗伯陈公二首 其一","f":"七言律诗","c":["西风摇落海门寒，到处闾阎有怨叹。","北阙此时应侧席，东山何日更弹冠。","词人屡款南州榻，艺苑先登赤帜坛。","多少儒生开阁望，芳洲无用忆秋兰。"]},{"t":"答大宗伯陈公二首 其二","f":"七言律诗","c":["秋声几夕雁来初，爽气全临水竹居。","文自吐馀皆五凤，书从断后更双鱼。","相期召对还金马，未许渔樵老孟诸。","可奈怀人葭露远，暮云搔首意何如。"]},{"t":"答康孟担留别","f":"七言律诗","c":["别后怀人水一方，归来宁似客衣裳。","江山异地曾留赋，花木还家渐向阳。","鞭弭代兴盟有主，风尘游倦思偏长。","同声海内如君几，谁许诗名附雁行。"]},{"t":"答佘宗汉明府二首 其一","f":"七言律诗","c":["喜见双凫下赤霄，夜凉孤月挂山腰。","游馀五岳来禽庆，腹有群书羡孝标。","短棹风涛曾遍阅，初衣尘壒已全消。","浮云万态皆苍狗，何处名山不可樵。"]},{"t":"答佘宗汉明府二首 其二","f":"七言律诗","c":["早辞荣禄傲烟霞，到处禅林伴法华。","彭泽已繁新种柳，河阳犹记旧栽花。","云晴对客山中月，秋至怀人水上葭。","何必勋名俱竹帛，桐江千古重皇家。"]},{"t":"答陈生心文","f":"七言律诗","c":["遇合从今却未迟，暗投当日不须悲。","冲牛夜色依然紫，问马天机竟是骊。","莲锷渐看出匣后，霜蹄还待过都时。","槐黄转盻秋期近，念我宁惭报玖诗。"]},{"t":"答林有本先生","f":"七言律诗","c":["当年携伴醉玄都，何似辞荣傲海隅。","酒熟持觞狎花鸟，月明摇棹出菰蒲。","烽烟东北犹传檄，刍粟西南更援桴。","羡尔彩毫舒物外，看山长日混樵苏。"]},{"t":"寄吴懋中明府时将上计","f":"七言律诗","c":["紫气腾陵望七峰，史溪南下剑成龙。","三年单父琴为政，百里河阳花是封。","过雉桑间仍抚字，飞凫云外又朝宗。","明堂自合优循吏，况已贤声达九重。"]},{"t":"送吴观可孝廉春试","f":"七言律诗","c":["早岁词场起大名，衣冠乡里慕同声。","处囊特擅三千客，抱璧终偿十五城。","亭馆山间辞问字，风云阙下会登瀛。","汉家侍从须文学，岂羡河南继治平。"]},{"t":"中秋月下饯别张道相孝廉春试","f":"七言律诗","c":["三年海上见中秋，月下今宵壮远游。","客路风清闽岭外，帝城春在曲江头。","二京赋就谁争美，三殿名高自胜流。","处处飞书新偃武，修文天子坐垂旒。"]},{"t":"初冬有事武闱登三山南楼眺望","f":"七言律诗","c":["一上层楼寓目宽，南中十月只轻寒。","千山雨过林仍绿，万木霜催叶未丹。","骑射此时资讲武，蒐罗他日备登坛。","汉家颇牧频推毂，须信封侯事不难。"]},{"t":"答温陵蔡生","f":"七言律诗","c":["名家宋殿旧端明，新见长杨重墨卿。","世业共推良冶子，英年人道弃繻生。","风前翮拟鹏将起，池上毛看凤早鸣。","司命君侯谁者是，漫劳相慕比韩荆。"]},{"t":"春日答周文学时同事有中伤者","f":"七言律诗","c":["淑气将春海上回，鱼龙蛰欲启风雷。","花明綵胜增王月，菜引青丝滞客杯。","万里关山天畔隔，几时消息日边来。","明年聚会应难拟，何处怀人寄折梅。"]},{"t":"答大中丞陈公二首 其一","f":"七言律诗","c":["结庐将傍白云隈，莫记尘游岁屡回。","谁为阳城更下考，祗应彭泽赋归来。","山中猿鹤休多怨，沙上凫鸥岂浪猜。","三径久荒违二仲，清尊花下拟重开。"]},{"t":"答大中丞陈公二首 其二","f":"七言律诗","c":["当春愁绪转难裁，卜夜空怀旧雨来。","世事岂须疑按剑，人情只合付深杯。","渔樵别有烟霞约，泉石应无燕雀猜。","归去五湖春水绿，捲纶犹及百花开。"]},{"t":"答康孟担","f":"七言律诗","c":["忆昨相逢笑语温，那知此别正销魂。","低眉自悔腰恒折，缄口宁誇舌尚存。","思过未开延寿阁，离群将署翟公门。","远书谩带烟霞色，始信山林道愈尊。"]},{"t":"答周吴华","f":"七言律诗","c":["宦情难自卜升沉，堪笑当年拟断金。","有约渔樵归旧隐，不言桃李任成阴。","沧洲久矣应吾道，流水依然待赏音。","留得海门千顷月，为余长照故人心。"]},{"t":"郑生善仪索赠赋此留别","f":"七言律诗","c":["谢家兰玉异恒儿，何必逢人说项斯。","世泽尚传通德里，文名初起论材时。","漫称小友惭吾长，敢说君侯命所司。","此别春风自桃李，早看雨露发华滋。"]},{"t":"答陈参知","f":"七言律诗","c":["绿杨垂荫草初芳，作伴青春去路长。","飞梦已悬招隐桂，离情多赠合欢棠。","归心正喜随单骑，晚食何须及万羊。","伏枥壮心销欲尽，不缘知己强为良。"]},{"t":"次洪塘别诸生","f":"七言律诗","c":["郭外波声涌暮潮，萋萋春草别魂销。","蛾眉老去甘沦落，龙性驯来转寂寥。","蓬转岂须违五柳，翮成终合待层霄。","临岐未洒穷途泪，握手应知愿不遥。"]},{"t":"答右司马陈公四首 其一","f":"七言律诗","c":["悠悠世事未全非，祖道都门亦共辉。","负俗知难投众好，解嘲惭已入危机。","由来傲吏山林癖，不记长途心事违。","却任浮云自舒卷，欲专丘壑遂初衣。"]},{"t":"答右司马陈公四首 其二","f":"七言律诗","c":["梁鸿曾赋五噫歌，司马青衫泪亦多。","一入利名皆苦海，元无生灭是恒河。","田家雨足宜粳秫，洞户风轻长薜萝。","莫说王孙归未得，祗将离绪付春波。"]},{"t":"答右司马陈公四首 其三","f":"七言律诗","c":["久客风尘徒自苦，馀寒灰律仗谁吹。","耕仍谷口应归去，花在河阳有别离。","敢拟诗留南国颂，莫须文勒北山移。","他时两地长怀处，云树苍苍大海涯。"]},{"t":"答右司马陈公四首 其四","f":"七言律诗","c":["滔滔江水日流东，得失无劳问塞翁。","归处柳应陶径合，积时薪比汉家同。","小山漫结词人社，大国难闻作者风。","客梦几宵犹绿野，满庭兰玉露华中。"]},{"t":"答清源林生","f":"七言律诗","c":["留良千里未空群，抱璧多年几献君。","暂映燃藜山寺月，相随蹑屩海天云。","荒斋夜静孤钟歇，远浦潮来一雁闻。","即道临邛饶赋客，教人偏诵马卿文。"]},{"t":"秋夕同宗汉宗振小集","f":"七言律诗","c":["客舍初停问月杯，更逢孤棹剡溪来。","南州未倦延高士，北海还堪集上才。","陶谢游同诗思好，荀陈德聚旅怀开。","尊前莫拟悲秋赋，此夕俱无庾信哀。"]},{"t":"送林参知先生入贺","f":"七言律诗","c":["南粤瞻天万里遥，五云深处导星轺。","廿年久隔鹓鸿侣，双阙重趋玉帛朝。","鉴拟千秋承帝眷，乐闻九奏会仙韶。","礼成召对应询瘼，三祝馀情更愿尧。"]},{"t":"夏日过王光禄飞云洞宴集","f":"七言律诗","c":["十亩烟霞覆短墙，中开三径引求羊。","琴尊自美谈玄宅，宾从时过醉白堂。","台倚高云临大野，池通新水着浮航。","当朝若更徵岩穴，未许林园混酒狂。"]},{"t":"送郭太学","f":"七言律诗","c":["槐市秋清集俊髦，壮游堪逐五陵豪。","初开道路驹千里，争睹云霄凤一毛。","都讲席看随上序，进贤冠羡映东曹。","筑台况是君家事，此去悬金价并高。"]},{"t":"李观察父叔齐封","f":"七言律诗","c":["天书齐下紫泥封，海日烟消花影重。","父叔崔门今两凤，弟昆许里旧双龙。","埙篪并美千秋业，杖屦仍同五岳踪。","增秩岁逢新命至，承恩次第兴俱浓。"]},{"t":"磻溪图","f":"七言律诗","c":["一溪聊以遂吾安，溪上乾坤亦自宽。","潦尽微澜清鹤渚，月明香雾湿鱼竿。","林塘兴洽扁舟雨，鸥鹭机閒几里滩。","筋力百年殊健在，后车宁作众人看。"]},{"t":"送朱少襄入京","f":"七言律诗","c":["山中十载满瑶篇，此去邮程羡着鞭。","自许骅骝轻远道，暂令猿鹤怨飞泉。","凉生弭棹秋如水，兴溢停觞笔似椽。","不为观光行上国，赋成谁解识青钱。"]},{"t":"送康孟担归莆中","f":"七言律诗","c":["天涯归思近何如，几夜秋声入客居。","书断故人惟有雁，歌残长铗尚无鱼。","盟从旧社还真率，赋岂同时负子虚。","烟水木兰堪进棹，怀余尺素未应疏。"]},{"t":"送薛侯宣民部出守南宁","f":"七言律诗","c":["几载频烦领度支，主恩南顾念荒疲。","朱幡夹道来千骑，竹马临江导两麾。","入境可知凰并集，分岐徒羡鹤相随。","与君握手揶揄外，多少心期付所知。"]},{"t":"送董崇相博士之任南雍","f":"七言律诗","c":["衣冠江左集群英，南浦仙槎壮远行。","作吏风尘归上国，得师文学擅西京。","菁莪载育周多士，礼乐宁惭鲁两生。","诏下石渠先论易，好陈交泰弼承明。"]},{"t":"送金友珙之罗浮便谒刘使君友珙先有作见贻","f":"七言律诗","c":["千里逢君过草堂，依刘何地系轻航。","寒梅远望罗浮色，明月先投合浦光。","道路霜威悬马首，江湖星象映鱼肠。","山居寂寞无酬答，却写离怀付短章。"]},{"t":"答蔡孝廉时春试后南还","f":"七言律诗","c":["谁从鳞羽识虬鸾，喜尔翩翩汉魏坛。","北望太行悲远道，南来禹穴得奇观。","里中白雪歌弥寡，天上繁星色正寒。","愧我并驱时已暮，新诗宁合更传看。"]},{"t":"黄贞妇","f":"七言律诗","c":["吊影空堂夜寂寥，夫君魂杳妾魂销。","结缡转恨乖违早，垂髡宁知岁月遥。","使者采风旌独行，乡人评旦颂高标。","他时嗣述应无负，更拟恩光下圣朝。"]},{"t":"题龙起卷送何贡士","f":"七言律诗","c":["天尽东南大壑宽，伏龙深处水云寒。","一朝雷动初开蛰，万里风长更助澜。","头角久应为物睹，飞腾宁复限泥蟠。","层霄有路知无极，霖雨他年合并看。"]},{"t":"送佘参知分署罗定","f":"七言律诗","c":["为语攀辕减别愁，使星仍照粤江头。","棠连千里河同润，薇对三城地旧游。","百雉重关新保障，万山过雨足瓯窭。","已知凤下人争睹，旋听将雏兴自悠。"]},{"t":"答郑纬文司理","f":"七言律诗","c":["雀罗幽寂掩柴荆，祗许求羊狎旧盟。","独鹤九皋千里梦，冥鸿两地尺书情。","篇诗已幸分玄草，杯酒何由对落英。","世事浮沉君自见，息机羡尔早遗荣。"]},{"t":"送谭永明山人之康州时以州乘应沈使君之辟","f":"七言律诗","c":["旅游何地不逍遥，自爱云林隔市朝。","刺灭独存狐史笔，路难宁羡马卿桥。","古文鸟迹谙奇字，方椠蝇头记里谣。","见说郡斋悬榻久，可无高士应嘉招。"]},{"t":"寄怀沈使君二首 其一","f":"七言律诗","c":["千里牂牁溯上游，从前彫弊说西州。","偶随一鹤来炎徼，却望三龙识沈侯。","兴革备闻经画远，江山聊与颂声留。","即论治行东南遍，谁擅专城第一流。"]},{"t":"寄怀沈使君二首 其二","f":"七言律诗","c":["息交岑寂守茅庐，五马犹能问索居。","穷巷闭门积雨后，焚香开卷落花馀。","循良十郡仍高等，蹇拙当年但属车。","杯酒别来频望远，几回梁月夜窗虚。"]},{"t":"寿黄别驾","f":"七言律诗","c":["天开耆社寿为朋，洛下衣冠岁月增。","有禄岂须过邴曼，何侯不可傲东陵。","苍松翠竹多相伴，白马青袍莫记曾。","况是庆馀堪万石，凤毛应早见骞腾。"]},{"t":"倪明府考绩","f":"七言律诗","c":["保障东南佐治安，汉家儒雅得倪宽。","琴前星入同单父，花下风来似灌坛。","异等循良推岭外，清班献纳待朝端。","比年侍从多虚席，即拟徵书付紫鸾。"]},{"t":"曾泽卿侍御以东宫覃恩封其父如己官","f":"七言律诗","c":["四百峰头旧结庐，承恩初下紫泥书。","尊传白兽添春酒，驾引青牛易鹭车。","桓典已闻推避马，于公能自应高闾。","祥光夜夜瞻南极，总是前星映彩馀。"]},{"t":"郊居小集言怀","f":"七言律诗","c":["廿载驱驰道路难，且因泉石息风湍。","杯前日月真怀土，镜里星霜合弃官。","生事菟裘宁厌薄，畏途滟滪不堪看。","人间大有安閒地，曾见红尘上钓竿。"]},{"t":"飞云洞饯别林别驾之槜李兼呈车使君","f":"七言律诗","c":["吴越山川纪胜游，屏星远道接清秋。","邑缘课最荣增秩，郡以抡材裕借筹。","展骥途看千里逸，飞云觞为片时留。","雌堂到日应知己，共赋登高月满楼。"]},{"t":"飞云洞兰有并蒂之瑞各赋一章","f":"七言律诗","c":["胜苑名花几向阳，喜看兰蕙有奇芳。","连枝已讶栽培异，并蒂均誇雨露长。","丛转光风双毓瑞，阶联玉树两呈祥。","非缘并结宜男佩，定许重沾上国香。"]},{"t":"送袁仲子赴阙","f":"七言律诗","c":["海日初腾雾欲消，似闻鲲运向层霄。","图南羽翼三山动，直北风云万里遥。","伯仲交游天下士，词章出入圣明朝。","凤池旧侣今应在，赋雪吟春并可招。"]},{"t":"寻五先生南园旧社答谭子玄","f":"七言律诗","c":["一代词盟旧结庐，名山何地更藏书。","空留野露沾荆棘，无复残篇落蠹鱼。","忆共买邻嗟世远，翻从凿壁爱光馀。","谁令故宅更新主，萧瑟西风独怆予。"]},{"t":"为陈勋卿题龙津藕花庄瑞莲","f":"七言律诗","c":["灼灼芙蕖澹澹风，龙津毓瑞到芳丛。","孤标秀引澄湖绿，双萼辉迎晓日红。","倚槛并怜娇欲语，淩波齐讶步逾工。","閒居未尽濂溪爱，更有天香待汉宫。"]},{"t":"十三夜同康孟担熊楚伯刘觐国周方大谭子玄梁宪父待月得章字","f":"七言律诗","c":["落月常悬照屋梁，何期此夕共清光。","已欣陶谢多奇思，况遇羊何有和章。","残暑尽随挥麈却，高谈偏助引杯长。","良宵几值秋将半，欲送柴门夜未央。"]},{"t":"送梁左史还周藩","f":"七言律诗","c":["家传相业旧青箱，海内今推马季常。","凤沼握兰辞直阙，兔园修竹羡游梁。","名因授简称方外，心为长裾别故乡。","到日醴尊承眷问，好陈乐善答君王。"]},{"t":"送康孟担西游访其叔郡丞","f":"七言律诗","c":["千里竹林几梦寻，西行此日惬尘襟。","孤舟夜泊风前笛，两岸秋声月下砧。","雾宿山光时隐现，岚飞野色半晴阴。","柳江若过曾游地，应笑当年种柳心。"]},{"t":"答陈子成秋夕见怀二首 其一","f":"七言律诗","c":["西风摇落正悲秋，月下听鸿独上楼。","宾馆尚悬徐孺榻，仙踪谁并李膺舟。","解传鹦鹉惊人赋，未爱鹔鹴贳酒裘。","乘兴若来应共醉，何须还棹剡溪头。"]},{"t":"答陈子成秋夕见怀二首 其二","f":"七言律诗","c":["草堂幽寂枉瑶篇，何处尊开白雁前。","异地长怀人似玉，良宵几待月初弦。","了无奇字堪相问，莫把新诗更与传。","鞭弭中原看此日，预期金石为君镌。"]},{"t":"秋暮陪沈郡公再登陈勋卿逍遥楼宴集","f":"七言律诗","c":["五马郊原问俗行，登台秋色倍澄清。","倒听木叶穿林下，坐见烟光抱郭平。","帘捲西山霞未落，窗衔东海月初生。","不缘光禄如渑酒，飞盖何由并两旌。"]},{"t":"陈孝廉父以七十犹守诸生其年家子来索寿章","f":"七言律诗","c":["经术传家旧有声，贤星久重太丘名。","斑衣擢桂香先染，彩笔占花念未更。","兰树阶庭偏美色，菊萸篱落好餐英。","三朝容鬓安车日，岂逐终童更请缨。"]},{"t":"答郑介繁二首 其一","f":"七言律诗","c":["忆昔河梁欲别时，魂销春草咏君诗。","风尘墨绶思何补，山水朱弦负所知。","吴下吕蒙惊见异，洛中张翰惜归迟。","巡檐正值梅堪索，乘兴奚囊好复随。"]},{"t":"答郑介繁二首 其二","f":"七言律诗","c":["虚堂阒寂掩蒿莱，对酒新诗每独裁。","心逐冥鸿宜客傲，赋从倚马识君才。","几回并就停云句，何似同倾问月杯。","霜菊向残犹未落，东篱迟尔共徘徊。"]},{"t":"许处士双寿","f":"七言律诗","c":["何处门庭道气赊，修真曾羡许君家。","鸡鸣并戒神逾王，鹤算齐占鬓有华。","五月桃疑千岁实，三江云似十洲霞。","他年使者求颜阖，双白承恩到海涯。"]},{"t":"惠州何使君考绩二首 其一","f":"七言律诗","c":["侍直从容忆往年，一麾犹荷主恩偏。","名留青琐来何暮，阁近朱明地是仙。","问俗海邦安抚字，奏成天阙重旬宣。","君王念旧应无已，会有徵书自日边。"]},{"t":"惠州何使君考绩二首 其二","f":"七言律诗","c":["悠悠世事卜行藏，推毂同君荷郑庄。","异地一隅甘守黑，东方千骑称怀黄。","河流并许沾馀润，里巷宁云汔小康。","绩奏治平推第一，汉家公辅待循良。"]},{"t":"寿王令公","f":"七言律诗","c":["官阁梅花渐报春，康谣兼颂岳生申。","几年栖凤留炎徼，万里飞凫候紫宸。","天阙五云连画省，汉家三馆重平津。","他时湛露沾清宴，此日壶觞念远人。"]},{"t":"答友人促余北上","f":"七言律诗","c":["纵横车骑奕棋看，几向羊肠叹路难。","不为雀罗妨下榻，更随鸥队狎持竿。","青衫往事白司马，皂帽今时管幼安。","一出又惊尘梦远，可容年少问南冠。"]},{"t":"贺梁幼宁明府生子","f":"七言律诗","c":["何处东篱酒兴宽，三城嘉瑞报徵兰。","升从匹练空中见，照彻明珠掌上看。","龙凤岂难追往牒，箕裘应解接儒冠。","不缘高士重为颂，须道出关胜伯鸾。"]},{"t":"答族侄广生","f":"七言律诗","c":["九天鹏翮看扶摇，镜里朱颜总易彫。","春草池塘思渐远，乌衣门巷聚非遥。","倦还鸟雀投林早，争起鱼龙挟雨骄。","期尔雄文终遇合，予将白社息烦嚣。"]},{"t":"为梁丈人送其婿黎君游太学时伯子方在计偕","f":"七言律诗","c":["紫云长护丈人峰，早识延明快似龙。","几载菁莪歌乐泮，百年礼乐待临雍。","行看诏下优三老，更拟书成上九重。","指日公车同召对，泥金双达八行封。"]},{"t":"萱芝齐茂图为周生寿其外祖母","f":"七言律诗","c":["宅相曾期应外家，且因喜燕进流霞。","紫鸾诏待辉双翟，青鸟书传集六珈。","萱号忘忧金作草，芝看联秀玉为花。","由来圣善堪多祉，庆溢潘园未有涯。"]},{"t":"寄题道州月岩和钱使君","f":"七言律诗","c":["空山圆月挂岩阿，光霁由来此地多。","近水楼台开宝镜，广寒宫阙傍银河。","乌啼绕树疏星晓，兔魄当杯浊酒歌。","坐久天香云外落，玉笙几度醉嫦娥。"]},{"t":"穆令公首荐","f":"七言律诗","c":["海隅苍赤颂神君，抚字功高帝亦闻。","栖棘岂妨同览德，过都元易识空群。","皂囊故启朝端誉，白简宁私柱后文。","虚席此时需召对，郎星天畔带祥氛。"]},{"t":"王倩泠自四明来访将由罗浮历武夷至雁荡而归武林赋此为别","f":"七言律诗","c":["雪夜扁舟过子猷，偶因并合散穷愁。","鉴湖月色辞乡远，粤岭梅花伴客留。","春酒碧霞瑶石酌，岩茶新雨幔亭游。","永嘉山水应无尽，早向钱塘及好秋。"]},{"t":"夜雨偶成和邓玑伯刺史","f":"七言律诗","c":["谁遣閒愁到酒边，感时触事意相牵。","计缘衣食家为累，梦落风波道苦邅。","孤坐有怀徒耿耿，忧心无地不悁悁。","夜来甘雨应沾足，且为三农庆有年。"]},{"t":"祖德诗为姚司理作","f":"七言律诗","c":["东南佐郡有贤声，世德曾高旧旦评。","黄绶海邦称惠尉，青云法从字升卿。","官缘一命馀家庆，秩拟三旌荷国荣。","大父交知同记忆，相才先习二郎名。"]},{"t":"袁参知入贺","f":"七言律诗","c":["凤历才过三十春，瞻天此日庆逾新。","车驱万里趋王会，鉴拟千秋效国珍。","海宇承流波尽息，文坛司命士仍亲。","圣恩若遂需丞弼，杼轴东南正可陈。"]},{"t":"答友人西游见寄","f":"七言律诗","c":["远道何由折简呼，花前曾记伴提壶。","书邮渐讶八行少，诗债才偿一事无。","留客江山知信美，怀人风月隔欢娱。","几回欲报加餐字，西岭云深雁影孤。"]},{"t":"送高学谕致政还江右二首 其一","f":"七言律诗","c":["二载山城雨露初，薰风远道送征车。","拂衣未是嫌官冷，垂橐无须问禄馀。","邹鲁泽成桃李荫，苏湖经就草茅书。","阶前玉树凌霄发，会有青藜共石渠。"]},{"t":"送高学谕致政还江右二首 其二","f":"七言律诗","c":["南来造士见功高，湖海元龙气尚豪。","不为三鳣糜岁月，却随一鹤返林皋。","归来满径犹松菊，别去环门自李桃。","即拟宫衣荣彩服，何须白马恋青袍。"]},{"t":"答黄用砺明府","f":"七言律诗","c":["倦游敢道息图南，白社诗篇癖自耽。","天地风尘元易厌，渔樵生计也曾谙。","五湖新水供垂钓，三径閒云引盍簪。","知尔玄言今既就，问奇谁复似桓谭。"]},{"t":"与王令公喜诸生新进","f":"七言律诗","c":["文星夜灿碧云头，挟策翩翩喜见收。","选里并为新秀士，环桥争羡小瀛洲。","三千待奏公车牍，九万将腾海国秋。","异日荐贤推上赏，岂惭车马锡诸侯。"]},{"t":"送丁明府之西粤","f":"七言律诗","c":["两粤云山路不遥，临岐休道别魂销。","菁莪百里河同润，桃李三城春自饶。","暑雨闾阎需抚字，光风庭院隔招邀。","仙凫会见凌霄起，竹马重迎荷圣朝。"]},{"t":"寄题顺德双塔","f":"七言律诗","c":["城南千尺驾虹桥，桥下江声旦暮潮。","云际何来双玉笋，雨馀忽对两霞标。","地灵终古文成象，词客高秋赋屡招。","倚槛天风吹万里，即看鹏翼共扶摇。"]},{"t":"答董叔远","f":"七言律诗","c":["襄野何从访具茨，白云无地不心怡。","几年道路松荒日，一径蓬蒿鸟倦时。","天子尚思游猎赋，硕人偏爱考槃诗。","秋光亦自堪娱客，可负尊前菊满篱。"]},{"t":"寄寿林左史九十","f":"七言律诗","c":["一自投簪逸海滨，壶山烟月自为邻。","林泉养邃三朝硕，龟鹤龄开九十春。","末路浮名庄叟达，初筵宾戒武公陈。","天将遐算优遗老，况复琼枝雨露新。"]},{"t":"雄州陈司理考绩","f":"七言律诗","c":["几度梅花对法曹，岭头春雪唱逾高。","朗陵聚后星为福，肺石清来目屡蒿。","侍从频年虚召对，平反今日正书劳。","趋朝便拟看花去，为问玄都观里桃。"]},{"t":"为罗甥寿其伯典仪君","f":"七言律诗","c":["几人方外得罗含，春酒如渑傍菊潭。","修竹念年经兔苑，德星今夕聚狐南。","传家自美青云馆，招隐难忘白石庵。","群从阶庭富兰玉，更容小阮共清酣。"]},{"t":"答友人九日客中见怀","f":"七言律诗","c":["九日秋光映远峰，每缘觞咏忆相逢。","黄花节序家千里，浊酒乡心路几重。","东道却宜山色美，西园犹记露华浓。","问君倒屣多容接，得似陶家三径松。"]},{"t":"送周士宾春试","f":"七言律诗","c":["同学犹能忆少年，却惭天路着鞭先。","君当礼乐千言就，我厌风尘万态捐。","游猎正陈天子赋，抚军谁觅孝廉船。","曲江旧事知无补，看尔登瀛望亦仙。"]},{"t":"答诸叔侄劝驾二首 其一","f":"七言律诗","c":["远道迢遥忆帝城，懒从潘岳赋西征。","自非白社皆尘境，独有青山不世情。","客路烟波愁易倦，閒居风月喜双清。","竹林小阮偏多兴，我亦沙鸥恋旧盟。"]},{"t":"答诸叔侄劝驾二首 其二","f":"七言律诗","c":["回首风尘满凤城，朔云不断雁南征。","游人自厌冰霜苦，倦客偏多湖海情。","闭户已能甘寂寞，登车谁与共澄清。","谢家群从多兰玉，次第还参上国盟。"]},{"t":"送何观察入贺","f":"七言律诗","c":["海国风清岁晏如，喜持金鉴奉宸居。","万方玉帛趋王会，五夜星辰记直庐。","恩重紫骝辞汉阙，礼成青鸟报潘舆。","春明莫恋斑衣里，多少蒸黎待属车。"]},{"t":"赠刘提盐署郡捕","f":"七言律诗","c":["三城苍赤幸依刘，筹策兵农事事优。","万灶牢盘供裕国，一方锁钥佐为州。","官閒未比曹疑马，俗易行看剑买牛。","盐铁不须持汉议，消弭兼颂富民侯。"]},{"t":"柏茂蒲芳图寿周宪副","f":"七言律诗","c":["早年三径遂鸿冥，柏实蒲香学制龄。","直干长留千尺黛，灵根不断四时青。","乌栖朱博台中府，鹤舞安期涧畔亭。","耆社只今尊洛下，太丘门更聚群星。"]},{"t":"游氏迎晖堂","f":"七言律诗","c":["鸡鸣晓日映扶桑，万里烟消见曙光。","影动楼台初上下，色增台构共苍凉。","中天瑞霭开长夜，满地清晖豁大荒。","最是飞腾宜凤羽，先从海外得朝阳。"]},{"t":"锦江春色图","f":"七言律诗","c":["万里休嗟蜀道难，披图春色满江干。","烟开巫峡峰千叠，花接岷峨树几盘。","金马岧峣苍霭合，青羊占候紫云宽。","何当舣棹星桥下，草阁琴台载酒看。"]},{"t":"送萧孝廉初上春官","f":"七言律诗","c":["五云翘首望金台。","万里群游亦壮哉。","江月满船催晓发，岭梅迎骑报春魁。","山中豹变开玄雾，浪里龙吟起蛰雷。","最是登瀛需妙选，泥金消息待南来。"]},{"t":"题鹤南飞图寿陈勋卿","f":"七言律诗","c":["图南羽翼出尘寰，矫首层霄未易攀。","琴伴昔年游蜀道，笙吹何日到缑山。","九皋闻野风前听，千岁巢松月下还。","谁解穿云调玉笛，苏仙文物正堪班。"]},{"t":"归粤寿母卷为马仲高作","f":"七言律诗","c":["万里观光入帝畿，瞻云犹自恋春晖。","总缘罔极怀明发，岂为羁愁赋式微。","璧水桥门推论难，平津阁道见知希。","归来慈母看缝线，片片天香染彩衣。"]},{"t":"陈勋卿招饮龙津别墅先遗长篇赋谢","f":"七言律诗","c":["折简重来忆隔年，深尊容我复谈天。","杯前云影千行雁，棋里秋声几树蝉。","双屐东山游暂卧，盈门北海坐常延。","诗情更觉飞扬甚，彩笔先悬白雪篇。"]},{"t":"送举主何侍御还京","f":"七言律诗","c":["闽海当年奉属车，姓名叨列荐贤书。","周南迹滞登龙后，冀北群惭相马初。","大泽风雷愁魍魉，閒居岁月傍樵渔。","孤臣恋阙心犹在，已逐前旌梦玉除。"]},{"t":"和体韶妹丈劝发","f":"七言律诗","c":["几年泉石托清流，差胜尘途感百忧。","苦为交亲辞野服，又随京国梦宸旒。","山间木叶催寒序，径里花枝恋酒筹。","更美莼鲈思缓发，免教长路即悲秋。"]},{"t":"诸叔侄兄弟携具促发赋别","f":"七言律诗","c":["几载郊居罢远游，复劳相赠看吴钩。","祗因汗漫思湖海，更逐风尘应马牛。","竹叶临岐催去棹，芦花和雁宿前洲。","閒身又判从人没，敢向天涯咏四愁。"]},{"t":"答亲友赠别十九首 其一","f":"七言律诗","c":["归来似为厌时名，又听阳关送别声。","得丧漫同失马叟，去还宁比弃繻生。","惭余浪迹过三仕，喜尔雄文重二京。","莫遣风尘双鬓改，东隅犹及见功成。"]},{"t":"答亲友赠别十九首 其二","f":"七言律诗","c":["幽居曾傍水云开，已分清时只草莱。","最是亲朋工劝驾，非关廊庙远抡才。","天閒拟共驰中驷，列宿还从望上台。","握手慇勤各持赠，多君别赋旅中裁。"]},{"t":"答亲友赠别十九首 其三","f":"七言律诗","c":["瞻天万里觉途长，叠尽阳关酒一觞。","处处江山人是客，盈盈秋水露为霜。","朋游上国多鹓侣，鞭弭中原有雁行。","山鬼笑人君莫讶，楚舆犹为凤歌狂。"]},{"t":"答亲友赠别十九首 其四","f":"七言律诗","c":["为园久拟著潜夫，惭愧当年屡剖符。","圣世几曾需俗吏，公车元自盛文儒。","天涯预叹书邮杳，斗下翻疑剑气孤。","迟尔赋成须诣阙，早看鲲运试南图。"]},{"t":"答亲友赠别十九首 其五","f":"七言律诗","c":["江湖漂泊隔鹓班，草野何知觐圣颜。","被褐似从方外至，鸣珂仍向日边还。","鹍鹏敢谓搏南海，猿鹤先教怨北山。","试问弹冠当早晚，未应长恋钓鱼湾。"]},{"t":"答亲友赠别十九首 其六","f":"七言律诗","c":["尘途老我仍脂辖，艺苑多君擅斲轮。","拙宦久孤金结士，神交偏羡玉为人。","驱驰自觉风霜久，岁月相期雨露新。","自是同声怜去住，故传篇咏到通津。"]},{"t":"答亲友赠别十九首 其七","f":"七言律诗","c":["拟因遗世谢浮名，颇为傍人笑独清。","岂比隋珠能照乘，敢方赵璧抵连城。","仍为小草惭羁旅，已就长杨羡墨卿。","时事正须幽侧问，治安何日奏承明。"]},{"t":"答亲友赠别十九首 其八","f":"七言律诗","c":["飘摇征袂拂霜寒，老大深惭独据鞍。","至后喜看时渐改，行边不记路曾难。","裘怜季子尘中久，铗笑冯生暗里弹。","尘世几人堪共济，怀香应待谢家兰。"]},{"t":"答亲友赠别十九首 其九","f":"七言律诗","c":["草堂无事只科头，谁遣膏车赋远游。","开径转应怜仲蔚，轻舟难复似王猷。","因耽薄禄居频卜，久识微名世共浮。","明到蓟城春未晚，与谁觞咏散乡愁。"]},{"t":"答亲友赠别十九首 其十","f":"七言律诗","c":["衡门幽寂久烟萝，又赋骊驹兴玉珂。","往事只看云共散，致贤难俟礼为罗。","人情黯淡遭时晚，宦绩优游较孰多。","似尔林泉堪寄傲，南山休续饭牛歌。"]},{"t":"答亲友赠别十九首 其十一","f":"七言律诗","c":["江头彩鹢应潮开，犹记龙津月下台。","桂树有丛淹作赋，菊花留径狎传杯。","中朝事业推耆旧，末路蹉跎愧不才。","孤剑斗光明灭半，五云何日傍三台。"]},{"t":"答亲友赠别十九首 其十二","f":"七言律诗","c":["樽酒河梁忆路岐，海天风雨正纷披。","鹿门已道终遗世，狗监何心更遇时。","升斗逢迎衣食累，关山迢递鹤琴知。","公车岁岁徵贤硕，草野能无念国危。"]},{"t":"答亲友赠别十九首 其十三","f":"七言律诗","c":["念载驱驰道路难，买邻曾借一枝安。","暂违松菊先生里，敢附风云国士坛。","蜀赋祗今危鸟道，楚歌元自爱幽兰。","山中猿鹤君能主，莫拟移文异日看。"]},{"t":"答亲友赠别十九首 其十四","f":"七言律诗","c":["閒居水石差怡性，恋阙驺车又戒途。","已愧朝阳冈上凤，漫随波泛水中凫。","考槃羡尔开三径，作赋令人重两都。","康济并需岩穴士，先忧宁道只江湖。"]},{"t":"答亲友赠别十九首 其十五","f":"七言律诗","c":["忆昔分符海上城，寸心无日不悬旌。","官同即墨宁干誉，政比丹徒却坐清。","拙宦久劳州郡职，汉庭多薄少年生。","蛾眉渐老应销妒，启事何当辱鉴衡。"]},{"t":"答亲友赠别十九首 其十六","f":"七言律诗","c":["千古东山慕谢安，蓬蒿一径岂同看。","玄言并拟幽人宅，赤帜谁堪大将坛。","霜映万枫帆影度，斗连五夜剑光寒。","悠悠燕粤音书隔，期尔方弹贡禹冠。"]},{"t":"答亲友赠别十九首 其十七","f":"七言律诗","c":["祖道不堪乡土别，绨袍偏恋故人心。","祗缘慷慨思燕筑，却任漂零作越吟。","白社几年曾伴月，苍生何处拟为霖。","疏才薄宦知无补，竹户谁开待抱琴。"]},{"t":"答亲友赠别十九首 其十八","f":"七言律诗","c":["落月常悬照屋梁，临岐不得共持觞。","藏珍敢谓明时重，伏枥仍期知己良。","万里关山重作客，十年漂泊老为郎。","弓旌何日求岩穴，召对看君入帝乡。"]},{"t":"答亲友赠别十九首 其十九","f":"七言律诗","c":["醇交自昔推公瑾，诗伴如君复建安。","再向风尘驱下走，又从羁旅对南冠。","衡门水石思仍系，客路星霜迥自寒。","但道时艰须共济，过都迟尔路非难。"]},{"t":"岁寒松柏图","f":"七言律诗","c":["朔气能寒海上山，却留苍翠倚云间。","时看舞鹤笙前下，长听栖乌月里还。","天泽九重承自远，霜标千仞渺难攀。","休疑绿鬓年年好，柏实松苓总驻颜。"]},{"t":"舟行值雨","f":"七言律诗","c":["长江烟雨泛兰桡，极目关山万里遥。","踪迹重违门外柳，功名犹是梦中蕉。","客来转忆孤山鹤，寒至偏侵季子貂。","何日功成归绿野，丛林丰草任渔樵。"]},{"t":"度庾岭逢雪","f":"七言律诗","c":["重游不似旧看山，满目琼瑶应接间。","好拟新篇歌郢里，莫将匹马比蓝关。","山阴月色扁舟往，江上渔歌独钓还。","此日寒云征路满，驱驰难任意同閒。"]},{"t":"取道浙行值岁方暮","f":"七言律诗","c":["岁暮阴阳羁旅泊，天涯泉石梦郊居。","红尘再拟看花会，白社初抛种树书。","适越有怀探禹穴，浮江无用吊三闾。","春来依旧王孙道，芳草东风不负余。"]}]};